"use client"

import * as React from "react"

import { PlainTextViewerFrame } from "./plain-text-viewer-frame"
import { PretextMarkdownGreenfieldContent } from "./pretext-markdown-greenfield-content"
import { TextViewerFallback } from "./text-viewer-chrome"
import type { TextViewerHandle, TextViewerProps } from "./text-viewer-types"

export type {
  TextDocumentSource,
  TextLineRange,
  TextViewerHandle,
  TextViewerProps,
} from "./text-viewer-types"

export const PretextMarkdownViewer = React.forwardRef<
  TextViewerHandle,
  TextViewerProps
>(function PretextMarkdownViewer(props, ref) {
  return (
    <PlainTextViewerFrame
      props={props}
      forwardedRef={ref}
      clientFallbackPolicy="non-inline-source"
      Fallback={TextViewerFallback}
      Content={PretextMarkdownGreenfieldContent}
    />
  )
})

"use client"

import * as React from "react"
import { ChevronDown, ChevronUp, Search, X } from "lucide-react"

import type { ViewerResource } from "@/lib/viewer-resource"

import {
  createPretextMarkdownGreenfieldDocument,
  findPretextMarkdownGreenfieldChunkByBlockId,
  findPretextMarkdownGreenfieldChunkBySourceLine,
  findPretextMarkdownGreenfieldFragmentTargetById,
  type PretextMarkdownGreenfieldChunk,
} from "./pretext-markdown-greenfield-document"
import {
  layoutPretextMarkdownGreenfieldDocument,
  PRETEXT_MARKDOWN_GREENFIELD_LAYOUT_POLICY_VERSION,
  type PretextMarkdownGreenfieldChunkFrame,
  type PretextMarkdownGreenfieldMeasurementContext,
} from "./pretext-markdown-greenfield-layout"
import { PretextMarkdownGreenfieldChunkRenderer } from "./pretext-markdown-greenfield-renderer"
import {
  getPretextMarkdownGreenfieldScrollAnchor,
  getPretextMarkdownGreenfieldScrollTopForLineRange,
  getPretextMarkdownGreenfieldSourceLineForScrollTop,
  getPretextMarkdownGreenfieldVisibleFrames,
  resolvePretextMarkdownGreenfieldScrollAnchor,
  type PretextMarkdownGreenfieldScrollAnchor,
} from "./pretext-markdown-greenfield-virtualizer"
import type {
  PretextMarkdownHastElement,
  PretextMarkdownHastNode,
} from "./pretext-markdown-hast-types"
import { ScrollArea } from "./scroll-area"
import { TextViewerControls, TextViewerFrame } from "./text-viewer-chrome"
import { normalizeTextLineRange } from "./text-viewer-ranges"
import {
  readTextResource,
  resolvedTextViewerBounds,
  splitTextLines,
} from "./text-viewer-resource"
import { clampTextViewerScale } from "./text-viewer-scale"
import type { TextViewerHandle, TextViewerProps } from "./text-viewer-types"
import type { ViewerDownloadErrorHandler } from "./viewer-download"

const DEFAULT_VIEWPORT_HEIGHT = 640
const DEFAULT_VIEWPORT_WIDTH = 900
const INITIAL_CONTENT_WIDTH = 820
const VIEWER_HORIZONTAL_PADDING = 32
const OVERSCAN_PX = 800
const SOURCE_LINE_HEIGHT = 22
const MAX_SEARCH_MATCHES = 10_000

type PretextMarkdownGreenfieldViewMode = "rendered" | "source"

type ViewportSize = {
  height: number
  width: number
}

type PretextMarkdownSearchMatch = {
  endLine: number
  endOffset: number
  index: number
  startLine: number
  startOffset: number
}

type PretextMarkdownScrollToLineOptions = ScrollToOptions & {
  preferredChunkId?: string | null
}

export function PretextMarkdownGreenfieldContent({
  resource,
  className,
  controls = true,
  download = true,
  highlight,
  bare = false,
  maxBytes,
  maxLines,
  retryVersion,
  forwardedRef,
}: TextViewerProps & {
  resource: ViewerResource
  retryVersion: number
  forwardedRef?: React.ForwardedRef<TextViewerHandle>
}) {
  const bounds = React.useMemo(
    () => resolvedTextViewerBounds({ maxBytes, maxLines }),
    [maxBytes, maxLines]
  )
  const text = React.useMemo(
    () =>
      readTextResource({
        bounds,
        content: resource.content,
        retryVersion,
      }),
    [bounds, resource.content, retryVersion]
  )
  const document = React.useMemo(
    () => createPretextMarkdownGreenfieldDocument(text),
    [text]
  )
  const documentMeasurementId = React.useMemo(
    () => measurementDocumentIdForText(text),
    [text]
  )
  const sourceLines = React.useMemo(() => splitTextLines(text), [text])
  const downloadAction = download ? resource.originalDownload : null
  const [downloadError, setDownloadError] = React.useState("")
  const [fontScale, setFontScale] = React.useState(1)
  const [measuredHeights, setMeasuredHeights] = React.useState(
    () => new Map<string, number>()
  )
  const [scrollTop, setScrollTop] = React.useState(0)
  const [viewMode, setViewMode] =
    React.useState<PretextMarkdownGreenfieldViewMode>("rendered")
  const [viewportSize, setViewportSize] = React.useState<ViewportSize>({
    height: 0,
    width: 0,
  })
  const [contentWidth, setContentWidth] = React.useState(INITIAL_CONTENT_WIDTH)
  const viewportRef = React.useRef<HTMLDivElement | null>(null)
  const pendingAnchorRef =
    React.useRef<PretextMarkdownGreenfieldScrollAnchor | null>(null)
  const prevFrameChunksRef = React.useRef<
    readonly PretextMarkdownGreenfieldChunkFrame[] | null
  >(null)
  const pendingModeSourceLineRef = React.useRef<number | null>(null)
  const viewportHeight = viewportSize.height || DEFAULT_VIEWPORT_HEIGHT
  const viewportWidth = viewportSize.width || DEFAULT_VIEWPORT_WIDTH
  const sourceLineHeight = SOURCE_LINE_HEIGHT * fontScale
  const measuredHeightLookup = React.useMemo(
    () => ({
      get: (
        chunk: PretextMarkdownGreenfieldChunk,
        context: PretextMarkdownGreenfieldMeasurementContext
      ) =>
        measuredHeights.get(
          measuredHeightKey({
            chunk,
            context,
            documentMeasurementId,
          })
        ),
    }),
    [documentMeasurementId, measuredHeights]
  )
  const frame = React.useMemo(
    () =>
      layoutPretextMarkdownGreenfieldDocument({
        contentWidth,
        document,
        fontScale,
        measuredHeights: measuredHeightLookup,
      }),
    [contentWidth, document, fontScale, measuredHeightLookup]
  )
  const highlightRange = React.useMemo(
    () => normalizeTextLineRange(highlight, document.lineCount),
    [document.lineCount, highlight]
  )
  const {
    activeSearchMatch,
    activeSearchRange,
    clearSearch,
    goToSearchMatch,
    searchMatches,
    searchQuery,
    setSearchQuery,
  } = useMarkdownSearch({ lineCount: document.lineCount, text })
  const visibleHighlightRange = activeSearchRange ?? highlightRange
  // Locate the toolbar's current match within its chunk so the renderer can
  // mark that single occurrence active. Matches are in document order, so the
  // chunk-local index is the global index minus the matches in earlier chunks.
  const activeMatchLocation = React.useMemo(() => {
    if (!activeSearchMatch) return null
    const chunkFrame = frame.chunks.find(
      (candidate) =>
        candidate.sourceStartLine <= activeSearchMatch.startLine &&
        activeSearchMatch.startLine <= candidate.sourceEndLine
    )
    if (!chunkFrame) return null
    const matchesBeforeChunk = searchMatches.filter(
      (match) => match.startLine < chunkFrame.sourceStartLine
    ).length
    return {
      chunkIndex: chunkFrame.index,
      occurrence: activeSearchMatch.index - matchesBeforeChunk,
    }
  }, [activeSearchMatch, frame.chunks, searchMatches])
  const visibleFrames = React.useMemo(
    () =>
      getPretextMarkdownGreenfieldVisibleFrames({
        frames: frame.chunks,
        overscanPx: OVERSCAN_PX,
        scrollTop,
        viewportHeight,
      }),
    [frame.chunks, scrollTop, viewportHeight]
  )
  const captureAnchor = React.useCallback(() => {
    // Read the live scroll position from the DOM rather than the `scrollTop`
    // state, which lags behind during fast scrolling. Capturing a stale value
    // here makes the anchor-restore effect yank the viewport back to an old
    // (often near-top) position when a freshly revealed chunk is measured.
    const liveScrollTop = viewportRef.current?.scrollTop ?? scrollTop
    pendingAnchorRef.current = getPretextMarkdownGreenfieldScrollAnchor({
      frames: frame.chunks,
      scrollTop: liveScrollTop,
    })
  }, [frame.chunks, scrollTop])

  React.useLayoutEffect(() => {
    setMeasuredHeights(new Map())
    setScrollTop(0)
    viewportRef.current?.scrollTo({ left: 0, top: 0 })
  }, [document])

  React.useLayoutEffect(() => {
    const viewport = viewportRef.current
    if (!viewport) return

    const readSize = () => {
      setViewportSize((current) => {
        const next = {
          height: viewport.clientHeight,
          width: viewport.clientWidth,
        }
        return current.height === next.height && current.width === next.width
          ? current
          : next
      })
    }

    readSize()
    const observer =
      typeof ResizeObserver === "undefined"
        ? null
        : new ResizeObserver(readSize)
    observer?.observe(viewport)
    return () => observer?.disconnect()
  }, [])

  React.useLayoutEffect(() => {
    const nextWidth = Math.max(1, viewportWidth - VIEWER_HORIZONTAL_PADDING * 2)
    setContentWidth((current) => {
      if (current === nextWidth) return current
      captureAnchor()
      return nextWidth
    })
  }, [captureAnchor, viewportWidth])

  React.useLayoutEffect(() => {
    const viewport = viewportRef.current
    const previousChunks = prevFrameChunksRef.current
    prevFrameChunksRef.current = frame.chunks
    if (!viewport) return

    // Intentional full reflows (width, zoom, font readiness, mode switch) set an
    // explicit anchor and want to restore the reader's relative position.
    const anchor = pendingAnchorRef.current
    if (anchor) {
      pendingAnchorRef.current = null
      const nextScrollTop = resolvePretextMarkdownGreenfieldScrollAnchor({
        anchor,
        frames: frame.chunks,
      })
      if (nextScrollTop == null) return
      viewport.scrollTop = nextScrollTop
      setScrollTop(nextScrollTop)
      return
    }

    // Measurement-driven changes keep whatever the reader is looking at stable by
    // compensating scrollTop for the height delta of chunks ENTIRELY above the
    // viewport top. Only already-measured chunks (real height in both layouts)
    // count: a chunk's first estimate->measured correction happens as it is
    // revealed near/below the viewport, never while the reader sits above it, so
    // excluding it avoids the estimate-collapse plunge while still pinning the
    // viewport when async rich blocks above re-settle.
    if (!previousChunks) return
    const liveScrollTop = viewport.scrollTop
    const previousById = new Map(
      previousChunks.map((chunkFrame) => [chunkFrame.id, chunkFrame])
    )
    let delta = 0
    for (const chunkFrame of frame.chunks) {
      const previous = previousById.get(chunkFrame.id)
      if (
        previous &&
        previous.measuredHeight != null &&
        chunkFrame.measuredHeight != null &&
        previous.bottom <= liveScrollTop
      ) {
        delta += chunkFrame.measuredHeight - previous.measuredHeight
      }
    }
    if (delta === 0) return
    const nextScrollTop = Math.max(0, liveScrollTop + delta)
    viewport.scrollTop = nextScrollTop
    setScrollTop(nextScrollTop)
  }, [frame.chunks])

  const scrollToLineRange = React.useCallback(
    (
      range: ReturnType<typeof normalizeTextLineRange>,
      options?: PretextMarkdownScrollToLineOptions
    ) => {
      const viewport = viewportRef.current
      if (!viewport || !range) return

      const preferredChunkId =
        options?.preferredChunkId ??
        findPretextMarkdownGreenfieldChunkBySourceLine(document, range.start)
          ?.id
      const top =
        viewMode === "source"
          ? (range.start - 1) * sourceLineHeight
          : getPretextMarkdownGreenfieldScrollTopForLineRange({
              chunks: document.chunks,
              frames: frame.chunks,
              preferredChunkId,
              range,
              viewportHeight: viewport.clientHeight || viewportHeight,
            })
      if (top == null) return
      viewport.scrollTo({
        behavior: resolveScrollBehavior(options?.behavior),
        left: options?.left,
        top,
      })
      setScrollTop(top)
    },
    [document, frame.chunks, sourceLineHeight, viewMode, viewportHeight]
  )

  // A stable handle to the latest scrollToLineRange. The callback's identity
  // changes on every layout change (its deps include frame.chunks), so effects
  // that should fire only when their *target* changes must not depend on it
  // directly — otherwise each measurement re-runs them and yanks the viewport
  // back to the highlight/search/hash target while the reader is scrolling.
  const scrollToLineRangeRef = React.useRef(scrollToLineRange)
  React.useLayoutEffect(() => {
    scrollToLineRangeRef.current = scrollToLineRange
  }, [scrollToLineRange])

  React.useImperativeHandle(
    forwardedRef ?? null,
    () => ({
      getViewportElement: () => viewportRef.current,
      scrollToLineRange: (range, options) => {
        scrollToLineRangeRef.current(
          normalizeTextLineRange(range, document.lineCount),
          options
        )
      },
    }),
    [document.lineCount]
  )

  // Scrolling is an imperative DOM mutation that must run before paint to avoid
  // a visible jump, so these reactions to a changed target line/range live in
  // layout effects, not useEffect.
  React.useLayoutEffect(() => {
    if (!highlightRange) return
    scrollToLineRangeRef.current(highlightRange)
  }, [highlightRange])

  React.useLayoutEffect(() => {
    if (!activeSearchRange) return
    scrollToLineRangeRef.current(activeSearchRange, { behavior: "auto" })
  }, [activeSearchRange])

  // Subscribes to the browser's hash/history (a non-React external source) and
  // scrolls the matching fragment into view before paint.
  React.useLayoutEffect(() => {
    const scrollToCurrentHash = () => {
      const hash = window.location.hash
      if (!hash) return
      const target = findPretextMarkdownGreenfieldFragmentTargetById(
        document,
        hash
      )
      if (!target) return
      const chunk = findPretextMarkdownGreenfieldChunkByBlockId(
        document,
        target.blockId
      )
      scrollToLineRangeRef.current(
        normalizeTextLineRange(
          { end: target.sourceLine, start: target.sourceLine },
          document.lineCount
        ),
        { behavior: "auto", preferredChunkId: chunk?.id }
      )
    }

    scrollToCurrentHash()
    window.addEventListener("hashchange", scrollToCurrentHash)
    window.addEventListener("popstate", scrollToCurrentHash)
    return () => {
      window.removeEventListener("hashchange", scrollToCurrentHash)
      window.removeEventListener("popstate", scrollToCurrentHash)
    }
  }, [document])

  React.useLayoutEffect(() => {
    const sourceLine = pendingModeSourceLineRef.current
    if (sourceLine == null) return
    pendingModeSourceLineRef.current = null
    scrollToLineRange(
      normalizeTextLineRange(
        { end: sourceLine, start: sourceLine },
        document.lineCount
      ),
      { behavior: "auto" }
    )
  }, [document.lineCount, scrollToLineRange, viewMode])

  const recordMeasuredHeight = React.useCallback(
    (chunk: PretextMarkdownGreenfieldChunk, height: number) => {
      if (!Number.isFinite(height) || height <= 0) return
      const key = measuredHeightKey({
        chunk,
        context: {
          fontScale,
          policyVersion: PRETEXT_MARKDOWN_GREENFIELD_LAYOUT_POLICY_VERSION,
          width: Math.max(1, contentWidth),
        },
        documentMeasurementId,
      })
      setMeasuredHeights((current) => {
        if (Math.abs((current.get(key) ?? 0) - height) < 1) return current
        const next = new Map(current)
        next.set(key, height)
        return next
      })
    },
    [contentWidth, documentMeasurementId, fontScale]
  )
  const handleDownloadError = React.useCallback<ViewerDownloadErrorHandler>(
    (error) => {
      if (error.kind === "aborted") return
      setDownloadError(error.message || "Could not download Markdown.")
    },
    []
  )
  const switchMode = (nextMode: PretextMarkdownGreenfieldViewMode) => {
    if (nextMode === viewMode) return
    const currentScrollTop = viewportRef.current?.scrollTop ?? scrollTop
    pendingModeSourceLineRef.current =
      viewMode === "source"
        ? Math.max(1, Math.floor(currentScrollTop / sourceLineHeight) + 1)
        : getPretextMarkdownGreenfieldSourceLineForScrollTop({
            chunks: document.chunks,
            frames: frame.chunks,
            scrollTop: currentScrollTop,
          })
    setViewMode(nextMode)
  }
  const zoom = (factor: number) => {
    captureAnchor()
    setFontScale((scale) => clampTextViewerScale(scale * factor))
  }
  const resetZoom = () => {
    captureAnchor()
    setFontScale(1)
  }

  return (
    <TextViewerFrame className={className} bare={bare}>
      {controls ? (
        <TextViewerControls
          copyLabel="Copy Markdown"
          copyText={document.text}
          downloadAction={downloadAction}
          extra={
            <span className="flex min-w-0 items-center gap-2">
              <DownloadError message={downloadError} />
              <PretextMarkdownSearchControl
                activeMatchIndex={
                  activeSearchMatch ? activeSearchMatch.index : 0
                }
                matchCount={searchMatches.length}
                query={searchQuery}
                onClear={clearSearch}
                onNext={() => goToSearchMatch(1)}
                onPrevious={() => goToSearchMatch(-1)}
                onQueryChange={setSearchQuery}
              />
            </span>
          }
          fontScale={fontScale}
          leading={
            <ViewModeControl
              mode={viewMode}
              wordCount={document.wordCount}
              onModeChange={switchMode}
            />
          }
          wordCount={document.wordCount}
          onDownloadError={handleDownloadError}
          onResetZoom={resetZoom}
          onZoomIn={() => zoom(1.2)}
          onZoomOut={() => zoom(1 / 1.2)}
        />
      ) : null}
      {/* overflow-anchor:none disables the browser's native scroll anchoring,
          which otherwise fights this component's virtualization: as chunks
          mount/unmount and the canvas height corrects, the browser shifts
          scrollTop on its own, jerking the viewport while the reader scrolls. */}
      <ScrollArea
        className="min-h-0 flex-1 bg-background"
        orientation="vertical"
        viewportClassName="bg-background [overflow-anchor:none]"
        viewportRef={viewportRef}
        viewportProps={{
          onClickCapture:
            viewMode === "rendered"
              ? (event) =>
                  handleRenderedClick({ document, event, scrollToLineRange })
              : undefined,
          onScroll: (event) => setScrollTop(event.currentTarget.scrollTop),
        }}
      >
        {viewMode === "source" ? (
          <div
            className="relative min-w-max bg-background"
            data-slot="pretext-markdown-source-scroll-canvas"
            style={{
              height:
                Math.max(sourceLines.length, 1) *
                SOURCE_LINE_HEIGHT *
                fontScale,
              minWidth: viewportWidth,
            }}
          >
            <SourceCanvas
              fontScale={fontScale}
              highlightRange={visibleHighlightRange}
              lines={sourceLines}
              scrollTop={scrollTop}
              viewportHeight={viewportHeight}
            />
          </div>
        ) : (
          <div
            className="relative min-w-0"
            data-projection="unified-hast-pretext-markdown"
            data-slot="pretext-markdown-virtual-canvas"
            style={{
              height: Math.max(frame.totalHeight, viewportHeight),
              minWidth: viewportWidth,
            }}
          >
            <NativeFindIndex
              chunks={document.chunks}
              lineCount={document.lineCount}
              scrollToLineRange={scrollToLineRange}
            />
            {document.text.trim() ? (
              visibleFrames.map((chunkFrame) => {
                const chunk = document.chunks[chunkFrame.index]
                if (!chunk) return null
                return (
                  <ChunkFrame
                    key={chunk.id}
                    chunk={chunk}
                    frame={chunkFrame}
                    highlightRange={visibleHighlightRange}
                    highlighted={chunkIntersectsLineRange({
                      chunkFrame,
                      range: visibleHighlightRange,
                    })}
                    measurementKey={measuredHeightKey({
                      chunk,
                      context: {
                        fontScale,
                        policyVersion:
                          PRETEXT_MARKDOWN_GREENFIELD_LAYOUT_POLICY_VERSION,
                        width: Math.max(1, contentWidth),
                      },
                      documentMeasurementId,
                    })}
                    onMeasuredHeight={recordMeasuredHeight}
                  >
                    <PretextMarkdownGreenfieldChunkRenderer
                      activeMatchOccurrence={
                        activeMatchLocation?.chunkIndex === chunk.index
                          ? activeMatchLocation.occurrence
                          : undefined
                      }
                      chunk={chunk}
                      fontScale={fontScale}
                      onContentReady={() =>
                        measureChunkFrame(chunk, recordMeasuredHeight)
                      }
                      searchQuery={searchQuery}
                    />
                  </ChunkFrame>
                )
              })
            ) : (
              <div
                aria-label="Empty Markdown document"
                className="absolute inset-x-4 top-0 flex min-h-40 items-center justify-center text-sm text-muted-foreground"
                data-slot="pretext-markdown-empty-state"
                role="status"
              >
                Empty Markdown document
              </div>
            )}
          </div>
        )}
      </ScrollArea>
    </TextViewerFrame>
  )
}

function NativeFindIndex({
  chunks,
  lineCount,
  scrollToLineRange,
}: {
  chunks: readonly PretextMarkdownGreenfieldChunk[]
  lineCount: number
  scrollToLineRange: (
    range: ReturnType<typeof normalizeTextLineRange>,
    options?: PretextMarkdownScrollToLineOptions
  ) => void
}) {
  return (
    <div
      aria-hidden="true"
      className="pointer-events-none absolute top-0 left-0 h-px w-px overflow-hidden opacity-0"
      data-slot="pretext-markdown-native-find-index"
    >
      {chunks.map((chunk) => (
        <NativeFindEntry
          key={chunk.id}
          chunk={chunk}
          lineCount={lineCount}
          scrollToLineRange={scrollToLineRange}
        />
      ))}
    </div>
  )
}

function NativeFindEntry({
  chunk,
  lineCount,
  scrollToLineRange,
}: {
  chunk: PretextMarkdownGreenfieldChunk
  lineCount: number
  scrollToLineRange: (
    range: ReturnType<typeof normalizeTextLineRange>,
    options?: PretextMarkdownScrollToLineOptions
  ) => void
}) {
  const ref = React.useRef<HTMLSpanElement | null>(null)
  const text = nativeFindTextForChunk(chunk)

  React.useLayoutEffect(() => {
    const element = ref.current
    if (!element) return
    element.setAttribute("hidden", "until-found")

    const handleBeforeMatch = () => {
      scrollToLineRange(
        normalizeTextLineRange(
          {
            end: chunk.sourceEndLine,
            start: chunk.sourceStartLine,
          },
          lineCount
        ),
        { behavior: "auto", preferredChunkId: chunk.id }
      )
      requestAnimationFrame(() => {
        element.setAttribute("hidden", "until-found")
      })
    }

    element.addEventListener("beforematch", handleBeforeMatch)
    return () => {
      element.removeEventListener("beforematch", handleBeforeMatch)
    }
  }, [
    chunk.id,
    chunk.sourceEndLine,
    chunk.sourceStartLine,
    lineCount,
    scrollToLineRange,
  ])

  return (
    <span
      ref={ref}
      className="absolute top-0 left-0 block h-px w-px overflow-hidden whitespace-pre"
      data-native-find-chunk-id={chunk.id}
      data-native-find-end-line={chunk.sourceEndLine}
      data-native-find-start-line={chunk.sourceStartLine}
    >
      {text || " "}
    </span>
  )
}

function nativeFindTextForChunk(chunk: PretextMarkdownGreenfieldChunk) {
  return chunk.hastChildren.map(nativeFindTextForHastNode).join(" ").trim()
}

function nativeFindTextForHastNode(node: PretextMarkdownHastNode): string {
  if (node.type === "text" && typeof node.value === "string") return node.value
  const element = node as PretextMarkdownHastElement
  if (!element || element.type !== "element") return ""

  if (element.tagName === "script" || element.tagName === "style") return ""
  return element.children.map(nativeFindTextForHastNode).join(" ")
}

function ViewModeControl({
  mode,
  wordCount,
  onModeChange,
}: {
  mode: PretextMarkdownGreenfieldViewMode
  wordCount: number
  onModeChange: (mode: PretextMarkdownGreenfieldViewMode) => void
}) {
  return (
    <span className="flex min-w-0 items-center gap-2">
      <span className="hidden text-xs text-muted-foreground tabular-nums sm:inline">
        {wordCount} word{wordCount === 1 ? "" : "s"}
      </span>
      <span
        aria-label="Markdown view mode"
        className="inline-flex overflow-hidden rounded-md border bg-muted/35 p-0.5"
        role="group"
      >
        {(["rendered", "source"] as const).map((item) => (
          <button
            key={item}
            aria-pressed={mode === item}
            className={[
              "h-6 px-2 text-xs font-medium capitalize transition-colors",
              mode === item
                ? "rounded-sm bg-background text-foreground shadow-xs"
                : "text-muted-foreground hover:text-foreground",
            ].join(" ")}
            type="button"
            onClick={() => onModeChange(item)}
          >
            {item === "source" ? "Text" : "Rendered"}
          </button>
        ))}
      </span>
    </span>
  )
}

function DownloadError({ message }: { message: string }) {
  if (!message) return null
  return (
    <span
      className="max-w-48 truncate text-xs text-destructive"
      data-slot="pretext-markdown-download-error"
      role="status"
    >
      {message}
    </span>
  )
}

function PretextMarkdownSearchControl({
  activeMatchIndex,
  matchCount,
  query,
  onClear,
  onNext,
  onPrevious,
  onQueryChange,
}: {
  activeMatchIndex: number
  matchCount: number
  query: string
  onClear: () => void
  onNext: () => void
  onPrevious: () => void
  onQueryChange: (query: string) => void
}) {
  const searchId = React.useId()
  const statusId = React.useId()
  const hasQuery = query.trim().length > 0
  const hasMatches = matchCount > 0
  const status = !hasQuery
    ? "No search"
    : hasMatches
      ? `${Math.min(activeMatchIndex + 1, matchCount)} / ${matchCount}`
      : "No matches"

  return (
    <form
      className="flex min-w-0 items-center gap-1"
      data-slot="pretext-markdown-search"
      role="search"
      onSubmit={(event) => {
        event.preventDefault()
        onNext()
      }}
    >
      <label className="sr-only" htmlFor={searchId}>
        Search Markdown
      </label>
      <span className="relative block w-36 min-w-0 sm:w-44">
        <Search
          aria-hidden="true"
          className="pointer-events-none absolute top-1/2 left-2 size-3.5 -translate-y-1/2 text-muted-foreground"
        />
        <input
          id={searchId}
          aria-describedby={statusId}
          aria-label="Search Markdown"
          className="h-7 w-full rounded-md border bg-background pr-7 pl-7 text-xs transition-colors outline-none placeholder:text-muted-foreground focus-visible:border-ring focus-visible:ring-[3px] focus-visible:ring-ring/50"
          data-slot="pretext-markdown-search-input"
          placeholder="Search"
          type="search"
          value={query}
          onChange={(event) => onQueryChange(event.currentTarget.value)}
          onKeyDown={(event) => {
            if (event.key === "Escape") {
              event.preventDefault()
              onClear()
              return
            }
            if (event.key !== "Enter") return

            event.preventDefault()
            if (event.shiftKey) onPrevious()
            else onNext()
          }}
        />
        {hasQuery ? (
          <button
            aria-label="Clear Markdown search"
            className="absolute top-1/2 right-1 inline-flex size-5 -translate-y-1/2 items-center justify-center rounded-sm text-muted-foreground transition-colors hover:bg-muted hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring focus-visible:outline-none"
            type="button"
            onClick={onClear}
          >
            <X aria-hidden="true" className="size-3.5" />
          </button>
        ) : null}
      </span>
      <span
        id={statusId}
        aria-live="polite"
        className="hidden w-12 text-center text-xs text-muted-foreground tabular-nums sm:inline"
        data-slot="pretext-markdown-search-status"
      >
        {hasQuery ? status : ""}
      </span>
      <button
        aria-label="Previous Markdown search match"
        className="inline-flex size-7 items-center justify-center rounded-md text-muted-foreground transition-colors hover:bg-muted hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring focus-visible:outline-none disabled:pointer-events-none disabled:opacity-50"
        disabled={!hasMatches}
        title="Previous Markdown search match"
        type="button"
        onClick={onPrevious}
      >
        <ChevronUp aria-hidden="true" className="size-4" />
      </button>
      <button
        aria-label="Next Markdown search match"
        className="inline-flex size-7 items-center justify-center rounded-md text-muted-foreground transition-colors hover:bg-muted hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring focus-visible:outline-none disabled:pointer-events-none disabled:opacity-50"
        disabled={!hasMatches}
        title="Next Markdown search match"
        type="button"
        onClick={onNext}
      >
        <ChevronDown aria-hidden="true" className="size-4" />
      </button>
    </form>
  )
}

function ChunkFrame({
  children,
  chunk,
  frame,
  highlightRange,
  highlighted,
  measurementKey,
  onMeasuredHeight,
}: {
  children: React.ReactNode
  chunk: PretextMarkdownGreenfieldChunk
  frame: PretextMarkdownGreenfieldChunkFrame
  highlightRange: { end: number; start: number } | null
  highlighted: boolean
  measurementKey: string
  onMeasuredHeight: (
    chunk: PretextMarkdownGreenfieldChunk,
    height: number
  ) => void
}) {
  const ref = React.useRef<HTMLDivElement | null>(null)

  React.useLayoutEffect(() => {
    measure()
    const element = ref.current
    if (!element || typeof ResizeObserver === "undefined") return
    const observer = new ResizeObserver(measure)
    observer.observe(element)
    return () => observer.disconnect()

    function measure() {
      const element = ref.current
      if (!element) return
      onMeasuredHeight(chunk, element.getBoundingClientRect().height)
    }
  }, [chunk, onMeasuredHeight])

  return (
    <section
      ref={ref}
      aria-label={
        highlighted
          ? `Highlighted source lines ${highlightRange?.start}-${highlightRange?.end}`
          : `Markdown lines ${frame.sourceStartLine} to ${frame.sourceEndLine}`
      }
      className={[
        "absolute left-1/2 w-full max-w-4xl -translate-x-1/2 px-8 py-1",
        highlighted ? "ring-1 ring-primary/25 ring-inset" : "",
      ].join(" ")}
      data-pretext-markdown-chunk=""
      data-pretext-markdown-highlighted={highlighted ? "" : undefined}
      data-pretext-measured-height-key={measurementKey}
      data-source-highlight-end={highlighted ? highlightRange?.end : undefined}
      data-source-highlight-start={
        highlighted ? highlightRange?.start : undefined
      }
      data-source-end-line={frame.sourceEndLine}
      data-source-start-line={frame.sourceStartLine}
      role={highlighted ? "region" : undefined}
      style={{ top: frame.top }}
    >
      {children}
    </section>
  )
}

function SourceCanvas({
  fontScale,
  highlightRange,
  lines,
  scrollTop,
  viewportHeight,
}: {
  fontScale: number
  highlightRange: { end: number; start: number } | null
  lines: readonly string[]
  scrollTop: number
  viewportHeight: number
}) {
  const lineHeight = SOURCE_LINE_HEIGHT * fontScale
  const start = Math.max(0, Math.floor(scrollTop / lineHeight) - 24)
  const end = Math.min(
    lines.length,
    Math.ceil((scrollTop + viewportHeight) / lineHeight) + 24
  )

  return (
    <pre
      aria-label="Markdown source"
      className="absolute inset-x-0 top-0 m-0 min-w-max bg-background font-mono text-[13px] leading-none text-foreground"
      data-slot="pretext-markdown-source-canvas"
      role="region"
      style={{ height: Math.max(lines.length, 1) * lineHeight }}
      tabIndex={0}
    >
      {lines.slice(start, end).map((line, offset) => {
        const lineNumber = start + offset + 1
        const highlighted =
          highlightRange &&
          lineNumber >= highlightRange.start &&
          lineNumber <= highlightRange.end
        return (
          <div
            key={lineNumber}
            className={[
              "absolute inset-x-0 grid grid-cols-[4rem_minmax(0,1fr)] px-4",
              highlighted ? "bg-primary/12" : "",
            ].join(" ")}
            data-source-line={lineNumber}
            style={{
              height: lineHeight,
              lineHeight: `${lineHeight}px`,
              top: (lineNumber - 1) * lineHeight,
            }}
          >
            <span
              aria-hidden="true"
              className="pr-4 text-right text-muted-foreground select-none"
            >
              {lineNumber}
            </span>
            <code className="whitespace-pre" data-source-line-content="">
              {line || " "}
            </code>
          </div>
        )
      })}
    </pre>
  )
}

function useMarkdownSearch({
  lineCount,
  text,
}: {
  lineCount: number
  text: string
}) {
  const [searchQuery, setSearchQuery] = React.useState("")
  const [activeIndex, setActiveIndex] = React.useState(0)
  const searchMatches = React.useMemo(
    () => buildPretextMarkdownSearchMatches(text, searchQuery),
    [searchQuery, text]
  )
  const activeSearchMatch =
    searchMatches.length === 0
      ? null
      : searchMatches[Math.min(activeIndex, searchMatches.length - 1)]
  const activeSearchRange = React.useMemo(
    () =>
      activeSearchMatch
        ? normalizeTextLineRange(
            {
              end: activeSearchMatch.endLine,
              start: activeSearchMatch.startLine,
            },
            lineCount
          )
        : null,
    [activeSearchMatch, lineCount]
  )

  // Changing the query resets the active match in the same event that sets it,
  // rather than reacting to the change in an effect.
  const updateSearchQuery = React.useCallback((next: string) => {
    setSearchQuery(next)
    setActiveIndex(0)
  }, [])

  const goToSearchMatch = React.useCallback(
    (direction: 1 | -1) => {
      setActiveIndex((current) => {
        if (searchMatches.length === 0) return 0
        return (
          (current + direction + searchMatches.length) % searchMatches.length
        )
      })
    },
    [searchMatches.length]
  )
  const clearSearch = React.useCallback(() => {
    setSearchQuery("")
    setActiveIndex(0)
  }, [])

  return {
    activeSearchMatch,
    activeSearchRange,
    clearSearch,
    goToSearchMatch,
    searchMatches,
    searchQuery,
    setSearchQuery: updateSearchQuery,
  }
}

function buildPretextMarkdownSearchMatches(
  text: string,
  query: string
): PretextMarkdownSearchMatch[] {
  const normalizedQuery = query.trim()
  if (!normalizedQuery) return []

  const lineStarts = getPretextMarkdownLineStarts(text)
  const lowerText = text.toLowerCase()
  const lowerQuery = normalizedQuery.toLowerCase()
  const matches: PretextMarkdownSearchMatch[] = []
  let offset = 0

  while (matches.length < MAX_SEARCH_MATCHES) {
    const startOffset = lowerText.indexOf(lowerQuery, offset)
    if (startOffset === -1) break

    const endOffset = startOffset + lowerQuery.length
    matches.push({
      endLine: getPretextMarkdownLineNumberForOffset(
        lineStarts,
        Math.max(startOffset, endOffset - 1)
      ),
      endOffset,
      index: matches.length,
      startLine: getPretextMarkdownLineNumberForOffset(lineStarts, startOffset),
      startOffset,
    })
    offset = Math.max(endOffset, startOffset + 1)
  }

  return matches
}

function getPretextMarkdownLineStarts(text: string) {
  const lineStarts = [0]
  for (let index = 0; index < text.length; index += 1) {
    if (text[index] === "\n") lineStarts.push(index + 1)
  }
  return lineStarts
}

function getPretextMarkdownLineNumberForOffset(
  lineStarts: readonly number[],
  offset: number
) {
  let low = 0
  let high = lineStarts.length - 1

  while (low <= high) {
    const middle = Math.floor((low + high) / 2)
    if ((lineStarts[middle] ?? 0) <= offset) low = middle + 1
    else high = middle - 1
  }

  return Math.max(1, high + 1)
}

function resolveScrollBehavior(behavior: ScrollBehavior | undefined) {
  if (behavior) return behavior
  if (
    typeof window !== "undefined" &&
    window.matchMedia?.("(prefers-reduced-motion: reduce)").matches
  ) {
    return "auto"
  }
  return "smooth"
}

function handleRenderedClick({
  document,
  event,
  scrollToLineRange,
}: {
  document: ReturnType<typeof createPretextMarkdownGreenfieldDocument>
  event: React.MouseEvent
  scrollToLineRange: (
    range: ReturnType<typeof normalizeTextLineRange>,
    options?: PretextMarkdownScrollToLineOptions
  ) => void
}) {
  const link = (event.target as HTMLElement | null)?.closest("a[href]")
  const href = link?.getAttribute("href")
  if (!href?.startsWith("#")) return

  const target = findPretextMarkdownGreenfieldFragmentTargetById(document, href)
  if (!target) return
  const chunk = findPretextMarkdownGreenfieldChunkByBlockId(
    document,
    target.blockId
  )

  event.preventDefault()
  window.history.pushState(null, "", href)
  scrollToLineRange(
    normalizeTextLineRange(
      { end: target.sourceLine, start: target.sourceLine },
      document.lineCount
    ),
    { behavior: "smooth", preferredChunkId: chunk?.id }
  )
}

function chunkIntersectsLineRange({
  chunkFrame,
  range,
}: {
  chunkFrame: PretextMarkdownGreenfieldChunkFrame
  range: { end: number; start: number } | null
}) {
  if (!range) return false
  return (
    chunkFrame.sourceStartLine <= range.end &&
    chunkFrame.sourceEndLine >= range.start
  )
}

function measureChunkFrame(
  _chunk: PretextMarkdownGreenfieldChunk,
  _onMeasuredHeight: (
    chunk: PretextMarkdownGreenfieldChunk,
    height: number
  ) => void
) {
  // The wrapper frame owns ResizeObserver measurement. This callback exists so
  // rich children can request a measurement pass without knowing the wrapper.
}

function measuredHeightKey({
  chunk,
  context,
  documentMeasurementId,
}: {
  chunk: PretextMarkdownGreenfieldChunk
  context: PretextMarkdownGreenfieldMeasurementContext
  documentMeasurementId: string
}) {
  return [
    documentMeasurementId,
    chunk.id,
    Math.round(context.width),
    context.fontScale.toFixed(4),
    context.policyVersion,
  ].join(":")
}

function measurementDocumentIdForText(text: string) {
  let hash = 2166136261
  for (let index = 0; index < text.length; index += 1) {
    hash ^= text.charCodeAt(index)
    hash = Math.imul(hash, 16777619)
  }
  return `md-${text.length}-${(hash >>> 0).toString(36)}`
}

"use client"

import * as React from "react"

export function isSafeHighlightedCodeLine(line: number) {
  return Number.isInteger(line) && line > 0 && line <= 100_000
}

export function normalizeCodeLanguage(language: string | null) {
  const value = (language ?? "text").toLowerCase()
  const aliases: Record<string, string> = {
    bash: "shell",
    docker: "dockerfile",
    javascript: "js",
    jsonc: "json",
    md: "markdown",
    patch: "diff",
    rb: "ruby",
    "shell-session": "shell",
    terminal: "shell",
    typescript: "ts",
    yml: "yaml",
  }
  return aliases[value] ?? value
}

export function diffLineKind(line: string) {
  if (line.startsWith("+") && !line.startsWith("+++")) return "add"
  if (line.startsWith("-") && !line.startsWith("---")) return "remove"
  return null
}

export function renderCodeLine({
  fallbackLanguage,
  line,
  pattern,
  shikiLine,
}: {
  fallbackLanguage: string
  line: string
  pattern: string
  shikiLine: readonly ShikiCodeToken[] | undefined
}) {
  if (shikiLine) {
    return renderShikiCodeLine({
      fallbackLanguage,
      line,
      pattern,
      tokens: shikiLine,
    })
  }
  if (!pattern) return renderFallbackCodeTokens(line || " ", fallbackLanguage)
  const index = line.indexOf(pattern)
  if (index < 0) return renderFallbackCodeTokens(line || " ", fallbackLanguage)
  return (
    <>
      {renderFallbackCodeTokens(line.slice(0, index), fallbackLanguage)}
      <span data-highlighted-chars="">{pattern}</span>
      {renderFallbackCodeTokens(
        line.slice(index + pattern.length),
        fallbackLanguage
      )}
    </>
  )
}

function renderShikiCodeLine({
  fallbackLanguage,
  line,
  pattern,
  tokens,
}: {
  fallbackLanguage: string
  line: string
  pattern: string
  tokens: readonly ShikiCodeToken[]
}) {
  if (!tokens.length) return " "
  if (!pattern) return renderShikiCodeTokens(tokens)

  const highlightStart = line.indexOf(pattern)
  if (highlightStart < 0) return renderShikiCodeTokens(tokens)

  return renderShikiCodeTokensWithHighlight({
    fallbackLanguage,
    highlightEnd: highlightStart + pattern.length,
    highlightStart,
    tokens,
  })
}

function renderShikiCodeTokens(tokens: readonly ShikiCodeToken[]) {
  return tokens.map((token, index) => (
    <span
      key={index}
      className="text-[var(--shiki-light)] dark:text-[var(--shiki-dark)]"
      data-pretext-code-token="shiki"
      data-shiki-token=""
      style={shikiTokenStyle(token)}
    >
      {token.content}
    </span>
  ))
}

function renderShikiCodeTokensWithHighlight({
  fallbackLanguage,
  highlightEnd,
  highlightStart,
  tokens,
}: {
  fallbackLanguage: string
  highlightEnd: number
  highlightStart: number
  tokens: readonly ShikiCodeToken[]
}) {
  const rendered: React.ReactNode[] = []
  let cursor = 0

  tokens.forEach((token, tokenIndex) => {
    const tokenStart = cursor
    const tokenEnd = cursor + token.content.length
    cursor = tokenEnd

    if (tokenEnd <= highlightStart || tokenStart >= highlightEnd) {
      rendered.push(
        <span
          key={tokenIndex}
          className="text-[var(--shiki-light)] dark:text-[var(--shiki-dark)]"
          data-pretext-code-token="shiki"
          data-shiki-token=""
          style={shikiTokenStyle(token)}
        >
          {token.content}
        </span>
      )
      return
    }

    const before = token.content.slice(
      0,
      Math.max(0, highlightStart - tokenStart)
    )
    const highlighted = token.content.slice(
      Math.max(0, highlightStart - tokenStart),
      Math.min(token.content.length, highlightEnd - tokenStart)
    )
    const after = token.content.slice(
      Math.min(token.content.length, highlightEnd - tokenStart)
    )

    if (before) {
      rendered.push(
        <span
          key={`${tokenIndex}-before`}
          className="text-[var(--shiki-light)] dark:text-[var(--shiki-dark)]"
          data-pretext-code-token="shiki"
          data-shiki-token=""
          style={shikiTokenStyle(token)}
        >
          {before}
        </span>
      )
    }
    if (highlighted) {
      rendered.push(
        <span key={`${tokenIndex}-highlight`} data-highlighted-chars="">
          <span
            className="text-[var(--shiki-light)] dark:text-[var(--shiki-dark)]"
            data-pretext-code-token="shiki"
            data-shiki-token=""
            style={shikiTokenStyle(token)}
          >
            {highlighted}
          </span>
        </span>
      )
    }
    if (after) {
      rendered.push(
        <span
          key={`${tokenIndex}-after`}
          className="text-[var(--shiki-light)] dark:text-[var(--shiki-dark)]"
          data-pretext-code-token="shiki"
          data-shiki-token=""
          style={shikiTokenStyle(token)}
        >
          {after}
        </span>
      )
    }
  })

  if (rendered.length) return rendered
  return renderFallbackCodeTokens(" ", fallbackLanguage)
}

function renderFallbackCodeTokens(line: string, language: string) {
  const tokens = tokenizeCodeLine(line, language)
  if (!tokens.length) return " "
  return tokens.map((token, index) =>
    token.kind === "plain" ? (
      <React.Fragment key={index}>{token.value}</React.Fragment>
    ) : (
      <span
        key={index}
        className={codeTokenClassName(token.kind)}
        data-pretext-code-token={token.kind}
      >
        {token.value}
      </span>
    )
  )
}

type ShikiCodeToken = {
  content: string
  darkColor: string
  fontStyle: number | undefined
  lightColor: string
}

type RawShikiToken = {
  content?: unknown
  variants?: {
    dark?: {
      color?: unknown
      fontStyle?: unknown
    }
    light?: {
      color?: unknown
      fontStyle?: unknown
    }
  }
}

const shikiCodeLineCache = new Map<string, Promise<ShikiCodeToken[][] | null>>()
const resolvedShikiCodeLines = new Map<string, ShikiCodeToken[][] | null>()
const shikiCodeLineSubscribers = new Set<() => void>()

function ensureShikiCodeLines(args: {
  cacheKey: string
  expectedLineCount: number
  language: string
  source: string
}) {
  if (resolvedShikiCodeLines.has(args.cacheKey)) return
  void getShikiCodeLines(args).then((lines) => {
    resolvedShikiCodeLines.set(args.cacheKey, lines)
    while (resolvedShikiCodeLines.size > 128) {
      const oldestKey = resolvedShikiCodeLines.keys().next().value
      if (oldestKey === undefined) break
      resolvedShikiCodeLines.delete(oldestKey)
    }
    for (const notify of shikiCodeLineSubscribers) notify()
  })
}

// Shiki tokenization is an asynchronous external system (a dynamically imported
// highlighter with a shared resolved-value cache). The viewer subscribes to
// that cache with useSyncExternalStore — the React-idiomatic way to read an
// external store — rather than driving the load from an effect. The snapshot
// returns a stable reference (the cached array, or null while pending) so
// rendering stays progressive: plain source first, highlighted once resolved.
export function useShikiCodeLines(
  source: string,
  language: string,
  expectedLineCount: number
) {
  const cacheKey = `${language}\0${source}`
  const subscribe = React.useCallback(
    (onStoreChange: () => void) => {
      shikiCodeLineSubscribers.add(onStoreChange)
      ensureShikiCodeLines({ cacheKey, expectedLineCount, language, source })
      return () => {
        shikiCodeLineSubscribers.delete(onStoreChange)
      }
    },
    [cacheKey, expectedLineCount, language, source]
  )
  const getSnapshot = React.useCallback(
    () =>
      resolvedShikiCodeLines.has(cacheKey)
        ? (resolvedShikiCodeLines.get(cacheKey) ?? null)
        : null,
    [cacheKey]
  )
  return React.useSyncExternalStore(subscribe, getSnapshot, () => null)
}

function getShikiCodeLines({
  cacheKey,
  expectedLineCount,
  language,
  source,
}: {
  cacheKey: string
  expectedLineCount: number
  language: string
  source: string
}) {
  let cached = shikiCodeLineCache.get(cacheKey)
  if (!cached) {
    cached = loadShikiCodeLines({ expectedLineCount, language, source })
    shikiCodeLineCache.set(cacheKey, cached)
    trimShikiCodeLineCache()
  }
  return cached
}

async function loadShikiCodeLines({
  expectedLineCount,
  language,
  source,
}: {
  expectedLineCount: number
  language: string
  source: string
}) {
  try {
    const shiki = await import("shiki")
    const lines = (await (shiki.codeToTokensWithThemes as any)(source, {
      lang: shikiLanguageFor(language),
      themes: {
        dark: "github-dark",
        light: "github-light-default",
      },
    })) as RawShikiToken[][]

    return normalizeShikiCodeLines(lines, expectedLineCount)
  } catch {
    return null
  }
}

function normalizeShikiCodeLines(
  lines: RawShikiToken[][],
  expectedLineCount: number
) {
  return Array.from({ length: expectedLineCount }, (_, index) =>
    normalizeShikiCodeLine(lines[index] ?? [])
  )
}

function normalizeShikiCodeLine(tokens: RawShikiToken[]): ShikiCodeToken[] {
  return tokens
    .map((token) => {
      const content = typeof token.content === "string" ? token.content : ""
      const lightColor = readShikiTokenColor(token, "light")
      const darkColor = readShikiTokenColor(token, "dark")
      if (!content || !lightColor || !darkColor) return null
      return {
        content,
        darkColor,
        fontStyle: readShikiTokenFontStyle(token),
        lightColor,
      }
    })
    .filter((token): token is ShikiCodeToken => token != null)
}

function readShikiTokenColor(token: RawShikiToken, variant: "dark" | "light") {
  const color = token.variants?.[variant]?.color
  return typeof color === "string" && /^#[0-9a-f]{6,8}$/i.test(color)
    ? color
    : ""
}

function readShikiTokenFontStyle(token: RawShikiToken) {
  const fontStyle =
    typeof token.variants?.light?.fontStyle === "number"
      ? token.variants.light.fontStyle
      : undefined
  return fontStyle && Number.isFinite(fontStyle) ? fontStyle : undefined
}

function shikiTokenStyle(token: ShikiCodeToken) {
  return {
    "--shiki-dark": token.darkColor,
    "--shiki-light": token.lightColor,
    fontStyle: token.fontStyle === 1 ? "italic" : undefined,
  } as React.CSSProperties
}

function shikiLanguageFor(language: string) {
  const aliases: Record<string, string> = {
    dockerfile: "docker",
    js: "javascript",
    shell: "bash",
    ts: "typescript",
  }
  return aliases[language] ?? language
}

function trimShikiCodeLineCache() {
  while (shikiCodeLineCache.size > 64) {
    const oldestKey = shikiCodeLineCache.keys().next().value
    if (!oldestKey) break
    shikiCodeLineCache.delete(oldestKey)
  }
}

type CodeToken = {
  kind: "comment" | "keyword" | "literal" | "number" | "plain" | "string"
  value: string
}

function tokenizeCodeLine(line: string, language: string): CodeToken[] {
  if (!line) return []
  if (language === "diff") return tokenizeDiffLine(line)
  if (language === "json") return tokenizeJsonLikeLine(line)
  if (language === "yaml") return tokenizeYamlLine(line)
  if (
    language === "js" ||
    language === "jsx" ||
    language === "ts" ||
    language === "tsx"
  ) {
    return tokenizeCStyleLine(line)
  }
  if (
    language === "shell" ||
    language === "bash" ||
    language === "dockerfile"
  ) {
    return tokenizeShellLine(line)
  }
  return [{ kind: "plain", value: line }]
}

function tokenizeCStyleLine(line: string): CodeToken[] {
  const commentIndex = line.indexOf("//")
  const codePart = commentIndex >= 0 ? line.slice(0, commentIndex) : line
  const commentPart = commentIndex >= 0 ? line.slice(commentIndex) : ""
  return [
    ...tokenizeByPattern(
      codePart,
      /("(?:\\.|[^"\\])*"|'(?:\\.|[^'\\])*'|`(?:\\.|[^`\\])*`|\b(?:as|async|await|break|case|catch|class|const|continue|default|do|else|export|extends|false|finally|for|from|function|if|import|in|instanceof|interface|let|new|null|of|return|satisfies|switch|throw|true|try|type|typeof|undefined|var|while|yield)\b|\b\d+(?:\.\d+)?\b)/g,
      classifyCStyleToken
    ),
    ...(commentPart ? [{ kind: "comment" as const, value: commentPart }] : []),
  ]
}

function classifyCStyleToken(value: string): CodeToken["kind"] {
  if (/^["'`]/.test(value)) return "string"
  if (/^\d/.test(value)) return "number"
  if (/^(?:true|false|null|undefined)$/.test(value)) return "literal"
  return "keyword"
}

function tokenizeJsonLikeLine(line: string): CodeToken[] {
  return tokenizeByPattern(
    line,
    /("(?:\\.|[^"\\])*"|\b(?:true|false|null)\b|-?\b\d+(?:\.\d+)?(?:e[+-]?\d+)?\b)/gi,
    (value) => {
      if (/^"/.test(value)) return "string"
      if (/^(?:true|false|null)$/i.test(value)) return "literal"
      return "number"
    }
  )
}

function tokenizeYamlLine(line: string): CodeToken[] {
  const commentIndex = line.indexOf("#")
  const codePart = commentIndex >= 0 ? line.slice(0, commentIndex) : line
  const commentPart = commentIndex >= 0 ? line.slice(commentIndex) : ""
  return [
    ...tokenizeByPattern(
      codePart,
      /("(?:\\.|[^"\\])*"|'(?:\\.|[^'\\])*'|\b(?:true|false|null)\b|-?\b\d+(?:\.\d+)?\b)/gi,
      (value) => {
        if (/^["']/.test(value)) return "string"
        if (/^(?:true|false|null)$/i.test(value)) return "literal"
        return "number"
      }
    ),
    ...(commentPart ? [{ kind: "comment" as const, value: commentPart }] : []),
  ]
}

function tokenizeShellLine(line: string): CodeToken[] {
  const commentIndex = line.search(/(^|\s)#/)
  const codePart = commentIndex >= 0 ? line.slice(0, commentIndex) : line
  const commentPart = commentIndex >= 0 ? line.slice(commentIndex) : ""
  return [
    ...tokenizeByPattern(
      codePart,
      /("(?:\\.|[^"\\])*"|'(?:\\.|[^'\\])*'|\b(?:cd|cp|curl|echo|export|git|grep|mkdir|mv|node|npm|pnpm|rm|sed|test|yarn)\b)/g,
      (value) => (/^["']/.test(value) ? "string" : "keyword")
    ),
    ...(commentPart ? [{ kind: "comment" as const, value: commentPart }] : []),
  ]
}

function tokenizeDiffLine(line: string): CodeToken[] {
  if (line.startsWith("+") && !line.startsWith("+++")) {
    return [{ kind: "literal", value: line }]
  }
  if (line.startsWith("-") && !line.startsWith("---")) {
    return [{ kind: "comment", value: line }]
  }
  return [{ kind: "plain", value: line }]
}

function tokenizeByPattern(
  line: string,
  pattern: RegExp,
  classify: (value: string) => CodeToken["kind"]
): CodeToken[] {
  const tokens: CodeToken[] = []
  let cursor = 0
  for (const match of line.matchAll(pattern)) {
    const index = match.index ?? 0
    if (index > cursor) {
      tokens.push({ kind: "plain", value: line.slice(cursor, index) })
    }
    const value = match[0]
    tokens.push({ kind: classify(value), value })
    cursor = index + value.length
  }
  if (cursor < line.length) {
    tokens.push({ kind: "plain", value: line.slice(cursor) })
  }
  return tokens
}

function codeTokenClassName(kind: CodeToken["kind"]) {
  switch (kind) {
    case "comment":
      return "text-muted-foreground italic"
    case "keyword":
      return "font-semibold text-sky-700 dark:text-sky-300"
    case "literal":
      return "text-purple-700 dark:text-purple-300"
    case "number":
      return "text-amber-700 dark:text-amber-300"
    case "string":
      return "text-emerald-700 dark:text-emerald-300"
    default:
      return ""
  }
}

"use client"

import * as React from "react"
import { Check, Clipboard } from "lucide-react"

const MERMAID_MAX_LINES = 160
const MERMAID_MAX_SOURCE_LENGTH = 12_000

const MERMAID_CONFIG = {
  flowchart: {
    htmlLabels: false,
    useMaxWidth: true,
  },
  securityLevel: "strict",
  sequence: {
    useMaxWidth: true,
  },
  startOnLoad: false,
  suppressErrorRendering: true,
  theme: "default",
} as const

type DiagramState =
  | { status: "failed"; message: string }
  | { status: "loading" }
  | { status: "ready"; svg: string }
type ReadyDiagramState = Extract<DiagramState, { status: "ready" }>

// A per-instance async store for one diagram's mermaid render. Kept per
// component (not module-global) so instances never share state — no cross-
// render notify fan-out and no shared cache keyed by a render-order id.
type MermaidDiagramStore = {
  key: string
  result: DiagramState | null
  listeners: Set<() => void>
}

export function PretextMarkdownGreenfieldDiagram({
  caption,
  componentName,
  onContentReady,
  source,
  title,
}: {
  caption?: string
  componentName?: string
  onContentReady?: () => void
  source: string
  title?: string
}) {
  const limitMessage = React.useMemo(
    () => readDiagramLimitMessage(source),
    [source]
  )
  const diagramId = React.useId().replace(/:/g, "")
  const elementId = `pretext-markdown-diagram-${diagramId}`
  const description = React.useMemo(() => describeDiagram(source), [source])
  const bodyHeight = React.useMemo(
    () => estimateDiagramBodyHeight(source),
    [source]
  )
  const descriptionId = description
    ? `pretext-markdown-diagram-description-${diagramId}`
    : undefined
  const captionId = caption
    ? `pretext-markdown-diagram-caption-${diagramId}`
    : undefined
  const describedBy =
    [descriptionId, captionId].filter(Boolean).join(" ") || undefined

  // Derive the displayed state: a limit message fails immediately; otherwise the
  // state follows this instance's async mermaid store (loading until resolved).
  const storeRef = React.useRef<MermaidDiagramStore | null>(null)
  if (storeRef.current === null) {
    storeRef.current = { key: "", listeners: new Set(), result: null }
  }
  const store = storeRef.current
  const renderKey = limitMessage ? "" : `${elementId}\0${source}`
  const subscribe = React.useCallback(
    (onStoreChange: () => void) => {
      store.listeners.add(onStoreChange)
      // Kick off (or restart on source change) the render here, in the store
      // subscription, so no effect is needed.
      if (!limitMessage && store.key !== renderKey) {
        store.key = renderKey
        store.result = null
        void renderMermaidDiagram(source, elementId).then((result) => {
          if (store.key !== renderKey) return
          store.result = result
          for (const listener of store.listeners) listener()
        })
      }
      return () => {
        store.listeners.delete(onStoreChange)
      }
    },
    [elementId, limitMessage, renderKey, source, store]
  )
  const getSnapshot = React.useCallback(
    () => (store.key === renderKey ? store.result : null),
    [renderKey, store]
  )
  const resolvedState = React.useSyncExternalStore(
    subscribe,
    getSnapshot,
    () => null
  )
  const state: DiagramState = limitMessage
    ? { status: "failed", message: limitMessage }
    : (resolvedState ?? { status: "loading" })

  React.useLayoutEffect(() => {
    onContentReady?.()
  }, [bodyHeight, onContentReady, state.status])

  return (
    <figure
      aria-describedby={describedBy}
      aria-label={title || "Mermaid diagram"}
      className="group my-5 min-h-40 overflow-hidden rounded-md border bg-muted/30"
      data-diagram-language="mermaid"
      data-diagram-reserved-height={bodyHeight}
      data-diagram-state={state.status}
      data-pretext-component={componentName}
      role="group"
      style={
        {
          "--pretext-diagram-body-height": `${bodyHeight}px`,
        } as React.CSSProperties
      }
    >
      <div className="flex h-9 items-center gap-1 border-b bg-muted/60 px-3">
        <span className="min-w-0 truncate text-xs font-medium text-muted-foreground">
          {title || "mermaid"}
        </span>
        <DiagramCopyButton
          ariaLabel="Copy diagram source"
          className="ml-auto"
          text={source}
        />
        {state.status === "ready" ? (
          <DiagramCopyButton ariaLabel="Copy diagram SVG" text={state.svg} />
        ) : null}
      </div>
      {description ? (
        <p
          className="sr-only"
          data-pretext-diagram-description=""
          id={descriptionId}
        >
          {description}
        </p>
      ) : null}
      <div
        aria-label="Mermaid diagram body"
        className="h-(--pretext-diagram-body-height) overflow-auto p-4"
        data-pretext-diagram-body=""
        onKeyDown={(event) => {
          const element = event.currentTarget
          if (event.key === "ArrowRight") {
            element.scrollLeft += 50
            event.preventDefault()
          } else if (event.key === "ArrowLeft") {
            element.scrollLeft -= 50
            event.preventDefault()
          } else if (event.key === "End") {
            element.scrollLeft = Math.max(
              0,
              element.scrollWidth - element.clientWidth
            )
            event.preventDefault()
          } else if (event.key === "Home") {
            element.scrollLeft = 0
            event.preventDefault()
          }
        }}
        role="region"
        tabIndex={0}
      >
        {state.status === "ready" ? (
          <div dangerouslySetInnerHTML={{ __html: state.svg }} />
        ) : (
          <>
            {state.status === "failed" ? (
              <p
                className="mb-3 rounded border border-destructive/25 bg-destructive/10 px-3 py-2 text-sm text-destructive"
                data-pretext-diagram-error=""
                role="alert"
              >
                {state.message}
              </p>
            ) : null}
            <pre
              aria-label="Mermaid diagram source"
              className="m-0 overflow-x-auto font-mono text-[0.82em] leading-relaxed text-muted-foreground"
              tabIndex={0}
            >
              {source}
            </pre>
          </>
        )}
      </div>
      {caption ? (
        <figcaption
          className="border-t bg-muted/30 px-3 py-2 text-sm text-muted-foreground"
          data-pretext-diagram-caption=""
          id={captionId}
        >
          {caption}
        </figcaption>
      ) : null}
    </figure>
  )
}

function DiagramCopyButton({
  ariaLabel,
  className,
  text,
}: {
  ariaLabel: string
  className?: string
  text: string
}) {
  const [isCopied, setIsCopied] = React.useState(false)

  return (
    <button
      aria-label={isCopied ? "Copied" : ariaLabel}
      className={[
        "inline-flex size-7 items-center justify-center rounded-md text-muted-foreground transition hover:bg-background hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring focus-visible:outline-none",
        className,
      ]
        .filter(Boolean)
        .join(" ")}
      type="button"
      onClick={() => {
        void navigator.clipboard?.writeText(text).then(() => {
          setIsCopied(true)
          window.setTimeout(() => setIsCopied(false), 1200)
        })
      }}
    >
      {isCopied ? (
        <Check aria-hidden="true" className="size-3.5" />
      ) : (
        <Clipboard aria-hidden="true" className="size-3.5" />
      )}
    </button>
  )
}

async function renderMermaidDiagram(
  source: string,
  id: string
): Promise<DiagramState> {
  try {
    const mermaidModule = await import("mermaid")
    const mermaid = mermaidModule.default
    mermaid.initialize?.(MERMAID_CONFIG)
    const result = await mermaid.render(id, source)
    return { status: "ready", svg: sanitizeSvg(result.svg) }
  } catch (error) {
    const message = error instanceof Error ? error.message : "Invalid diagram"
    if (!/getBBox|layout|force-basic-fallback/i.test(message)) {
      return { status: "failed", message }
    }
    return renderBasicMermaidDiagram(source)
  }
}

function renderBasicMermaidDiagram(source: string): ReadyDiagramState {
  const kind = diagramKind(source)
  const lines = readableDiagramLines(source)
  const escaped = escapeHtml(lines.join(" | ") || describeDiagram(source))
  const piePaths =
    kind === "pie"
      ? '<path d="M20 20h20v20H20z"/><path d="M44 20h20v20H44z"/><path d="M68 20h20v20H68z"/>'
      : ""
  return {
    status: "ready",
    svg: `<svg role="img" aria-label="Mermaid diagram" data-pretext-basic-mermaid="${kind}" viewBox="0 0 720 160" width="100%" height="160" xmlns="http://www.w3.org/2000/svg"><rect width="720" height="160" rx="8" fill="currentColor" opacity="0.05"/>${piePaths}<text x="24" y="82" fill="currentColor" font-family="monospace" font-size="16">${escaped}</text></svg>`,
  }
}

function sanitizeSvg(svg: string) {
  if (typeof DOMParser === "undefined") return svg

  const document = new DOMParser().parseFromString(svg, "image/svg+xml")
  const root = document.documentElement
  if (!root || root.tagName.toLowerCase() !== "svg") {
    const fallback = renderBasicMermaidDiagram("")
    return fallback.status === "ready" ? fallback.svg : ""
  }

  for (const element of Array.from(root.querySelectorAll("*"))) {
    const tagName = element.tagName.toLowerCase()
    if (
      tagName === "script" ||
      tagName === "a" ||
      tagName === "animate" ||
      tagName === "foreignobject" ||
      tagName === "image" ||
      tagName === "iframe" ||
      tagName === "object" ||
      tagName === "embed" ||
      tagName === "style" ||
      tagName === "use"
    ) {
      element.remove()
      continue
    }

    for (const attribute of Array.from(element.attributes)) {
      const name = attribute.name.toLowerCase()
      const value = attribute.value.trim()
      if (name.startsWith("on") || name === "style") {
        element.removeAttribute(attribute.name)
        continue
      }
      if ((name === "id" || name === "name") && isDomClobberingId(value)) {
        element.setAttribute(attribute.name, `user-content-${value}`)
        continue
      }
      if (
        (name === "href" || name.endsWith(":href") || name === "src") &&
        !isSafeSvgReference(value)
      ) {
        element.removeAttribute(attribute.name)
      }
    }
  }

  for (const attribute of Array.from(root.attributes)) {
    const name = attribute.name.toLowerCase()
    if (name.startsWith("on") || name === "style") {
      root.removeAttribute(attribute.name)
      continue
    }
    if (
      (name === "id" || name === "name") &&
      isDomClobberingId(attribute.value)
    ) {
      root.setAttribute(attribute.name, `user-content-${attribute.value}`)
    }
  }

  return new XMLSerializer()
    .serializeToString(root)
    .replace(/^<svg\b([^>]*)\brole="([^"]*)"([^>]*)>/, '<svg role="$2"$1$3>')
}

function isSafeSvgReference(value: string) {
  return (
    value === "" ||
    value.startsWith("#") ||
    value.startsWith("data:image/") ||
    /^https?:\/\//i.test(value)
  )
}

function readDiagramLimitMessage(source: string) {
  if (source.length > MERMAID_MAX_SOURCE_LENGTH) {
    return "Mermaid diagram too large to render safely. Copy the source and render it in a dedicated diagram tool."
  }
  if (source.split(/\r\n|[\n\r\u2028\u2029]/).length > MERMAID_MAX_LINES) {
    return "Mermaid diagram has too many lines to render safely. Copy the source and render it in a dedicated diagram tool."
  }
  return null
}

function describeDiagram(source: string) {
  const lines = semanticDiagramLines(source)
  const kind = diagramKind(source)
  if (kind === "graph") {
    const direction = lines[0]
      ?.match(/\b(?:graph|flowchart)\s+([A-Z]{2})\b/i)?.[1]
      ?.toUpperCase()
    const directionText = direction === "LR" ? "left to right" : "top down"
    const edges = lines.filter((line) => /-->|---|-.->|==>/.test(line)).length
    const nodes = new Set<string>()
    for (const line of lines) {
      for (const match of line.matchAll(/\b([A-Za-z][\w-]*)\b/g)) {
        const value = match[1]!
        if (
          !["graph", "flowchart", "TD", "LR", "TB", "BT", "RL"].includes(value)
        ) {
          nodes.add(value)
        }
      }
    }
    return `Mermaid graph diagram flowing ${directionText}, with ${nodes.size} nodes and ${edges} edge${edges === 1 ? "" : "s"}.`
  }
  if (kind === "sequence") {
    const messages = lines.filter((line) => /->>|-->>|->|-->/.test(line)).length
    const participants = new Set<string>()
    for (const line of lines) {
      const participant = /^participant\s+\S+(?:\s+as\s+(.+))?/i.exec(line)
      if (participant) participants.add(participant[1] ?? line.split(/\s+/)[1]!)
      for (const side of line.split(/->>|-->>|->|-->/)) {
        const name = side.split(":")[0]?.trim()
        if (name && !/^sequenceDiagram/i.test(name)) participants.add(name)
      }
    }
    return `Mermaid sequence diagram with ${participants.size} participants and ${messages} message${messages === 1 ? "" : "s"}.`
  }
  if (kind === "state") {
    const transitions = lines.filter((line) => /-->/.test(line)).length
    const states = new Set<string>()
    for (const line of lines) {
      const stateAlias = /^state\s+"([^"]+)"\s+as\s+(\w+)/.exec(line)
      if (stateAlias) {
        states.add(stateAlias[1]!)
        continue
      }
      if (!/-->/.test(line)) continue
      for (const side of line.split(/-->/)) {
        const name = side
          .split(":")[0]!
          .replace(/\[\*\]/g, "")
          .trim()
        if (name && !/^stateDiagram/.test(name)) {
          states.add(name)
        }
      }
    }
    return `Mermaid state diagram with ${states.size} states and ${transitions} transitions.`
  }
  if (kind === "class") {
    const relationships = lines.filter((line) =>
      /<\|--|--|<--|\.\./.test(line)
    ).length
    const classes = new Set<string>()
    for (const line of lines) {
      for (const match of line.matchAll(/\b([A-Z][A-Za-z0-9_]*)\b/g))
        classes.add(match[1]!)
    }
    return `Mermaid class diagram with ${classes.size} classes and ${relationships} relationship${relationships === 1 ? "" : "s"}.`
  }
  if (kind === "er") {
    const relationships = lines.filter((line) =>
      /\|\||o\{|\|\{/.test(line)
    ).length
    const entities = new Set<string>()
    for (const line of lines) {
      for (const match of line.matchAll(/\b([A-Z][A-Z0-9_]*)\b/g)) {
        if (!["ERDIAGRAM"].includes(match[1]!)) entities.add(match[1]!)
      }
    }
    return `Mermaid entity relationship diagram with ${entities.size} entities and ${relationships} relationships.`
  }
  if (kind === "journey")
    return `Mermaid journey diagram with ${countLinesStarting(lines, "section ")} sections and ${lines.filter((line) => /:\s*\d+\s*:/.test(line)).length} tasks.`
  if (kind === "gantt")
    return `Mermaid Gantt chart with ${countLinesStarting(lines, "section ")} sections and ${lines.filter((line) => /:/.test(line) && !/^dateFormat/i.test(line) && !/^title\b/i.test(line)).length} tasks.`
  if (kind === "gitGraph")
    return `Mermaid Git graph with ${countLinesStarting(lines, "branch ")} branch, ${countExact(lines, "commit")} commits, and ${countLinesStarting(lines, "merge ")} merge.`
  if (kind === "timeline")
    return `Mermaid timeline with ${countLinesStarting(lines, "section ")} sections and ${lines.filter((line) => /^\d/.test(line)).length} events.`
  if (kind === "mindmap")
    return `Mermaid mind map with ${Math.max(0, lines.length - 1)} nodes.`
  if (kind === "quadrantChart")
    return `Mermaid quadrant chart with ${lines.filter((line) => /:\s*\[[^\]]+\]/.test(line)).length} points.`
  if (kind === "requirementDiagram")
    return `Mermaid requirement diagram with ${countLinesStarting(lines, "requirement ")} requirement, ${countLinesStarting(lines, "element ")} element, and ${lines.filter((line) => /-\s*\w+\s*->/.test(line)).length} relationship.`
  if (kind === "xychart") {
    const series = lines.filter((line) => /^(bar|line)\s+\[/.test(line))
    const values = series.reduce(
      (sum, line) => sum + (line.match(/-?\d+(?:\.\d+)?/g)?.length ?? 0),
      0
    )
    return `Mermaid XY chart with ${series.length} series and ${values} values.`
  }
  if (kind === "sankey") {
    const flows = lines.filter((line) => line.includes(","))
    const nodes = new Set(
      flows.flatMap((line) =>
        line
          .split(",")
          .slice(0, 2)
          .map((item) => item.trim())
      )
    )
    return `Mermaid Sankey diagram with ${nodes.size} nodes and ${flows.length} flows.`
  }
  if (kind === "c4")
    return `Mermaid C4 diagram with ${lines.filter((line) => /^(Person|System)\(/.test(line)).length} nodes and ${countLinesStarting(lines, "Rel(")} relationship.`
  if (kind === "pie") {
    const values = lines
      .flatMap((line) => line.match(/:\s*(\d+(?:\.\d+)?)/)?.[1] ?? [])
      .map(Number)
    const total = values.reduce((sum, value) => sum + value, 0)
    return `Mermaid pie chart with ${values.length} slices and total value ${total}.`
  }
  return "Mermaid diagram"
}

function estimateDiagramBodyHeight(source: string) {
  switch (diagramKind(source)) {
    case "graph":
      return 286
    case "sequence":
      return 160
    case "state":
      return 238
    case "class":
      return 220
    case "er":
      return 292
    case "journey":
      return 270
    case "gantt":
      return 300
    case "gitGraph":
      return 212
    case "timeline":
      return 270
    case "mindmap":
      return 232
    case "quadrantChart":
      return 296
    case "requirementDiagram":
      return 230
    case "xychart":
      return 334
    case "sankey":
      return 310
    case "c4":
      return 236
    case "pie":
      return 224
    default:
      return 180
  }
}

function diagramKind(source: string) {
  const first = semanticDiagramLines(source)[0] ?? ""
  if (/^(?:graph|flowchart)\b/i.test(first)) return "graph"
  if (/^sequenceDiagram\b/i.test(first)) return "sequence"
  if (/^stateDiagram/i.test(first)) return "state"
  if (/^classDiagram\b/i.test(first)) return "class"
  if (/^erDiagram\b/i.test(first)) return "er"
  if (/^journey\b/i.test(first)) return "journey"
  if (/^gantt\b/i.test(first)) return "gantt"
  if (/^gitGraph\b/i.test(first)) return "gitGraph"
  if (/^timeline\b/i.test(first)) return "timeline"
  if (/^mindmap\b/i.test(first)) return "mindmap"
  if (/^quadrantChart\b/i.test(first)) return "quadrantChart"
  if (/^requirementDiagram\b/i.test(first)) return "requirementDiagram"
  if (/^xychart/i.test(first)) return "xychart"
  if (/^sankey/i.test(first)) return "sankey"
  if (/^C4/i.test(first)) return "c4"
  if (/^pie\b/i.test(first)) return "pie"
  return "source"
}

function semanticDiagramLines(source: string) {
  return stripMermaidFrontmatter(source)
    .split(/\r\n|[\n\r\u2028\u2029]/)
    .map((line) => line.trim())
    .filter((line) => line && !line.startsWith("%%"))
}

function readableDiagramLines(source: string) {
  const lines = semanticDiagramLines(source)
  if (diagramKind(source) === "pie") {
    return lines.map((line) => {
      const match = /"([^"]+)"\s*:\s*(\d+(?:\.\d+)?)/.exec(line)
      return match ? `${match[1]} ${match[2]} (${match[2]}%)` : line
    })
  }
  return lines
}

function stripMermaidFrontmatter(source: string) {
  const lines = source.split(/\r\n|[\n\r\u2028\u2029]/)
  if (lines[0]?.trim() !== "---") return source
  const end = lines.findIndex(
    (line, index) => index > 0 && line.trim() === "---"
  )
  return end === -1 ? source : lines.slice(end + 1).join("\n")
}

function countLinesStarting(lines: readonly string[], prefix: string) {
  return lines.filter((line) => line.startsWith(prefix)).length
}

function countExact(lines: readonly string[], value: string) {
  return lines.filter((line) => line === value).length
}

function isDomClobberingId(id: string) {
  return ["constructor", "forms", "images", "location", "__proto__"].includes(
    id
  )
}

function escapeHtml(value: string) {
  return value
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
}

"use client"

import type {
  PretextMarkdownHastElement,
  PretextMarkdownHastNode,
} from "./pretext-markdown-hast-types"
import {
  pretextMarkdownSourceRangeFromPosition,
  pretextMarkdownSourceTextForRange,
  type PretextMarkdownSourceRange,
} from "./pretext-markdown-source-map"
import {
  createPretextMarkdownUnifiedDocument,
  type PretextMarkdownUnifiedDocument,
} from "./pretext-markdown-unified-pipeline"

const TARGET_CHUNK_SOURCE_LINES = 42
const MAX_CHUNK_SOURCE_LINES = 64
const HOSTILE_CODE_LINE_COUNT = 400
const HOSTILE_HAST_NODE_COUNT = 3_000
const HOSTILE_HAST_DEPTH = 80
const HOSTILE_TEXT_LENGTH = 20_000
const HOSTILE_TABLE_CELL_COUNT = 2_000
const DOCUMENT_CACHE_LIMIT = 24

const pretextMarkdownGreenfieldDocumentCache = new Map<
  string,
  {
    document: PretextMarkdownGreenfieldDocument
    text: string
  }
>()

export type PretextMarkdownGreenfieldBlockKind =
  | "blockquote"
  | "code"
  | "component"
  | "diagram"
  | "footnotes"
  | "frontmatter"
  | "heading"
  | "html"
  | "image"
  | "list"
  | "math"
  | "paragraph"
  | "table"
  | "thematicBreak"
  | "unknown"

export type PretextMarkdownGreenfieldDocument = {
  blocks: PretextMarkdownGreenfieldBlock[]
  chunks: PretextMarkdownGreenfieldChunk[]
  fragmentTargets: PretextMarkdownGreenfieldFragmentTarget[]
  headings: PretextMarkdownGreenfieldHeading[]
  lineCount: number
  text: string
  unified: PretextMarkdownUnifiedDocument
  wordCount: number
}

export type PretextMarkdownGreenfieldHeading = {
  blockId: string
  id: string
  sourceLine: number
  text: string
}

export type PretextMarkdownGreenfieldFragmentTarget = {
  blockId: string
  id: string
  sourceLine: number
}

export type PretextMarkdownGreenfieldBlock = {
  hastChildren: PretextMarkdownHastNode[]
  id: string
  index: number
  isGenerated: boolean
  isHostile: boolean
  kind: PretextMarkdownGreenfieldBlockKind
  sourceRange: PretextMarkdownSourceRange | null
  sourceText: string
}

export type PretextMarkdownGreenfieldChunk = {
  blockIds: string[]
  hastChildren: PretextMarkdownHastNode[]
  id: string
  index: number
  isHostile: boolean
  sourceEndLine: number
  sourceRange: PretextMarkdownSourceRange | null
  sourceStartLine: number
  sourceText: string
}

export function createPretextMarkdownGreenfieldDocument(
  markdown: string
): PretextMarkdownGreenfieldDocument {
  const text = markdown.length ? markdown : " "
  const cacheKey = pretextMarkdownGreenfieldDocumentCacheKey(text)
  const cached = pretextMarkdownGreenfieldDocumentCache.get(cacheKey)
  if (cached?.text === text) {
    pretextMarkdownGreenfieldDocumentCache.delete(cacheKey)
    pretextMarkdownGreenfieldDocumentCache.set(cacheKey, cached)
    return cached.document
  }

  const document = createUncachedPretextMarkdownGreenfieldDocument(text)
  pretextMarkdownGreenfieldDocumentCache.set(cacheKey, {
    document,
    text,
  })
  while (pretextMarkdownGreenfieldDocumentCache.size > DOCUMENT_CACHE_LIMIT) {
    const oldestKey = pretextMarkdownGreenfieldDocumentCache.keys().next().value
    if (!oldestKey) break
    pretextMarkdownGreenfieldDocumentCache.delete(oldestKey)
  }

  return document
}

function createUncachedPretextMarkdownGreenfieldDocument(
  text: string
): PretextMarkdownGreenfieldDocument {
  const unified = createPretextMarkdownUnifiedDocument(text)
  normalizePretextMarkdownGreenfieldHeadingIds(unified.hast.children, unified)
  normalizePretextMarkdownGreenfieldTables(unified.hast.children)
  annotatePretextMarkdownGreenfieldSourceMetadata(
    unified.hast.children,
    unified
  )
  const blocks = createPretextMarkdownGreenfieldBlocks({ text, unified })
  const chunks = createPretextMarkdownGreenfieldChunks({ blocks, text })
  const headings = createPretextMarkdownGreenfieldHeadings(blocks)
  const fragmentTargets = createPretextMarkdownGreenfieldFragmentTargets({
    blocks,
    unified,
  })
  freezePretextMarkdownHastNode(unified.hast)

  return freezePretextMarkdownGreenfieldDocument({
    blocks,
    chunks,
    fragmentTargets,
    headings,
    lineCount: unified.sourceMap.lineCount,
    text,
    unified,
    wordCount: text.trim().split(/\s+/).filter(Boolean).length,
  })
}

export function findPretextMarkdownGreenfieldHeadingById(
  document: PretextMarkdownGreenfieldDocument,
  headingId: string
) {
  const normalizedId = headingId.replace(/^#/, "")
  return document.headings.find((heading) => heading.id === normalizedId)
}

export function findPretextMarkdownGreenfieldFragmentTargetById(
  document: PretextMarkdownGreenfieldDocument,
  fragmentId: string
) {
  const normalizedId = normalizeFragmentTargetId(fragmentId)
  return document.fragmentTargets.find((target) => target.id === normalizedId)
}

export function findPretextMarkdownGreenfieldBlockById(
  document: PretextMarkdownGreenfieldDocument,
  blockId: string
) {
  return document.blocks.find((block) => block.id === blockId) ?? null
}

export function findPretextMarkdownGreenfieldChunkByBlockId(
  document: PretextMarkdownGreenfieldDocument,
  blockId: string
) {
  return (
    document.chunks.find((chunk) => chunk.blockIds.includes(blockId)) ?? null
  )
}

export function findPretextMarkdownGreenfieldBlockBySourceLine(
  document: PretextMarkdownGreenfieldDocument,
  sourceLine: number
) {
  const line = clampSourceLine(sourceLine, document.lineCount)
  return (
    document.blocks.find((block) => {
      const range = block.sourceRange
      return range && range.startLine <= line && range.endLine >= line
    }) ?? null
  )
}

export function findPretextMarkdownGreenfieldChunkBySourceLine(
  document: PretextMarkdownGreenfieldDocument,
  sourceLine: number
) {
  const block = findPretextMarkdownGreenfieldBlockBySourceLine(
    document,
    sourceLine
  )
  if (block)
    return findPretextMarkdownGreenfieldChunkByBlockId(document, block.id)

  const line = clampSourceLine(sourceLine, document.lineCount)
  return (
    document.chunks.find(
      (chunk) => chunk.sourceStartLine <= line && chunk.sourceEndLine >= line
    ) ?? null
  )
}

export function findPretextMarkdownGreenfieldBlockBySourceOffset(
  document: PretextMarkdownGreenfieldDocument,
  sourceOffset: number
) {
  const offset = clampSourceOffset(sourceOffset, document.text.length)
  return (
    document.blocks.find((block) => {
      const range = block.sourceRange
      return range && range.startOffset <= offset && range.endOffset > offset
    }) ?? null
  )
}

export function findPretextMarkdownGreenfieldChunkBySourceOffset(
  document: PretextMarkdownGreenfieldDocument,
  sourceOffset: number
) {
  const block = findPretextMarkdownGreenfieldBlockBySourceOffset(
    document,
    sourceOffset
  )
  return block
    ? findPretextMarkdownGreenfieldChunkByBlockId(document, block.id)
    : null
}

function createPretextMarkdownGreenfieldBlocks({
  text,
  unified,
}: {
  text: string
  unified: PretextMarkdownUnifiedDocument
}) {
  const blocks: PretextMarkdownGreenfieldBlock[] = []

  for (const child of unified.hast.children) {
    if (isWhitespaceText(child)) continue

    const directSourceRange = pretextMarkdownSourceRangeFromPosition({
      position: child.position,
      sourceMap: unified.sourceMap,
    })
    const sourceRange =
      directSourceRange ??
      pretextMarkdownSyntheticSourceRangeForNode(child, unified)
    const kind = pretextMarkdownBlockKindForHastChild(child)
    const sourceText = pretextMarkdownSourceTextForRange({
      range: sourceRange,
      sourceMap: unified.sourceMap,
    })
    const line = sourceRange?.startLine ?? unified.sourceMap.lineCount
    const block: PretextMarkdownGreenfieldBlock = {
      hastChildren: [child],
      id: `block-${blocks.length + 1}-${line}-${kind}`,
      index: blocks.length,
      isGenerated: !directSourceRange,
      isHostile: isHostilePretextMarkdownGreenfieldBlock({
        child,
        kind,
        sourceText,
      }),
      kind,
      sourceRange,
      sourceText:
        sourceText ||
        (sourceRange
          ? text.slice(sourceRange.startOffset, sourceRange.endOffset)
          : ""),
    }
    blocks.push(block)
  }

  if (!blocks.length) {
    blocks.push({
      hastChildren: [],
      id: "block-1-empty",
      index: 0,
      isGenerated: true,
      isHostile: false,
      kind: "paragraph",
      sourceRange: {
        endLine: 1,
        endOffset: text.length,
        startLine: 1,
        startOffset: 0,
      },
      sourceText: text,
    })
  }

  return blocks
}

function createPretextMarkdownGreenfieldChunks({
  blocks,
  text,
}: {
  blocks: readonly PretextMarkdownGreenfieldBlock[]
  text: string
}) {
  const chunks: PretextMarkdownGreenfieldChunk[] = []
  let current: PretextMarkdownGreenfieldBlock[] = []

  const flush = () => {
    if (!current.length) return
    chunks.push(createChunk(current, chunks.length, text))
    current = []
  }

  for (const block of blocks) {
    if (block.isHostile) {
      flush()
      current.push(block)
      flush()
      continue
    }

    const nextLineCount = lineCountForBlocks([...current, block])
    const startsNewChunk =
      current.length > 0 &&
      block.kind === "heading" &&
      nextLineCount >= TARGET_CHUNK_SOURCE_LINES
    const exceedsMax =
      current.length > 0 && nextLineCount > MAX_CHUNK_SOURCE_LINES

    if (startsNewChunk || exceedsMax) flush()
    current.push(block)
  }

  flush()
  return chunks
}

function createChunk(
  blocks: readonly PretextMarkdownGreenfieldBlock[],
  index: number,
  text: string
): PretextMarkdownGreenfieldChunk {
  const ranges = blocks
    .map((block) => block.sourceRange)
    .filter((range): range is PretextMarkdownSourceRange => Boolean(range))
  const sourceRange = ranges.length
    ? {
        endLine: Math.max(...ranges.map((range) => range.endLine)),
        endOffset: Math.max(...ranges.map((range) => range.endOffset)),
        startLine: Math.min(...ranges.map((range) => range.startLine)),
        startOffset: Math.min(...ranges.map((range) => range.startOffset)),
      }
    : null
  const sourceStartLine =
    sourceRange?.startLine ?? blocks[0]?.sourceRange?.startLine ?? 1
  const sourceEndLine =
    sourceRange?.endLine ??
    blocks[blocks.length - 1]?.sourceRange?.endLine ??
    sourceStartLine

  return {
    blockIds: blocks.map((block) => block.id),
    hastChildren: blocks.flatMap((block) => block.hastChildren),
    id: `chunk-${index + 1}-${sourceStartLine}`,
    index,
    isHostile: blocks.some((block) => block.isHostile),
    sourceEndLine,
    sourceRange,
    sourceStartLine,
    sourceText: sourceRange
      ? text.slice(sourceRange.startOffset, sourceRange.endOffset)
      : "",
  }
}

function createPretextMarkdownGreenfieldHeadings(
  blocks: readonly PretextMarkdownGreenfieldBlock[]
) {
  return blocks.flatMap((block) => {
    const element = readHastElement(block.hastChildren[0])
    if (!element || !/^h[1-6]$/.test(element.tagName)) return []

    const id = readStringProperty(element.properties?.id)
    if (!id) return []

    return [
      {
        blockId: block.id,
        id,
        sourceLine: block.sourceRange?.startLine ?? 1,
        text: extractHastText(element).trim(),
      },
    ]
  })
}

function createPretextMarkdownGreenfieldFragmentTargets({
  blocks,
  unified,
}: {
  blocks: readonly PretextMarkdownGreenfieldBlock[]
  unified: PretextMarkdownUnifiedDocument
}) {
  const targets = new Map<string, PretextMarkdownGreenfieldFragmentTarget>()

  for (const block of blocks) {
    for (const child of block.hastChildren) {
      collectFragmentTargets({
        block,
        node: child,
        targets,
        unified,
      })
    }
  }

  return Array.from(targets.values())
}

function collectFragmentTargets({
  block,
  node,
  targets,
  unified,
}: {
  block: PretextMarkdownGreenfieldBlock
  node: PretextMarkdownHastNode
  targets: Map<string, PretextMarkdownGreenfieldFragmentTarget>
  unified: PretextMarkdownUnifiedDocument
}) {
  const element = readHastElement(node)
  if (!element) return

  const id = readStringProperty(element.properties?.id)
  if (id) {
    const sourceRange =
      pretextMarkdownSourceRangeFromPosition({
        position: element.position,
        sourceMap: unified.sourceMap,
      }) ?? block.sourceRange
    const target = {
      blockId: block.id,
      id,
      sourceLine: sourceRange?.startLine ?? unified.sourceMap.lineCount,
    }

    for (const alias of fragmentTargetAliases(id)) {
      if (!targets.has(alias)) {
        targets.set(alias, { ...target, id: alias })
      }
    }
  }

  for (const child of element.children) {
    collectFragmentTargets({ block, node: child, targets, unified })
  }
}

function pretextMarkdownSyntheticSourceRangeForNode(
  node: PretextMarkdownHastNode,
  unified: PretextMarkdownUnifiedDocument
): PretextMarkdownSourceRange | null {
  const ranges = collectPretextMarkdownSourceRanges(node, unified)
  if (!ranges.length) return null
  return {
    endLine: Math.max(...ranges.map((range) => range.endLine)),
    endOffset: Math.max(...ranges.map((range) => range.endOffset)),
    startLine: Math.min(...ranges.map((range) => range.startLine)),
    startOffset: Math.min(...ranges.map((range) => range.startOffset)),
  }
}

function collectPretextMarkdownSourceRanges(
  node: PretextMarkdownHastNode,
  unified: PretextMarkdownUnifiedDocument
): PretextMarkdownSourceRange[] {
  const range = pretextMarkdownSourceRangeFromPosition({
    position: node.position,
    sourceMap: unified.sourceMap,
  })
  const element = readHastElement(node)
  return [
    ...(range ? [range] : []),
    ...(element?.children ?? []).flatMap((child) =>
      collectPretextMarkdownSourceRanges(child, unified)
    ),
  ]
}

function normalizePretextMarkdownGreenfieldHeadingIds(
  nodes: readonly PretextMarkdownHastNode[],
  unified: PretextMarkdownUnifiedDocument
) {
  const usedIds = new Map<string, number>()
  for (const node of nodes) {
    normalizeHeadingIdsInNode(node, usedIds, unified)
  }
}

function normalizeHeadingIdsInNode(
  node: PretextMarkdownHastNode,
  usedIds: Map<string, number>,
  unified: PretextMarkdownUnifiedDocument
) {
  const element = readHastElement(node)
  if (!element) return

  if (/^h[1-6]$/.test(element.tagName)) {
    const visibleText = extractHastText(element)
    const markdownText = markdownHeadingTextFromSource(element, unified)
    const baseId = safeHeadingIdForText(
      markdownText.includes("__proto__") ? markdownText : visibleText
    )
    const duplicateCount = usedIds.get(baseId) ?? 0
    usedIds.set(baseId, duplicateCount + 1)
    element.properties = {
      ...element.properties,
      id: duplicateCount === 0 ? baseId : `${baseId}-${duplicateCount}`,
    }
  }

  for (const child of element.children) {
    normalizeHeadingIdsInNode(child, usedIds, unified)
  }
}

function markdownHeadingTextFromSource(
  element: PretextMarkdownHastElement,
  unified: PretextMarkdownUnifiedDocument
) {
  const range = pretextMarkdownSourceRangeFromPosition({
    position: element.position,
    sourceMap: unified.sourceMap,
  })
  if (!range) return ""
  return pretextMarkdownSourceTextForRange({
    range,
    sourceMap: unified.sourceMap,
  })
    .replace(/^\s{0,3}#{1,6}[ \t]*/, "")
    .replace(/[ \t]+#*\s*$/, "")
    .trim()
}

function safeHeadingIdForText(text: string) {
  const slug =
    text
      .toLowerCase()
      .normalize("NFKD")
      .replace(/[\u0300-\u036f]/g, "")
      .replace(/[^\w\s-]/g, "")
      .trim()
      .replace(/\s+/g, "-")
      .replace(/-+/g, "-") || "section"

  return isDomClobberingId(slug) ? `section-${slug}` : slug
}

function normalizeFragmentTargetId(fragmentId: string) {
  return decodeURIComponent(fragmentId.replace(/^#/, ""))
}

function fragmentTargetAliases(id: string) {
  const aliases = new Set<string>([normalizeFragmentTargetId(id)])
  const withoutRepeatedClobberPrefix = id.replace(
    /^(user-content-)+/,
    "user-content-"
  )
  aliases.add(withoutRepeatedClobberPrefix)
  aliases.add(withoutRepeatedClobberPrefix.replace(/^user-content-/, ""))
  return Array.from(aliases).filter(Boolean)
}

function normalizePretextMarkdownGreenfieldTables(
  nodes: readonly PretextMarkdownHastNode[]
) {
  let tableIndex = 0
  for (const node of nodes) {
    tableIndex = normalizeTablesInNode(node, tableIndex)
  }
}

function normalizeTablesInNode(
  node: PretextMarkdownHastNode,
  tableIndex: number
) {
  const element = readHastElement(node)
  if (!element) return tableIndex

  if (element.tagName === "table") {
    normalizeTableElement(element, tableIndex)
    tableIndex += 1
  }

  for (const child of element.children) {
    tableIndex = normalizeTablesInNode(child, tableIndex)
  }
  return tableIndex
}

function normalizeTableElement(
  table: PretextMarkdownHastElement,
  tableIndex: number
) {
  const rows = tableRows(table)
  const headerIds = new Map<number, string>()

  rows.forEach((row, rowIndex) => {
    row.properties = {
      ...row.properties,
      ariaRowIndex: rowIndex + 1,
      dataPretextTableRowIndex: rowIndex + 1,
    }

    tableCells(row).forEach((cell, columnIndex) => {
      const column = columnIndex + 1
      const properties = {
        ...cell.properties,
        ariaColIndex: column,
        dataPretextTableColumnIndex: column,
      }
      if (cell.tagName === "th") {
        const id = `pretext-markdown-table-${tableIndex + 1}-column-${column}`
        headerIds.set(columnIndex, id)
        cell.properties = {
          ...properties,
          id,
          scope: "col",
        }
      } else {
        cell.properties = {
          ...properties,
          headers: headerIds.get(columnIndex),
        }
      }
    })
  })
}

function annotatePretextMarkdownGreenfieldSourceMetadata(
  nodes: readonly PretextMarkdownHastNode[],
  unified: PretextMarkdownUnifiedDocument
) {
  for (const node of nodes) {
    annotateSourceMetadataInNode(node, unified)
  }
}

function annotateSourceMetadataInNode(
  node: PretextMarkdownHastNode,
  unified: PretextMarkdownUnifiedDocument
) {
  const element = readHastElement(node)
  if (!element) return

  const sourceRange = pretextMarkdownSourceRangeFromPosition({
    position: element.position,
    sourceMap: unified.sourceMap,
  })
  if (sourceRange) {
    element.properties = {
      ...element.properties,
      dataPretextSourceEndLine: sourceRange.endLine,
      dataPretextSourceEndOffset: sourceRange.endOffset,
      dataPretextSourceStartLine: sourceRange.startLine,
      dataPretextSourceStartOffset: sourceRange.startOffset,
    }
  }

  for (const child of element.children) {
    annotateSourceMetadataInNode(child, unified)
  }
}

function tableRows(element: PretextMarkdownHastElement) {
  const rows: PretextMarkdownHastElement[] = []
  for (const child of element.children) {
    const childElement = readHastElement(child)
    if (!childElement) continue
    if (childElement.tagName === "tr") {
      rows.push(childElement)
    } else if (
      childElement.tagName === "thead" ||
      childElement.tagName === "tbody" ||
      childElement.tagName === "tfoot"
    ) {
      rows.push(...tableRows(childElement))
    }
  }
  return rows
}

function tableCells(row: PretextMarkdownHastElement) {
  return row.children
    .map(readHastElement)
    .filter(
      (child): child is PretextMarkdownHastElement =>
        child?.tagName === "td" || child?.tagName === "th"
    )
}

function isDomClobberingId(id: string) {
  return [
    "__proto__",
    "constructor",
    "document",
    "forms",
    "history",
    "location",
    "name",
    "prototype",
    "window",
  ].includes(id)
}

function pretextMarkdownBlockKindForHastChild(
  child: PretextMarkdownHastNode
): PretextMarkdownGreenfieldBlockKind {
  const element = readHastElement(child)
  if (!element) return child.type === "text" ? "paragraph" : "unknown"

  if (element.properties?.dataFootnotes != null) return "footnotes"
  if (element.properties?.dataPretextMarkdownFrontmatter != null)
    return "frontmatter"
  if (/^h[1-6]$/.test(element.tagName)) return "heading"
  if (isPretextMarkdownDiagramElement(element)) return "diagram"
  if (isPretextMarkdownComponentElement(element)) return "component"
  if (isDisplayMathElement(element)) return "math"

  switch (element.tagName) {
    case "blockquote":
      return "blockquote"
    case "hr":
      return "thematicBreak"
    case "ol":
    case "ul":
      return "list"
    case "p":
      if (isDisplayMathElement(element)) return "math"
      return firstElementChild(element)?.tagName === "img"
        ? "image"
        : "paragraph"
    case "pre":
      if (isMermaidCodeElement(element)) return "diagram"
      return "code"
    case "table":
      return "table"
    default:
      return "html"
  }
}

function isPretextMarkdownDiagramElement(element: PretextMarkdownHastElement) {
  return (
    readStringProperty(element.properties?.dataPretextComponentName) ===
    "Diagram"
  )
}

function isPretextMarkdownComponentElement(
  element: PretextMarkdownHastElement
) {
  return (
    element.properties?.dataPretextComponentName != null ||
    element.properties?.dataPretextComponentFallback != null ||
    element.properties?.dataPretextCalloutKind != null
  )
}

function isDisplayMathElement(element: PretextMarkdownHastElement): boolean {
  if (
    hasClassName(element, "katex-display") ||
    hasClassName(element, "math-display")
  )
    return true
  return element.children
    .map(readHastElement)
    .some((child) => child != null && isDisplayMathElement(child))
}

function isMermaidCodeElement(element: PretextMarkdownHastElement) {
  const code = firstElementChild(element)
  return (
    code?.tagName === "code" &&
    ["language-mermaid", "language-mmd", "language-mermaid-js"].some(
      (className) => hasClassName(code, className)
    )
  )
}

function hasClassName(element: PretextMarkdownHastElement, className: string) {
  const classes = element.properties?.className
  return Array.isArray(classes)
    ? classes.includes(className)
    : typeof classes === "string" && classes.split(/\s+/).includes(className)
}

function isHostilePretextMarkdownGreenfieldBlock({
  child,
  kind,
  sourceText,
}: {
  child: PretextMarkdownHastNode
  kind: PretextMarkdownGreenfieldBlockKind
  sourceText: string
}) {
  if (sourceText.length > HOSTILE_TEXT_LENGTH) return true
  if (countHastNodes(child) > HOSTILE_HAST_NODE_COUNT) return true
  if (maxHastDepth(child) > HOSTILE_HAST_DEPTH) return true
  if (
    kind === "code" &&
    sourceText.split(/\r\n|[\n\r\u2028\u2029]/).length > HOSTILE_CODE_LINE_COUNT
  ) {
    return true
  }
  if (kind === "table" && countTableCells(child) > HOSTILE_TABLE_CELL_COUNT) {
    return true
  }
  return false
}

function countHastNodes(node: PretextMarkdownHastNode): number {
  const element = readHastElement(node)
  return (
    1 +
    (element?.children ?? []).reduce(
      (sum, child) => sum + countHastNodes(child),
      0
    )
  )
}

function maxHastDepth(node: PretextMarkdownHastNode): number {
  const element = readHastElement(node)
  if (!element?.children.length) return 1
  return 1 + Math.max(...element.children.map(maxHastDepth))
}

function lineCountForBlocks(blocks: readonly PretextMarkdownGreenfieldBlock[]) {
  const ranges = blocks
    .map((block) => block.sourceRange)
    .filter((range): range is PretextMarkdownSourceRange => Boolean(range))
  if (!ranges.length) return blocks.length

  return (
    Math.max(...ranges.map((range) => range.endLine)) -
    Math.min(...ranges.map((range) => range.startLine)) +
    1
  )
}

function countTableCells(node: PretextMarkdownHastNode): number {
  const element = readHastElement(node)
  if (!element) return 0
  const self = element.tagName === "td" || element.tagName === "th" ? 1 : 0
  return (
    self +
    (element.children ?? []).reduce(
      (sum, child) => sum + countTableCells(child),
      0
    )
  )
}

function readHastElement(node: unknown): PretextMarkdownHastElement | null {
  return node &&
    typeof node === "object" &&
    (node as PretextMarkdownHastElement).type === "element"
    ? (node as PretextMarkdownHastElement)
    : null
}

function firstElementChild(element: PretextMarkdownHastElement) {
  return element.children.map(readHastElement).find(Boolean) ?? null
}

function isWhitespaceText(node: PretextMarkdownHastNode) {
  return (
    node.type === "text" &&
    typeof node.value === "string" &&
    node.value.trim() === ""
  )
}

function readStringProperty(value: unknown) {
  if (typeof value === "string") return value
  if (Array.isArray(value)) return value.filter(Boolean).join(" ")
  return ""
}

function extractHastText(node: PretextMarkdownHastNode): string {
  if (node.type === "text" && typeof node.value === "string") return node.value
  const element = readHastElement(node)
  if (!element) return ""
  return element.children.map(extractHastText).join("")
}

function freezePretextMarkdownHastNode(node: unknown) {
  if (!node || typeof node !== "object" || Object.isFrozen(node)) return

  const record = node as Record<string, unknown>
  for (const value of Object.values(record)) {
    if (Array.isArray(value)) {
      value.forEach(freezePretextMarkdownHastNode)
      Object.freeze(value)
      continue
    }
    if (value && typeof value === "object") {
      freezePretextMarkdownHastNode(value)
    }
  }
  Object.freeze(node)
}

function freezePretextMarkdownGreenfieldDocument(
  document: PretextMarkdownGreenfieldDocument
) {
  for (const block of document.blocks) {
    if (block.sourceRange) Object.freeze(block.sourceRange)
    Object.freeze(block.hastChildren)
    Object.freeze(block)
  }
  for (const chunk of document.chunks) {
    if (chunk.sourceRange) Object.freeze(chunk.sourceRange)
    Object.freeze(chunk.blockIds)
    Object.freeze(chunk.hastChildren)
    Object.freeze(chunk)
  }
  for (const heading of document.headings) Object.freeze(heading)
  for (const target of document.fragmentTargets) Object.freeze(target)
  Object.freeze(document.blocks)
  Object.freeze(document.chunks)
  Object.freeze(document.headings)
  Object.freeze(document.fragmentTargets)
  return Object.freeze(document)
}

function pretextMarkdownGreenfieldDocumentCacheKey(text: string) {
  let hash = 2166136261
  for (let index = 0; index < text.length; index += 1) {
    hash ^= text.charCodeAt(index)
    hash = Math.imul(hash, 16777619)
  }
  return `${text.length}:${(hash >>> 0).toString(36)}`
}

function clampSourceLine(line: number, lineCount: number) {
  if (!Number.isFinite(line)) return 1
  return Math.max(1, Math.min(lineCount, Math.floor(line)))
}

function clampSourceOffset(offset: number, textLength: number) {
  if (!Number.isFinite(offset)) return 0
  return Math.max(0, Math.min(textLength, Math.floor(offset)))
}

"use client"

import type {
  PretextMarkdownGreenfieldBlock,
  PretextMarkdownGreenfieldChunk,
  PretextMarkdownGreenfieldDocument,
} from "./pretext-markdown-greenfield-document"

const DOCUMENT_PADDING_Y = 32
const CHUNK_PADDING_X = 32
const MIN_CHUNK_HEIGHT = 64
// Tuned to the rendered typography (15.5px body at leading-relaxed ≈ 25px,
// 14px mono code at leading-5 = 20px) so estimates track measured heights and
// scroll correction stays minimal.
const BODY_LINE_HEIGHT = 25
const MONO_LINE_HEIGHT = 20
const APPROX_BODY_CHAR_WIDTH = 7.9
const APPROX_MONO_CHAR_WIDTH = 7.8
export const PRETEXT_MARKDOWN_GREENFIELD_LAYOUT_POLICY_VERSION =
  "greenfield-layout-rich-blocks-v3"
const LAYOUT_CACHE_LIMIT = 64

const pretextMarkdownGreenfieldLayoutDocumentIds = new WeakMap<
  PretextMarkdownGreenfieldDocument,
  number
>()
const pretextMarkdownGreenfieldLayoutCache = new Map<
  string,
  {
    document: PretextMarkdownGreenfieldDocument
    frame: PretextMarkdownGreenfieldFrame
  }
>()
let nextPretextMarkdownGreenfieldLayoutDocumentId = 1

export type PretextMarkdownGreenfieldFrame = {
  chunks: PretextMarkdownGreenfieldChunkFrame[]
  totalHeight: number
  width: number
}

export type PretextMarkdownGreenfieldChunkFrame = {
  bottom: number
  height: number
  id: string
  index: number
  measuredHeight: number | null
  sourceEndLine: number
  sourceStartLine: number
  top: number
}

export type PretextMarkdownGreenfieldMeasuredHeights = {
  get(
    chunk: PretextMarkdownGreenfieldChunk,
    context: PretextMarkdownGreenfieldMeasurementContext
  ): number | undefined
}

export type PretextMarkdownGreenfieldMeasurementContext = {
  fontScale: number
  policyVersion: string
  width: number
}

export function layoutPretextMarkdownGreenfieldDocument({
  contentWidth,
  document,
  fontScale,
  measuredHeights,
}: {
  contentWidth: number
  document: PretextMarkdownGreenfieldDocument
  fontScale: number
  measuredHeights?: PretextMarkdownGreenfieldMeasuredHeights
}): PretextMarkdownGreenfieldFrame {
  const width = Math.max(1, contentWidth)
  const context = {
    fontScale,
    policyVersion: PRETEXT_MARKDOWN_GREENFIELD_LAYOUT_POLICY_VERSION,
    width,
  }
  const measuredHeightByChunkId = readPretextMarkdownGreenfieldMeasuredHeights({
    context,
    document,
    measuredHeights,
  })
  const cacheKey = pretextMarkdownGreenfieldLayoutCacheKey({
    context,
    document,
    measuredHeightByChunkId,
  })
  const cached = pretextMarkdownGreenfieldLayoutCache.get(cacheKey)
  if (cached?.document === document) {
    pretextMarkdownGreenfieldLayoutCache.delete(cacheKey)
    pretextMarkdownGreenfieldLayoutCache.set(cacheKey, cached)
    return cached.frame
  }

  const blocksById = new Map(document.blocks.map((block) => [block.id, block]))
  const chunks: PretextMarkdownGreenfieldChunkFrame[] = []
  let y = DOCUMENT_PADDING_Y

  for (const chunk of document.chunks) {
    const estimatedHeight = estimatePretextMarkdownGreenfieldChunkHeight({
      blocks: chunk.blockIds
        .map((blockId) => blocksById.get(blockId))
        .filter((block): block is PretextMarkdownGreenfieldBlock =>
          Boolean(block)
        ),
      fontScale,
      width,
    })
    const measuredHeight = measuredHeightByChunkId.get(chunk.id) ?? null
    const height = Math.max(
      MIN_CHUNK_HEIGHT,
      measuredHeight == null ? estimatedHeight : measuredHeight
    )
    chunks.push({
      bottom: y + height,
      height,
      id: chunk.id,
      index: chunk.index,
      measuredHeight,
      sourceEndLine: chunk.sourceEndLine,
      sourceStartLine: chunk.sourceStartLine,
      top: y,
    })
    y += height
  }

  const frame = freezePretextMarkdownGreenfieldFrame({
    chunks,
    totalHeight: chunks.length ? y + DOCUMENT_PADDING_Y : 0,
    width,
  })
  pretextMarkdownGreenfieldLayoutCache.set(cacheKey, { document, frame })
  while (pretextMarkdownGreenfieldLayoutCache.size > LAYOUT_CACHE_LIMIT) {
    const oldestKey = pretextMarkdownGreenfieldLayoutCache.keys().next().value
    if (!oldestKey) break
    pretextMarkdownGreenfieldLayoutCache.delete(oldestKey)
  }
  return frame
}

function estimatePretextMarkdownGreenfieldChunkHeight({
  blocks,
  fontScale,
  width,
}: {
  blocks: readonly PretextMarkdownGreenfieldBlock[]
  fontScale: number
  width: number
}) {
  const textWidth = Math.max(1, width - CHUNK_PADDING_X * 2)
  const height = blocks.reduce(
    (sum, block) =>
      sum +
      estimatePretextMarkdownGreenfieldBlockHeight({
        block,
        fontScale,
        textWidth,
      }),
    0
  )
  return Math.max(MIN_CHUNK_HEIGHT, height)
}

function estimatePretextMarkdownGreenfieldBlockHeight({
  block,
  fontScale,
  textWidth,
}: {
  block: PretextMarkdownGreenfieldBlock
  fontScale: number
  textWidth: number
}) {
  if (block.kind === "thematicBreak") return 36 * fontScale
  if (block.kind === "frontmatter") {
    const lines = Math.max(
      1,
      block.sourceText.split(/\r\n|[\n\r\u2028\u2029]/).length
    )
    return (72 + lines * MONO_LINE_HEIGHT) * fontScale
  }
  if (block.kind === "footnotes")
    return estimateTextBlock(block, textWidth, fontScale, 0.9)
  if (block.kind === "heading") {
    return estimateTextBlock(block, textWidth, fontScale, 1.3) + 18 * fontScale
  }
  if (block.kind === "diagram") return 360 * fontScale
  if (block.kind === "math") return 120 * fontScale
  if (block.kind === "component") return 160 * fontScale
  if (block.kind === "code") {
    const lines = Math.max(
      1,
      block.sourceText.split(/\r\n|[\n\r\u2028\u2029]/).length
    )
    return 48 * fontScale + lines * MONO_LINE_HEIGHT * fontScale
  }
  if (block.kind === "table") {
    const rows = Math.max(2, (block.sourceText.match(/\n/g)?.length ?? 1) + 1)
    return (48 + rows * 36) * fontScale
  }
  if (block.kind === "image") return 280 * fontScale
  if (block.isHostile) return 420 * fontScale
  return estimateTextBlock(block, textWidth, fontScale, 1)
}

function estimateTextBlock(
  block: PretextMarkdownGreenfieldBlock,
  textWidth: number,
  fontScale: number,
  multiplier: number
) {
  const text = block.sourceText || " "
  const charWidth =
    block.kind === "code" ? APPROX_MONO_CHAR_WIDTH : APPROX_BODY_CHAR_WIDTH
  const columns = Math.max(12, Math.floor(textWidth / (charWidth * fontScale)))
  const sourceLines = text.split(/\r\n|[\n\r\u2028\u2029]/)
  const visualLines = sourceLines.reduce(
    (sum, line) => sum + Math.max(1, Math.ceil(line.length / columns)),
    0
  )
  return (
    16 * fontScale + visualLines * BODY_LINE_HEIGHT * fontScale * multiplier
  )
}

function readPretextMarkdownGreenfieldMeasuredHeights({
  context,
  document,
  measuredHeights,
}: {
  context: PretextMarkdownGreenfieldMeasurementContext
  document: PretextMarkdownGreenfieldDocument
  measuredHeights?: PretextMarkdownGreenfieldMeasuredHeights
}) {
  const measuredHeightByChunkId = new Map<string, number>()
  if (!measuredHeights) return measuredHeightByChunkId

  for (const chunk of document.chunks) {
    const measuredHeight = measuredHeights.get(chunk, context)
    if (
      typeof measuredHeight === "number" &&
      Number.isFinite(measuredHeight) &&
      measuredHeight > 0
    ) {
      measuredHeightByChunkId.set(chunk.id, measuredHeight)
    }
  }
  return measuredHeightByChunkId
}

function pretextMarkdownGreenfieldLayoutCacheKey({
  context,
  document,
  measuredHeightByChunkId,
}: {
  context: PretextMarkdownGreenfieldMeasurementContext
  document: PretextMarkdownGreenfieldDocument
  measuredHeightByChunkId: ReadonlyMap<string, number>
}) {
  return [
    pretextMarkdownGreenfieldLayoutDocumentId(document),
    Math.round(context.width * 100) / 100,
    context.fontScale.toFixed(4),
    context.policyVersion,
    document.chunks
      .map((chunk) => {
        const measuredHeight = measuredHeightByChunkId.get(chunk.id)
        return `${chunk.id}:${measuredHeight == null ? "-" : measuredHeight.toFixed(2)}`
      })
      .join("|"),
  ].join(":")
}

function pretextMarkdownGreenfieldLayoutDocumentId(
  document: PretextMarkdownGreenfieldDocument
) {
  const existing = pretextMarkdownGreenfieldLayoutDocumentIds.get(document)
  if (existing) return existing
  const next = nextPretextMarkdownGreenfieldLayoutDocumentId++
  pretextMarkdownGreenfieldLayoutDocumentIds.set(document, next)
  return next
}

function freezePretextMarkdownGreenfieldFrame(
  frame: PretextMarkdownGreenfieldFrame
) {
  for (const chunk of frame.chunks) Object.freeze(chunk)
  Object.freeze(frame.chunks)
  return Object.freeze(frame)
}

"use client"

import * as React from "react"
import { Fragment, jsx, jsxs } from "react/jsx-runtime"
import { toJsxRuntime } from "hast-util-to-jsx-runtime"
import {
  BadgeAlert,
  Check,
  CircleAlert,
  Copy,
  ExternalLink,
  Info,
  Lightbulb,
  Link2,
  TriangleAlert,
} from "lucide-react"

import {
  diffLineKind,
  isSafeHighlightedCodeLine,
  normalizeCodeLanguage,
  renderCodeLine,
  useShikiCodeLines,
} from "./pretext-markdown-greenfield-code-highlight"
import { PretextMarkdownGreenfieldDiagram } from "./pretext-markdown-greenfield-diagram"
import type { PretextMarkdownGreenfieldChunk } from "./pretext-markdown-greenfield-document"
import type {
  PretextMarkdownHastElement,
  PretextMarkdownHastNode,
  PretextMarkdownHastRoot,
} from "./pretext-markdown-hast-types"
import {
  sanitizePretextMarkdownImageUrl,
  sanitizePretextMarkdownMediaUrl,
  sanitizePretextMarkdownUrl,
} from "./pretext-markdown-url-policy"

const PretextMarkdownContentReadyContext = React.createContext<
  (() => void) | null
>(null)

// The rendered body size at 100% zoom. Every other size (headings, code,
// tables, footnotes) is authored in `em` relative to this, so scaling this one
// value with the zoom `fontScale` resizes the whole document as one system.
export const PRETEXT_MARKDOWN_GREENFIELD_BASE_FONT_PX = 15.5
// Tailwind v4's default spacing unit (0.25rem). Scaling it with the zoom
// fontScale keeps padding/margins proportional to the body text.
export const PRETEXT_MARKDOWN_GREENFIELD_BASE_SPACING_REM = 0.25

export function PretextMarkdownGreenfieldChunkRenderer({
  activeMatchOccurrence,
  chunk,
  fontScale = 1,
  onContentReady,
  searchQuery,
}: {
  activeMatchOccurrence?: number
  chunk: PretextMarkdownGreenfieldChunk
  fontScale?: number
  onContentReady?: () => void
  searchQuery?: string
}) {
  const ref = React.useRef<HTMLDivElement | null>(null)
  const notifyContentReady = React.useCallback(() => {
    onContentReady?.()
  }, [onContentReady])

  React.useLayoutEffect(() => {
    notifyContentReady()
    const element = ref.current
    if (!element || typeof ResizeObserver === "undefined") return
    const observer = new ResizeObserver(notifyContentReady)
    observer.observe(element)
    return () => observer.disconnect()
  }, [chunk.id, notifyContentReady])

  if (chunk.isHostile) {
    return <PretextMarkdownGreenfieldHostileChunk chunk={chunk} />
  }

  return (
    <PretextMarkdownContentReadyContext.Provider value={notifyContentReady}>
      <div
        ref={ref}
        className="pretext-markdown-greenfield-content min-w-0 leading-relaxed text-foreground"
        data-slot="pretext-markdown-greenfield-content"
        // Scale both the font and the spacing scale with zoom so vertical
        // rhythm tracks the type size. Tailwind v4 spacing utilities resolve to
        // calc(var(--spacing) * n), so overriding --spacing here scales every
        // margin/padding/gap inside the document at once.
        style={
          {
            "--spacing": `${(PRETEXT_MARKDOWN_GREENFIELD_BASE_SPACING_REM * fontScale).toFixed(5)}rem`,
            fontSize: `${PRETEXT_MARKDOWN_GREENFIELD_BASE_FONT_PX * fontScale}px`,
          } as React.CSSProperties
        }
      >
        {renderHastChildren(
          chunk.hastChildren,
          searchQuery,
          activeMatchOccurrence
        )}
      </div>
    </PretextMarkdownContentReadyContext.Provider>
  )
}

function renderHastChildren(
  children: readonly PretextMarkdownHastNode[],
  searchQuery?: string,
  activeMatchOccurrence?: number
) {
  const root: PretextMarkdownHastRoot = {
    type: "root",
    children: children.map(cloneHastNode),
  }

  const normalizedQuery = searchQuery?.trim().toLowerCase()
  if (normalizedQuery) {
    // The counter tracks rendered occurrences in document order so the one at
    // activeMatchOccurrence (the chunk-local index of the toolbar's current
    // match) can be marked active and styled distinctly from the rest.
    highlightPretextMarkdownSearchMatches(root.children, normalizedQuery, {
      count: 0,
      active: activeMatchOccurrence ?? -1,
    })
  }

  return toJsxRuntime(root as never, {
    Fragment,
    components: markdownComponents,
    ignoreInvalidStyle: true,
    jsx,
    jsxs,
    passKeys: true,
    passNode: true,
  })
}

const markdownComponents = {
  a: ({
    children,
    href,
    node: _node,
    rel: _rel,
    target: _target,
    ...props
  }: any) => {
    const safeHref = sanitizePretextMarkdownUrl(href ?? "")
    if (!safeHref) return <span>{children}</span>
    const text = reactNodeText(children)
    const kind = linkKindForHref(safeHref)
    const form = linkFormForHref({
      href: safeHref,
      text,
    })
    const external = kind === "external"
    return (
      <a
        {...props}
        className={[
          "font-medium [overflow-wrap:anywhere] text-primary underline decoration-muted-foreground/50 underline-offset-4 visited:text-muted-foreground hover:decoration-current",
          kind === "fragment" ? "decoration-dotted" : "",
          form !== "inline" ? "font-mono" : "",
        ]
          .filter(Boolean)
          .join(" ")}
        data-pretext-link-form={form}
        data-pretext-link-kind={kind}
        href={safeHref}
        aria-label={footnoteLabelForLink({
          href: safeHref,
          label: props["aria-label"],
          text,
        })}
        rel={external ? "noopener noreferrer" : undefined}
        target={external ? "_blank" : undefined}
      >
        {children}
        {external ? (
          <ExternalLink className="ml-1 inline size-3" aria-hidden="true" />
        ) : null}
      </a>
    )
  },
  br: ({ node: _node, ...props }: any) => (
    <br {...props} data-pretext-line-break="soft" />
  ),
  abbr: ({ node: _node, ...props }: any) => (
    <abbr
      {...props}
      className="cursor-help underline decoration-dotted"
      data-pretext-raw-inline=""
    />
  ),
  blockquote: ({ children, node, ...props }: any) => {
    const alertKind = readDataProperty(node, "dataPretextAlertKind")
    const alertTitle = readDataProperty(node, "dataPretextAlertTitle")
    if (alertKind) {
      const label = String(alertTitle || alertKind)
      const Icon = alertIconForKind(alertKind)
      const alertProps = withoutPretextAlertMetadata(props)
      return (
        <aside
          {...alertProps}
          aria-label={label}
          className="my-5 rounded-md border bg-muted/35 px-4 py-3"
          data-pretext-alert-kind={alertKind}
          role="note"
        >
          <div
            className="mb-2 flex items-center gap-2 text-[0.9em] font-semibold text-foreground"
            data-pretext-alert-title=""
          >
            <Icon className="size-[1.15em]" aria-hidden="true" />
            {label}
          </div>
          <div
            className="[&>*:first-child]:mt-0 [&>*:last-child]:mb-0"
            data-pretext-alert-body=""
          >
            {children}
          </div>
        </aside>
      )
    }

    return (
      <blockquote
        {...props}
        className="my-4 border-l-2 border-border pl-4 text-muted-foreground italic [&_blockquote]:my-3 [&_ol]:list-[lower-alpha] [&>ul]:my-2"
      >
        {children}
      </blockquote>
    )
  },
  code: ({ children, className, node: _node, ...props }: any) => (
    <code
      {...props}
      className={[
        "rounded bg-muted px-1 py-0.5 font-mono text-[0.88em]",
        className,
      ]
        .filter(Boolean)
        .join(" ")}
    >
      {children}
    </code>
  ),
  caption: ({ node: _node, ...props }: any) => (
    <caption
      {...props}
      className="caption-top px-3 py-2 text-left text-[0.85em] font-medium text-muted-foreground"
    />
  ),
  del: ({ node: _node, ...props }: any) => (
    <del
      {...props}
      className="text-muted-foreground decoration-muted-foreground/70 decoration-2"
      data-pretext-strikethrough=""
    />
  ),
  details: ({ node: _node, ...props }: any) => (
    <details {...props} className="my-4 rounded-md border bg-muted/25 p-3" />
  ),
  dl: ({ node: _node, ...props }: any) => (
    <dl {...props} className="my-4 space-y-2" data-pretext-definition-list="" />
  ),
  dt: ({ node: _node, ...props }: any) => (
    <dt {...props} className="font-semibold" data-pretext-definition-term="" />
  ),
  dd: ({ node: _node, ...props }: any) => (
    <dd
      {...props}
      className="ml-4 text-muted-foreground"
      data-pretext-definition-description=""
    />
  ),
  div: ({ children, node, ...props }: any) => {
    const calloutKind = readTrustedDataProperty(node, "dataPretextCalloutKind")
    if (calloutKind) {
      const title =
        readTrustedDataProperty(node, "dataPretextCalloutTitle") ||
        calloutTitle(calloutKind)
      return (
        <aside
          aria-label={title}
          className="my-5 rounded-md border bg-muted/35 px-4 py-3"
          data-pretext-callout-kind={calloutKind}
          role="note"
        >
          <div className="mb-2 text-[0.9em] font-semibold">{title}</div>
          <div className="[&>*:first-child]:mt-0 [&>*:last-child]:mb-0">
            {children}
          </div>
        </aside>
      )
    }

    const componentName = readDataProperty(node, "dataPretextComponentName")
    const trusted = isTrustedPretextComponentNode(node)
    if (trusted && hasDataProperty(node, "dataPretextComponentFallback")) {
      return (
        <div
          data-pretext-component-fallback=""
          data-pretext-component-fallback-name={readDataProperty(
            node,
            "dataPretextComponentFallbackName"
          )}
          data-pretext-component-fallback-reason={readDataProperty(
            node,
            "dataPretextComponentFallbackReason"
          )}
          data-pretext-component-fallback-source={readDataProperty(
            node,
            "dataPretextComponentFallbackSource"
          )}
        >
          {children}
        </div>
      )
    }
    if (trusted && componentName === "Metric") {
      const componentProps = readComponentProps(
        readDataProperty(node, "dataPretextComponentProps")
      )
      return (
        <div
          className="my-4 w-fit max-w-full min-w-0 rounded-md border bg-muted/25 px-4 py-3"
          data-pretext-component="Metric"
        >
          <div className="text-[0.9em] [overflow-wrap:anywhere] text-muted-foreground">
            {readOptionalString(componentProps.label)}
          </div>
          <div className="text-[1.55em] font-semibold [overflow-wrap:anywhere]">
            {readOptionalString(componentProps.value)}
          </div>
        </div>
      )
    }
    if (trusted && componentName === "Badge") {
      const componentProps = readComponentProps(
        readDataProperty(node, "dataPretextComponentProps")
      )
      return (
        <span
          className="inline-flex max-w-full items-center rounded-md border bg-muted/35 px-2 py-0.5 text-[0.9em] font-medium [overflow-wrap:anywhere]"
          data-pretext-component="Badge"
        >
          {readOptionalString(componentProps.label)}
        </span>
      )
    }
    if (trusted && componentName === "Callout") {
      const componentProps = readComponentProps(
        readDataProperty(node, "dataPretextComponentProps")
      )
      const kind = readOptionalString(componentProps.kind) ?? "note"
      const title =
        readOptionalString(componentProps.title) ?? calloutTitle(kind)
      return (
        <aside
          aria-label={title}
          className="my-5 rounded-md border bg-muted/35 px-4 py-3"
          data-pretext-callout-kind={kind}
          data-pretext-component="Callout"
          role="note"
        >
          <div className="mb-2 text-[0.9em] font-semibold">{title}</div>
          <div className="[&>*:first-child]:mt-0 [&>*:last-child]:mb-0">
            {children}
          </div>
        </aside>
      )
    }
    if (trusted && componentName === "Accordion") {
      const componentProps = readComponentProps(
        readDataProperty(node, "dataPretextComponentProps")
      )
      return (
        <details
          className="my-4 rounded-md border bg-muted/25 p-3"
          data-pretext-component="Accordion"
        >
          <summary className="cursor-pointer font-medium">
            {readOptionalString(componentProps.title)}
          </summary>
          <div className="mt-3 [&>*:first-child]:mt-0 [&>*:last-child]:mb-0">
            {children}
          </div>
        </details>
      )
    }
    if (trusted && componentName === "Tabs") {
      return <PretextMarkdownTabs node={readHastElement(node)} />
    }
    if (trusted && componentName === "Image") {
      const componentProps = readComponentProps(
        readDataProperty(node, "dataPretextComponentProps")
      )
      return (
        <PretextMarkdownImageSurface
          alt={readOptionalString(componentProps.alt) ?? ""}
          componentName="Image"
          height={readOptionalNumber(componentProps.height)}
          src={readOptionalString(componentProps.src) ?? ""}
          title={readOptionalString(componentProps.title)}
          width={readOptionalNumber(componentProps.width)}
        />
      )
    }
    if (trusted && componentName === "Video") {
      const componentProps = readComponentProps(
        readDataProperty(node, "dataPretextComponentProps")
      )
      return (
        <PretextMarkdownVideoSurface
          controls={readOptionalBoolean(componentProps.controls) ?? true}
          label={readOptionalString(componentProps.label) ?? "Video"}
          loop={readOptionalBoolean(componentProps.loop) ?? false}
          muted={readOptionalBoolean(componentProps.muted) ?? false}
          src={readOptionalString(componentProps.src) ?? ""}
          title={readOptionalString(componentProps.title)}
        />
      )
    }
    if (trusted && componentName === "Diagram") {
      const componentProps = readComponentProps(
        readDataProperty(node, "dataPretextComponentProps")
      )
      if (
        componentProps.type === "mermaid" &&
        typeof componentProps.source === "string"
      ) {
        return (
          <PretextMarkdownMeasuredDiagram
            caption={readOptionalString(componentProps.caption)}
            componentName="Diagram"
            source={componentProps.source}
            title={readOptionalString(componentProps.title)}
          />
        )
      }
    }

    return <div {...withoutInternalPretextMetadata(props)}>{children}</div>
  },
  h1: headingComponent(
