function headingComponent(
  Tag: "h1" | "h2" | "h3" | "h4" | "h5" | "h6",
  blockClassName: string,
  textClassName: string
) {
  return function Heading({ children, node, ...props }: any) {
    const id = typeof props.id === "string" ? props.id : ""
    const text =
      extractHastText(readHastElement(node)) || reactNodeText(children)
    if (!id) {
      return (
        <Tag {...props} className={`${blockClassName} ${textClassName}`}>
          {children}
        </Tag>
      )
    }
    return (
      <div className={`group/heading relative ${blockClassName}`}>
        <Tag {...props} className={textClassName}>
          {children}
        </Tag>
        <HeadingAnchor id={id} text={text} />
      </div>
    )
  }
}

// A GitHub-style anchor that appears in the left gutter on hover/focus and
// copies a deep link to the heading. Kept as a sibling of the heading (not a
// child) so it never leaks into the heading's accessible name.
function HeadingAnchor({ id, text }: { id: string; text: string }) {
  const [copied, setCopied] = React.useState(false)
  return (
    <button
      aria-label={`Copy link to ${text}`}
      className="absolute top-1/2 -left-7 inline-flex size-6 -translate-y-1/2 items-center justify-center rounded text-muted-foreground opacity-0 transition-opacity group-hover/heading:opacity-100 hover:text-foreground focus-visible:opacity-100"
      type="button"
      onClick={() => {
        copyHeadingLink(id)
        setCopied(true)
        window.setTimeout(() => setCopied(false), 1200)
      }}
    >
      {copied ? (
        <Check className="size-4" aria-hidden="true" />
      ) : (
        <Link2 className="size-4" aria-hidden="true" />
      )}
    </button>
  )
}

function PretextMarkdownGreenfieldHostileChunk({
  chunk,
}: {
  chunk: PretextMarkdownGreenfieldChunk
}) {
  const sourceLines = React.useMemo(
    () => chunk.sourceText.split(/\r\n|[\n\r\u2028\u2029]/),
    [chunk.sourceText]
  )
  const [scrollTop, setScrollTop] = React.useState(0)
  const lineHeight = 24
  const viewportHeight = 576
  const start = Math.max(0, Math.floor(scrollTop / lineHeight) - 12)
  const end = Math.min(
    sourceLines.length,
    Math.ceil((scrollTop + viewportHeight) / lineHeight) + 12
  )
  const mountedLines = sourceLines.slice(start, end)
  const omittedLines = Math.max(0, sourceLines.length - mountedLines.length)

  return (
    <section
      aria-label="Large Markdown block"
      className="overflow-hidden rounded-md border bg-muted/25 text-sm text-muted-foreground"
      data-pretext-markdown-hostile-fallback=""
      data-pretext-markdown-hostile-line-count={sourceLines.length}
      data-pretext-markdown-hostile-mounted-lines={mountedLines.length}
      data-pretext-markdown-hostile-omitted-lines={omittedLines}
      data-pretext-markdown-hostile-virtualized=""
    >
      <div className="flex items-center justify-between gap-3 border-b bg-muted/55 px-3 py-2 font-medium text-foreground">
        Large Markdown block
        <button
          aria-label="Copy large Markdown block source"
          className="text-xs text-muted-foreground underline underline-offset-4"
          type="button"
          onClick={() => void navigator.clipboard?.writeText(chunk.sourceText)}
        >
          Copy
        </button>
      </div>
      <pre
        aria-label="Large Markdown source preview"
        className="max-h-[36rem] overflow-auto bg-background/60 font-mono text-[13px] whitespace-pre"
        data-pretext-markdown-hostile-preview=""
        role="region"
        tabIndex={0}
        onScroll={(event) => setScrollTop(event.currentTarget.scrollTop)}
      >
        <code
          className="relative block min-w-max"
          data-pretext-markdown-hostile-scroll-canvas=""
          style={{ height: Math.max(sourceLines.length, 1) * lineHeight }}
        >
          {mountedLines.map((line, index) => {
            const lineNumber = start + index + 1
            return (
              <span
                key={lineNumber}
                className="absolute inset-x-0 grid grid-cols-[4rem_minmax(0,1fr)] px-4"
                data-pretext-markdown-hostile-line={lineNumber}
                style={{
                  height: lineHeight,
                  lineHeight: `${lineHeight}px`,
                  top: (lineNumber - 1) * lineHeight,
                }}
              >
                <span
                  aria-hidden="true"
                  className="pr-4 text-right text-muted-foreground select-none"
                >
                  {lineNumber}
                </span>
                <span>{line || " "}</span>
              </span>
            )
          })}
        </code>
      </pre>
    </section>
  )
}

function PretextMarkdownCodeBlock({
  children: _children,
  language,
  metadata,
  source,
}: {
  children: React.ReactNode
  language: string
  metadata: ReturnType<typeof readCodeMetadata>
  source: string
}) {
  const [copyFailed, setCopyFailed] = React.useState(false)
  const title = metadata.title || language
  const sourceLines = source.split("\n")
  const shikiLines = useShikiCodeLines(source, language, sourceLines.length)
  const lineNumberStart = metadata.lineNumberStart ?? 1
  const lineNumberMaxDigits = String(
    lineNumberStart + Math.max(0, sourceLines.length - 1)
  ).length

  const copy = React.useCallback(
    async (selectedOnly: boolean) => {
      const selection = window.getSelection()
      const selectedText =
        selectedOnly && selection?.rangeCount
          ? selection.toString().trimEnd()
          : ""
      try {
        await navigator.clipboard?.writeText(selectedText || source)
        setCopyFailed(false)
      } catch {
        setCopyFailed(true)
      }
    },
    [source]
  )

  return (
    <figure
      aria-label={`${title} code block`}
      // text-[1em] keeps the code block on the document's scaling em cascade:
      // a host stylesheet (e.g. the demo's rehype-pretty-code rule) may pin
      // [data-rehype-pretty-code-figure] to a fixed font-size, which would stop
      // the block from following the zoom control. A utility-layer size wins.
      className="my-5 overflow-hidden rounded-md border bg-muted/25 text-[1em]"
      data-pretext-code-language={language}
      data-rehype-pretty-code-figure=""
      role="group"
    >
      <figcaption className="flex items-center justify-between gap-3 border-b bg-muted/55 px-3 py-2 text-sm">
        <span
          className="font-mono text-xs font-medium text-muted-foreground"
          data-pretext-code-title={metadata.title || undefined}
        >
          {title}
        </span>
        <span className="flex items-center gap-2">
          {copyFailed ? (
            <span aria-label="Copy failed" className="text-xs text-destructive">
              Copy failed
            </span>
          ) : null}
          <button
            aria-label="Copy code block"
            className="text-xs text-muted-foreground underline underline-offset-4"
            type="button"
            onClick={() => void copy(false)}
          >
            Copy
          </button>
          <button
            aria-label="Copy selected code or block"
            className="sr-only"
            type="button"
            onClick={() => void copy(true)}
          />
        </span>
      </figcaption>
      <pre
        aria-label={`${language} code source`}
        className="overflow-x-auto p-3 [overflow-wrap:normal] [&_code]:min-w-max"
        data-pretext-code-source=""
        role="region"
        tabIndex={0}
        onKeyDown={handleHorizontalScrollKeyDown}
      >
        <code
          aria-label={
            metadata.showLineNumbers
              ? `${language} numbered code lines`
              : undefined
          }
          className={[
            "block font-mono text-[0.9em] leading-[1.45]",
            metadata.showLineNumbers
              ? "[counter-reset:line] before:content-[counter(line)]"
              : "",
            metadata.highlightedLines.size
              ? "[&>[data-highlighted-line]]:bg-primary/10"
              : "",
            metadata.highlightPattern
              ? "[&_[data-highlighted-chars]]:rounded [&_[data-highlighted-chars]]:bg-primary/20"
              : "",
          ]
            .filter(Boolean)
            .join(" ")}
          data-language={language}
          data-line-numbers={metadata.showLineNumbers ? "" : undefined}
          data-line-numbers-max-digits={
            metadata.showLineNumbers ? lineNumberMaxDigits : undefined
          }
          role={metadata.showLineNumbers ? "list" : undefined}
          style={
            metadata.showLineNumbers
              ? { counterSet: `line ${lineNumberStart - 1}` }
              : undefined
          }
        >
          {sourceLines.map((line, index) => {
            const lineNumber = lineNumberStart + index
            const diffKind = diffLineKind(line)
            return (
              <span
                key={index}
                aria-label={
                  metadata.showLineNumbers ? `Line ${lineNumber}` : undefined
                }
                className={[
                  "block min-h-5 whitespace-pre",
                  diffKind === "add" ? "bg-emerald-500/10" : "",
                  diffKind === "remove" ? "bg-red-500/10" : "",
                ]
                  .filter(Boolean)
                  .join(" ")}
                data-highlighted-line={
                  metadata.highlightedLines.has(index + 1) ? "" : undefined
                }
                data-line=""
                data-pretext-code-diff-line={diffKind ?? undefined}
                data-pretext-code-line-number={
                  metadata.showLineNumbers ? lineNumber : undefined
                }
                role={metadata.showLineNumbers ? "listitem" : undefined}
              >
                {renderCodeLine({
                  fallbackLanguage: language,
                  line,
                  pattern: metadata.highlightPattern,
                  shikiLine: shikiLines?.[index],
                })}
              </span>
            )
          })}
        </code>
      </pre>
      {metadata.caption ? (
        <figcaption
          className="border-t px-3 py-2 text-[0.9em] text-muted-foreground"
          data-pretext-code-caption=""
        >
          {metadata.caption}
        </figcaption>
      ) : null}
    </figure>
  )
}

function PretextMarkdownMeasuredDiagram({
  caption,
  componentName,
  source,
  title,
}: {
  caption?: string
  componentName?: string
  source: string
  title?: string
}) {
  const notifyContentReady = React.useContext(
    PretextMarkdownContentReadyContext
  )
  return (
    <PretextMarkdownGreenfieldDiagram
      caption={caption}
      componentName={componentName}
      onContentReady={notifyContentReady ?? undefined}
      source={source}
      title={title}
    />
  )
}

function PretextMarkdownImageSurface({
  alt,
  componentName,
  height,
  src,
  title,
  width,
}: {
  alt: string
  componentName?: string
  height?: number
  src: string
  title?: string
  width?: number
}) {
  const notifyContentReady = React.useContext(
    PretextMarkdownContentReadyContext
  )
  const safeSrc = sanitizePretextMarkdownImageUrl(src)
  const explicitAspectRatio =
    width && height ? `${width} / ${height}` : undefined
  const [state, setState] = React.useState<
    "blocked" | "failed" | "loading" | "ready"
  >(safeSrc ? "loading" : "blocked")
  const [aspectRatio, setAspectRatio] = React.useState(
    () => explicitAspectRatio ?? ""
  )
  const captionId = React.useId()

  // Reset load state when the source/aspect-ratio inputs change by adjusting
  // state during render (React's prop-change pattern) instead of in an effect.
  const sourceResetKey = `${safeSrc}�${explicitAspectRatio ?? ""}`
  const [prevSourceResetKey, setPrevSourceResetKey] =
    React.useState(sourceResetKey)
  if (sourceResetKey !== prevSourceResetKey) {
    setPrevSourceResetKey(sourceResetKey)
    setState(safeSrc ? "loading" : "blocked")
    setAspectRatio(explicitAspectRatio ?? "")
  }

  React.useLayoutEffect(() => {
    notifyContentReady?.()
  }, [aspectRatio, notifyContentReady, state])

  return (
    <figure
      aria-label={
        state === "failed" ? `Image failed: ${alt}` : alt || title || "Image"
      }
      className="my-5 w-fit max-w-full"
      data-pretext-component={componentName}
      data-pretext-image-height={height}
      data-pretext-image-state={state}
      data-pretext-image-src={safeSrc || undefined}
      data-pretext-image-width={width}
      role="group"
      style={aspectRatio ? { aspectRatio } : undefined}
    >
      {safeSrc ? (
        <div
          className="relative flex min-h-48 max-w-full items-center justify-center overflow-hidden rounded-md border bg-muted/25"
          data-pretext-image-frame=""
          style={aspectRatio ? { aspectRatio } : undefined}
        >
          {state === "loading" ? (
            <span className="absolute inset-x-4 top-1/2 -translate-y-1/2 text-center text-sm text-muted-foreground">
              Loading image
            </span>
          ) : null}
          {state === "failed" ? (
            <div
              className="absolute inset-0 flex items-center justify-center px-4 text-center text-sm text-muted-foreground"
              role="alert"
            >
              Could not load image{alt ? `: ${alt}` : ""}
            </div>
          ) : null}
          {state === "failed" ? (
            <div
              aria-label={alt || "Image"}
              className="text-sm text-muted-foreground"
              data-pretext-image-state="failed"
              role="img"
            >
              Image failed to load: {alt}
              <button
                className="ml-2 text-xs underline underline-offset-4"
                type="button"
                onClick={() => setState("loading")}
              >
                Retry image
              </button>
            </div>
          ) : (
            <img
              alt={alt}
              aria-describedby={title ? captionId : undefined}
              className={[
                "block max-h-[70vh] max-w-full object-contain transition-opacity",
                state === "loading" ? "opacity-0" : "",
              ]
                .filter(Boolean)
                .join(" ")}
              decoding="async"
              loading="lazy"
              src={safeSrc}
              title={title}
              onError={(event) => {
                event.currentTarget.setAttribute(
                  "data-pretext-image-state",
                  "failed"
                )
                setState("failed")
              }}
              onLoad={(event) => {
                const image = event.currentTarget
                if (image.naturalWidth && image.naturalHeight) {
                  setAspectRatio(
                    `${image.naturalWidth} / ${image.naturalHeight}`
                  )
                }
                setState("ready")
              }}
            />
          )}
        </div>
      ) : (
        <span
          aria-label={alt || "Blocked image"}
          className="flex min-h-24 items-center rounded-md border border-dashed bg-muted/35 px-4 text-sm text-muted-foreground"
          role="img"
        >
          {alt || "Blocked image"}
        </span>
      )}
      {title ? (
        <figcaption
          id={captionId}
          className="mt-2 text-[0.9em] text-muted-foreground"
          data-pretext-image-caption=""
        >
          {title}
        </figcaption>
      ) : null}
    </figure>
  )
}

function PretextMarkdownVideoSurface({
  controls = true,
  label,
  loop = false,
  muted = false,
  src,
  title,
}: {
  controls?: boolean
  label: string
  loop?: boolean
  muted?: boolean
  src: string
  title?: string
}) {
  const notifyContentReady = React.useContext(
    PretextMarkdownContentReadyContext
  )
  const safeSrc = sanitizePretextMarkdownMediaUrl(src)
  const [failed, setFailed] = React.useState(false)
  React.useLayoutEffect(() => {
    notifyContentReady?.()
  }, [failed, notifyContentReady, safeSrc])
  if (!safeSrc) {
    return (
      <div
        aria-label={`Video blocked: ${label}`}
        className="my-5 rounded-md border border-dashed bg-muted/35 p-4 text-sm text-muted-foreground"
        data-pretext-component="Video"
        data-pretext-video-state="blocked"
        role="group"
      >
        {label}
      </div>
    )
  }
  return (
    <figure
      aria-label={failed ? `Video failed to load: ${label}` : label}
      className="my-5 max-w-full"
      data-pretext-component="Video"
      data-pretext-video-state={failed ? "failed" : "ready"}
      role="group"
    >
      <video
        className="block max-h-[70vh] max-w-full rounded-md border bg-muted"
        controls={controls}
        loop={loop}
        muted={muted}
        preload="metadata"
        src={safeSrc}
        title={title}
        onError={() => setFailed(true)}
      />
      {title ? (
        <figcaption className="mt-2 text-[0.9em] text-muted-foreground">
          {title}
        </figcaption>
      ) : null}
    </figure>
  )
}

function PretextMarkdownTabs({
  node,
}: {
  node: PretextMarkdownHastElement | null
}) {
  const props = readComponentProps(
    readDataProperty(node, "dataPretextComponentProps")
  )
  const tabs = (node?.children ?? [])
    .map(readHastElement)
    .filter((child): child is PretextMarkdownHastElement => {
      return (
        child?.tagName === "div" &&
        readDataProperty(child, "dataPretextComponentName") === "Tab"
      )
    })
  const [selected, setSelected] = React.useState(0)
  const baseId = React.useId()
  const label = readOptionalString(props.label) ?? "Tabs"

  const select = (index: number) =>
    setSelected((index + tabs.length) % tabs.length)

  return (
    <div className="my-5" data-pretext-component="Tabs">
      <div aria-label={label} className="flex gap-1 border-b" role="tablist">
        {tabs.map((tab, index) => {
          const tabProps = readComponentProps(
            readDataProperty(tab, "dataPretextComponentProps")
          )
          const title = readOptionalString(tabProps.title) ?? `Tab ${index + 1}`
          const active = selected === index
          return (
            <button
              key={index}
              aria-controls={`${baseId}-panel-${index}`}
              aria-selected={active}
              className="px-3 py-2 text-sm font-medium"
              id={`${baseId}-tab-${index}`}
              role="tab"
              tabIndex={active ? 0 : -1}
              type="button"
              onClick={() => select(index)}
              onKeyDown={(event) => {
                if (event.key === "ArrowRight") {
                  event.preventDefault()
                  const nextIndex = (index + 1) % tabs.length
                  select(nextIndex)
                  document.getElementById(`${baseId}-tab-${nextIndex}`)?.focus()
                } else if (event.key === "End") {
                  event.preventDefault()
                  select(tabs.length - 1)
                  document
                    .getElementById(`${baseId}-tab-${tabs.length - 1}`)
                    ?.focus()
                } else if (event.key === "Home") {
                  event.preventDefault()
                  select(0)
                  document.getElementById(`${baseId}-tab-0`)?.focus()
                }
              }}
            >
              {title}
            </button>
          )
        })}
      </div>
      {tabs.map((tab, index) => (
        <div
          key={index}
          aria-labelledby={`${baseId}-tab-${index}`}
          hidden={selected !== index}
          id={`${baseId}-panel-${index}`}
          className="pt-3"
          role="tabpanel"
        >
          {renderHastChildren(tab.children)}
        </div>
      ))}
    </div>
  )
}

// Tags whose text is verbatim source (code) or already a highlight; wrapping a
// match inside them would corrupt the rendered output, so they are skipped.
const PRETEXT_MARKDOWN_SEARCH_SKIP_TAGS = new Set([
  "code",
  "pre",
  "mark",
  "script",
  "style",
  "textarea",
])

// Browser-find-style highlighting for the in-app search: wraps every case-
// insensitive occurrence of the active query in a <mark> so matches are visible
// where the search navigates. Mutates the freshly cloned chunk tree in place,
// matching the same trimmed-substring semantics as the toolbar match count.
type PretextMarkdownSearchHighlightContext = { active: number; count: number }

function highlightPretextMarkdownSearchMatches(
  nodes: PretextMarkdownHastNode[],
  lowerQuery: string,
  context: PretextMarkdownSearchHighlightContext
) {
  for (let index = 0; index < nodes.length; index += 1) {
    const node = nodes[index]
    if (node.type === "text" && typeof node.value === "string") {
      const replacement = splitPretextMarkdownTextForSearch(
        node.value,
        lowerQuery,
        context
      )
      if (replacement) {
        nodes.splice(index, 1, ...replacement)
        index += replacement.length - 1
      }
      continue
    }
    if (node.type === "element" && Array.isArray(node.children)) {
      const tagName = (node as PretextMarkdownHastElement).tagName.toLowerCase()
      if (PRETEXT_MARKDOWN_SEARCH_SKIP_TAGS.has(tagName)) continue
      highlightPretextMarkdownSearchMatches(node.children, lowerQuery, context)
    }
  }
}

function splitPretextMarkdownTextForSearch(
  value: string,
  lowerQuery: string,
  context: PretextMarkdownSearchHighlightContext
): PretextMarkdownHastNode[] | null {
  const lowerValue = value.toLowerCase()
  let matchStart = lowerValue.indexOf(lowerQuery)
  if (matchStart === -1) return null

  const out: PretextMarkdownHastNode[] = []
  let cursor = 0
  while (matchStart !== -1) {
    if (matchStart > cursor) {
      out.push({ type: "text", value: value.slice(cursor, matchStart) })
    }
    const matchEnd = matchStart + lowerQuery.length
    const isActive = context.count === context.active
    context.count += 1
    out.push({
      type: "element",
      tagName: "mark",
      properties: isActive
        ? { dataPretextSearchMatch: "", dataPretextSearchMatchActive: "" }
        : { dataPretextSearchMatch: "" },
      children: [{ type: "text", value: value.slice(matchStart, matchEnd) }],
    })
    cursor = matchEnd
    matchStart = lowerValue.indexOf(lowerQuery, cursor)
  }
  if (cursor < value.length) {
    out.push({ type: "text", value: value.slice(cursor) })
  }
  return out
}

function cloneHastNode<T extends PretextMarkdownHastNode>(node: T): T {
  if (!("children" in node) || !Array.isArray(node.children)) {
    return { ...node }
  }

  return {
    ...node,
    children: node.children.map((child) =>
      cloneHastNode(child as PretextMarkdownHastNode)
    ),
    properties: readHastElement(node)?.properties
      ? { ...readHastElement(node)!.properties }
      : undefined,
  } as T
}

function readDataProperty(node: unknown, property: string) {
  const element = readHastElement(node)
  const value =
    element?.properties?.[property] ?? element?.properties?.[toKebab(property)]
  return typeof value === "string" ? value : ""
}

function readTrustedDataProperty(node: unknown, property: string) {
  if (!isTrustedPretextComponentNode(node)) return ""
  return readDataProperty(node, property)
}

function isTrustedPretextComponentNode(node: unknown) {
  return readHastElement(node)?.properties?.pretextComponentTrusted === true
}

function hasDataProperty(node: unknown, property: string) {
  const element = readHastElement(node)
  return (
    element?.properties != null &&
    (Object.hasOwn(element.properties, property) ||
      Object.hasOwn(element.properties, toKebab(property)))
  )
}

function withoutPretextAlertMetadata(props: Record<string, unknown>) {
  const next = { ...props }
  delete next.dataPretextAlertKind
  delete next.dataPretextAlertTitle
  delete next["data-pretext-alert-kind"]
  delete next["data-pretext-alert-title"]
  return next
}

function withoutInternalPretextMetadata(props: Record<string, unknown>) {
  const next = { ...props }
  for (const key of Object.keys(next)) {
    if (/^dataPretext(?:Component|Callout|Heading)/.test(key)) {
      delete next[key]
    }
    if (/^data-pretext-(?:component|callout|heading)/.test(key)) {
      delete next[key]
    }
    if (key === "pretextComponentTrusted") {
      delete next[key]
    }
  }
  return next
}

function readHastElement(node: unknown): PretextMarkdownHastElement | null {
  return node &&
    typeof node === "object" &&
    (node as PretextMarkdownHastElement).type === "element"
    ? (node as PretextMarkdownHastElement)
    : null
}

function readPreCodeElement(node: unknown): PretextMarkdownHastElement | null {
  const pre = readHastElement(node)
  if (pre?.tagName !== "pre") return null
  const code =
    pre.children
      .map(readHastElement)
      .find((child): child is PretextMarkdownHastElement =>
        Boolean(child && child.tagName === "code")
      ) ?? null
  return code
}

function readCodeLanguage(code: PretextMarkdownHastElement | null) {
  const className = code?.properties?.className
  const classes = Array.isArray(className) ? className : [className]
  const languageClass = classes.find(
    (value): value is string =>
      typeof value === "string" && value.startsWith("language-")
  )
  const language = languageClass?.slice("language-".length).toLowerCase()
  if (language === "mmd" || language === "mermaid-js") return "mermaid"
  return language ?? null
}

function readCodeMetadata(code: PretextMarkdownHastElement | null) {
  return parseCodeMetadata(readDataProperty(code, "dataPretextCodeMeta"))
}

function parseCodeMetadata(meta: string) {
  const result: {
    caption?: string
    highlightedLines: Set<number>
    highlightPattern: string
    lineNumberStart?: number
    showLineNumbers: boolean
    title?: string
  } = {
    highlightedLines: new Set<number>(),
    highlightPattern: "",
    showLineNumbers: false,
  }
  for (const match of meta.matchAll(
    /(?:^|\s)(title|caption)=(?:"([^"]*)"|'([^']*)'|([^\s]+))/g
  )) {
    const key = match[1] as "caption" | "title"
    result[key] = match[2] ?? match[3] ?? match[4] ?? ""
  }
  const lineNumbers = /(?:^|\s)showLineNumbers(?:\{(\d+)\})?(?=\s|$)/i.exec(
    meta
  )
  if (lineNumbers) {
    result.showLineNumbers = true
    result.lineNumberStart = lineNumbers[1] ? Number(lineNumbers[1]) : 1
  }
  for (const match of meta.matchAll(/\{(\d+(?:-\d+)?(?:,\d+(?:-\d+)?)*)\}/g)) {
    for (const value of match[1]!.split(",")) {
      addHighlightedCodeLineSpec(result.highlightedLines, value)
    }
  }
  const highlightPattern = /\/([^/\n]+)\//.exec(meta)
  result.highlightPattern = highlightPattern?.[1] ?? ""
  return result
}

function addHighlightedCodeLineSpec(lines: Set<number>, spec: string) {
  const range = /^(\d+)-(\d+)$/.exec(spec)
  if (range) {
    const start = Number(range[1])
    const end = Number(range[2])
    if (!isSafeHighlightedCodeLine(start) || !isSafeHighlightedCodeLine(end)) {
      return
    }
    if (end < start || end - start > 500) return
    for (let line = start; line <= end; line += 1) lines.add(line)
    return
  }

  const line = Number(spec)
  if (isSafeHighlightedCodeLine(line)) lines.add(line)
}

function toKebab(value: string) {
  return value.replace(/[A-Z]/g, (letter) => `-${letter.toLowerCase()}`)
}

function alertIconForKind(kind: string) {
  switch (kind) {
    case "note":
      return Info
    case "tip":
      return Lightbulb
    case "warning":
      return TriangleAlert
    case "caution":
      return CircleAlert
    default:
      return BadgeAlert
  }
}

function calloutTitle(kind: string) {
  const titles: Record<string, string> = {
    caution: "Caution",
    important: "Important",
    note: "Note",
    tip: "Tip",
    warning: "Warning",
  }
  return titles[kind] ?? "Note"
}

function linkKindForHref(href: string) {
  if (href.startsWith("#")) return "fragment"
  if (href.startsWith("/")) return "root"
  if (/^mailto:/i.test(href)) return "email"
  if (/^(?:https?:)?\/\//i.test(href)) return "external"
  return "relative"
}

function linkFormForHref({ href, text }: { href: string; text: string }) {
  if (/^mailto:/i.test(href) && href.slice("mailto:".length) === text) {
    return "email-autolink"
  }
  if (
    /^https?:\/\/www\./i.test(href) &&
    href.replace(/^https?:\/\//i, "") === text
  ) {
    return "autolink"
  }
  if (href === text && /^(?:https?:)?\/\//i.test(href)) return "autolink"
  return "inline"
}

function footnoteLabelForLink({
  href,
  label,
  text,
}: {
  href: string
  label: unknown
  text: string
}) {
  const display = footnoteDisplayForHref(href, text)
  if (/^#(?:user-content-)?fnref-/i.test(href)) {
    return "Back to footnote reference ↩"
  }
  if (/^#(?:user-content-)?fn-/i.test(href)) {
    return `Footnote${display ? ` ${display}` : ""}`
  }
  if (typeof label === "string" && label) return label
  return undefined
}

function footnoteDisplayForHref(href: string, text: string) {
  const visibleText = text.trim().replace(/^\[|\]$/g, "")
  if (/^\d+[a-z]?$/i.test(visibleText)) return visibleText

  const match = /^#(?:user-content-)?fn(?:ref)?-([A-Za-z0-9_-]+)/i.exec(href)
  if (!match) return ""
  return match[1]!.replace(/-/g, " ")
}

function reactNodeText(node: React.ReactNode): string {
  if (typeof node === "string" || typeof node === "number") return String(node)
  if (Array.isArray(node)) return node.map(reactNodeText).join("")
  return ""
}

function hasDescendantElement(
  element: PretextMarkdownHastElement | null,
  tagName: string
): boolean {
  if (!element) return false
  return element.children.some((child) => {
    const childElement = readHastElement(child)
    return (
      childElement?.tagName === tagName ||
      hasDescendantElement(childElement, tagName)
    )
  })
}

function isWhitespaceText(node: PretextMarkdownHastNode) {
  return (
    node.type === "text" &&
    typeof node.value === "string" &&
    node.value.trim() === ""
  )
}

function extractHastText(element: PretextMarkdownHastElement | null): string {
  return extractHastNodeText(element)
}

function extractHastNodeText(
  node: PretextMarkdownHastNode | null | undefined
): string {
  if (!node) return ""
  if (node.type === "text" && typeof node.value === "string") return node.value
  const element = readHastElement(node)
  if (!element) return ""
  return element.children.map(extractHastNodeText).join("")
}

function handleHorizontalScrollKeyDown(
  event: React.KeyboardEvent<HTMLElement>
) {
  const element =
    event.currentTarget.querySelector<HTMLElement>(
      "[data-pretext-markdown-table-scroll]"
    ) ?? event.currentTarget
  if (event.key === "ArrowRight") {
    element.scrollLeft += 50
    event.preventDefault()
  } else if (event.key === "ArrowLeft") {
    element.scrollLeft -= 50
    event.preventDefault()
  } else if (event.key === "End") {
    element.scrollLeft = Math.max(0, element.scrollWidth - element.clientWidth)
    event.preventDefault()
  } else if (event.key === "Home") {
    element.scrollLeft = 0
    event.preventDefault()
  }
}

function tableRowCount(table: PretextMarkdownHastElement | null) {
  if (!table) return undefined
  return countDescendantElements(table, "tr")
}

function tableColumnCount(table: PretextMarkdownHastElement | null) {
  const firstRow = findDescendantElement(table, "tr")
  if (!firstRow) return undefined
  return firstRow.children.filter((child) => {
    const element = readHastElement(child)
    return element?.tagName === "td" || element?.tagName === "th"
  }).length
}

function countDescendantElements(
  element: PretextMarkdownHastElement,
  tagName: string
): number {
  return element.children.reduce((sum, child) => {
    const childElement = readHastElement(child)
    if (!childElement) return sum
    return (
      sum +
      (childElement.tagName === tagName ? 1 : 0) +
      countDescendantElements(childElement, tagName)
    )
  }, 0)
}

function findDescendantElement(
  element: PretextMarkdownHastElement | null,
  tagName: string
): PretextMarkdownHastElement | null {
  if (!element) return null
  for (const child of element.children) {
    const childElement = readHastElement(child)
    if (!childElement) continue
    if (childElement.tagName === tagName) return childElement
    const found = findDescendantElement(childElement, tagName)
    if (found) return found
  }
  return null
}

// A subtle hover copy affordance in the table's top-right corner, replacing the
// persistent chrome bar so the table reads as a clean document table.
function TableCopyButton() {
  const [copied, setCopied] = React.useState(false)
  return (
    <button
      aria-label="Copy table as TSV"
      className="absolute top-2 right-2 z-10 inline-flex items-center gap-1 rounded-md border bg-background/90 px-2 py-1 text-xs font-medium text-muted-foreground opacity-0 shadow-sm backdrop-blur-sm transition-opacity group-hover:opacity-100 hover:text-foreground focus-visible:opacity-100"
      type="button"
      onClick={(event) => {
        copyTable(event.currentTarget)
        setCopied(true)
        window.setTimeout(() => setCopied(false), 1200)
      }}
    >
      {copied ? (
        <Check className="size-3.5" aria-hidden="true" />
      ) : (
        <Copy className="size-3.5" aria-hidden="true" />
      )}
      {copied ? "Copied" : "Copy"}
    </button>
  )
}

function copyTable(button: HTMLButtonElement) {
  const region = button.closest('[role="region"]')
  const table = region?.querySelector("table")
  if (!table) return

  const selection = window.getSelection()
  const selectedText =
    selection &&
    selection.rangeCount > 0 &&
    table.contains(selection.anchorNode)
      ? selection.toString()
      : ""
  if (selectedText.trim()) {
    void navigator.clipboard?.writeText(selectedText.trim())
    return
  }

  void navigator.clipboard?.writeText(serializeTableAsTsv(table))
}

function serializeTableAsTsv(table: HTMLTableElement) {
  return Array.from(table.querySelectorAll("tr"))
    .map((row) =>
      Array.from(row.querySelectorAll("th,td"))
        .map((cell) => normalizeTableCellText(cell.textContent ?? ""))
        .join("\t")
    )
    .join("\n")
}

function normalizeTableCellText(value: string) {
  return value.trim().replace(/[\t\r\n ]+/g, " ")
}

function copyHeadingLink(id: string) {
  const base = `${window.location.origin}${window.location.pathname}${window.location.search}`
  void navigator.clipboard?.writeText(`${base}#${id}`)
}

function readComponentProps(value: string): Record<string, unknown> {
  try {
    const parsed = JSON.parse(value)
    return parsed && typeof parsed === "object"
      ? (parsed as Record<string, unknown>)
      : {}
  } catch {
    return {}
  }
}

function readOptionalString(value: unknown) {
  return typeof value === "string" && value ? value : undefined
}

function readOptionalNumber(value: unknown) {
  const parsed =
    typeof value === "number"
      ? value
      : typeof value === "string"
        ? Number(value)
        : NaN
  return Number.isFinite(parsed) && parsed > 0 ? parsed : undefined
}

function readOptionalBoolean(value: unknown) {
  if (typeof value === "boolean") return value
  if (typeof value !== "string") return undefined
  if (value === "true") return true
  if (value === "false") return false
  return undefined
}

"use client"

import type { PretextMarkdownGreenfieldChunk } from "./pretext-markdown-greenfield-document"
import type { PretextMarkdownGreenfieldChunkFrame } from "./pretext-markdown-greenfield-layout"

export type PretextMarkdownGreenfieldScrollAnchor = {
  chunkId: string
  offsetWithinChunkPx: number
  chunkHeightPx: number
}

export function getPretextMarkdownGreenfieldVisibleFrames({
  frames,
  overscanPx,
  scrollTop,
  viewportHeight,
}: {
  frames: readonly PretextMarkdownGreenfieldChunkFrame[]
  overscanPx: number
  scrollTop: number
  viewportHeight: number
}) {
  if (!frames.length) return []
  const start = firstFrameWithBottomAfter(
    frames,
    Math.max(0, scrollTop - overscanPx)
  )
  const end = firstFrameWithTopAtOrAfter(
    frames,
    scrollTop + viewportHeight + overscanPx
  )
  return frames.slice(start, Math.max(start + 1, end))
}

export function getPretextMarkdownGreenfieldScrollAnchor({
  frames,
  scrollTop,
}: {
  frames: readonly PretextMarkdownGreenfieldChunkFrame[]
  scrollTop: number
}): PretextMarkdownGreenfieldScrollAnchor | null {
  if (!frames.length) return null
  const frame =
    frames[
      Math.min(firstFrameWithBottomAfter(frames, scrollTop), frames.length - 1)
    ]
  if (!frame) return null

  return {
    chunkId: frame.id,
    chunkHeightPx: frame.height,
    offsetWithinChunkPx: Math.max(0, scrollTop - frame.top),
  }
}

export function resolvePretextMarkdownGreenfieldScrollAnchor({
  anchor,
  frames,
}: {
  anchor: PretextMarkdownGreenfieldScrollAnchor
  frames: readonly PretextMarkdownGreenfieldChunkFrame[]
}) {
  const frame = frames.find((item) => item.id === anchor.chunkId)
  if (!frame) return null
  // Preserve the position *within* the anchored chunk proportionally. When the
  // chunk keeps its height this reduces to the original pixel offset; when an
  // over-estimated chunk shrinks after measurement, the viewport stays at the
  // same relative content instead of snapping toward the chunk's top (which is
  // what `min(offset, height - 1)` did, yanking the reader upward).
  const fraction =
    anchor.chunkHeightPx > 0
      ? Math.min(
          1,
          Math.max(0, anchor.offsetWithinChunkPx / anchor.chunkHeightPx)
        )
      : 0
  return frame.top + fraction * frame.height
}

export function getPretextMarkdownGreenfieldScrollTopForLineRange({
  chunks,
  frames,
  preferredChunkId,
  range,
  viewportHeight,
}: {
  chunks: readonly Pick<
    PretextMarkdownGreenfieldChunk,
    "id" | "index" | "sourceEndLine" | "sourceStartLine"
  >[]
  frames: readonly PretextMarkdownGreenfieldChunkFrame[]
  preferredChunkId?: string | null
  range: { end: number; start: number } | null
  viewportHeight: number
}) {
  if (!range) return null
  const preferredChunk =
    preferredChunkId == null
      ? null
      : chunks.find((item) => item.id === preferredChunkId)
  const chunk =
    preferredChunk ??
    chunks.find(
      (item) =>
        item.sourceStartLine <= range.start && item.sourceEndLine >= range.start
    ) ??
    chunks[0]
  const frame = chunk
    ? frames.find((candidate) => candidate.index === chunk.index)
    : null
  if (!frame) return null

  const lineCount = Math.max(1, frame.sourceEndLine - frame.sourceStartLine + 1)
  const lineOffset =
    (Math.max(0, range.start - frame.sourceStartLine) / lineCount) *
      frame.height || 0
  return Math.max(0, frame.top + lineOffset - viewportHeight * 0.25)
}

export function getPretextMarkdownGreenfieldSourceLineForScrollTop({
  chunks,
  frames,
  scrollTop,
}: {
  chunks: readonly Pick<
    PretextMarkdownGreenfieldChunk,
    "index" | "sourceEndLine" | "sourceStartLine"
  >[]
  frames: readonly PretextMarkdownGreenfieldChunkFrame[]
  scrollTop: number
}) {
  if (!frames.length) return 1
  const frame =
    frames[
      Math.min(firstFrameWithBottomAfter(frames, scrollTop), frames.length - 1)
    ]
  if (!frame) return 1
  const chunk = chunks.find((item) => item.index === frame.index)
  if (!chunk) return frame.sourceStartLine
  const lineCount = Math.max(1, chunk.sourceEndLine - chunk.sourceStartLine + 1)
  const ratio = Math.max(0, Math.min(1, (scrollTop - frame.top) / frame.height))
  return (
    chunk.sourceStartLine +
    Math.min(lineCount - 1, Math.floor(ratio * lineCount))
  )
}

function firstFrameWithBottomAfter(
  frames: readonly PretextMarkdownGreenfieldChunkFrame[],
  y: number
) {
  let low = 0
  let high = frames.length
  while (low < high) {
    const mid = Math.floor((low + high) / 2)
    if (frames[mid]!.bottom > y) high = mid
    else low = mid + 1
  }
  return low
}

function firstFrameWithTopAtOrAfter(
  frames: readonly PretextMarkdownGreenfieldChunkFrame[],
  y: number
) {
  let low = 0
  let high = frames.length
  while (low < high) {
    const mid = Math.floor((low + high) / 2)
    if (frames[mid]!.top >= y) high = mid
    else low = mid + 1
  }
  return low
}

"use client"

export type PretextMarkdownPoint = {
  column?: number
  line?: number
  offset?: number
}

export type PretextMarkdownPosition = {
  end?: PretextMarkdownPoint
  start?: PretextMarkdownPoint
}

export type PretextMarkdownHastText = {
  position?: PretextMarkdownPosition
  type: "text"
  value: string
}

export type PretextMarkdownHastElement = {
  children: PretextMarkdownHastNode[]
  position?: PretextMarkdownPosition
  properties?: Record<string, unknown>
  tagName: string
  type: "element"
}

export type PretextMarkdownHastRoot = {
  children: PretextMarkdownHastNode[]
  type: "root"
}

export type PretextMarkdownHastNode =
  | PretextMarkdownHastElement
  | PretextMarkdownHastText
  | {
      children?: PretextMarkdownHastNode[]
      position?: PretextMarkdownPosition
      type: string
      value?: unknown
    }

"use client"

import type { PretextMarkdownPosition } from "./pretext-markdown-hast-types"

export interface PretextMarkdownSourceRange {
  endLine: number
  endOffset: number
  startLine: number
  startOffset: number
}

export interface PretextMarkdownSourceMap {
  lineCount: number
  lineStarts: readonly number[]
  text: string
}

export function createPretextMarkdownSourceMap(
  text: string
): PretextMarkdownSourceMap {
  const lineStarts = [0]
  for (const match of text.matchAll(/\r\n|[\n\r\u2028\u2029]/g)) {
    lineStarts.push(match.index + match[0].length)
  }

  return {
    lineCount: Math.max(1, lineStarts.length),
    lineStarts,
    text,
  }
}

export function pretextMarkdownSourceRangeFromPosition({
  position,
  sourceMap,
}: {
  position: PretextMarkdownPosition | null | undefined
  sourceMap: PretextMarkdownSourceMap
}): PretextMarkdownSourceRange | null {
  if (!position?.start || !position.end) return null

  const startLine = clampLine(position.start.line, sourceMap)
  const endLine = clampLine(position.end.line, sourceMap)
  const startOffset =
    typeof position.start.offset === "number"
      ? clampOffset(position.start.offset, sourceMap.text.length)
      : offsetFromLineColumn({
          column: position.start.column,
          line: startLine,
          sourceMap,
        })
  const endOffset =
    typeof position.end.offset === "number"
      ? clampOffset(position.end.offset, sourceMap.text.length)
      : offsetFromLineColumn({
          column: position.end.column,
          line: endLine,
          sourceMap,
        })

  return {
    endLine: Math.max(startLine, endLine),
    endOffset: Math.max(startOffset, endOffset),
    startLine,
    startOffset,
  }
}

export function pretextMarkdownSourceTextForRange({
  range,
  sourceMap,
}: {
  range: PretextMarkdownSourceRange | null
  sourceMap: PretextMarkdownSourceMap
}) {
  if (!range) return ""
  return sourceMap.text.slice(range.startOffset, range.endOffset)
}

export function pretextMarkdownRangesIntersect({
  a,
  b,
}: {
  a: PretextMarkdownSourceRange | null
  b: PretextMarkdownSourceRange | null
}) {
  if (!a || !b) return false
  return a.startOffset < b.endOffset && a.endOffset > b.startOffset
}

export function pretextMarkdownLineRangeIntersects({
  endLine,
  range,
  startLine,
}: {
  endLine: number
  range: { end: number; start: number } | null
  startLine: number
}) {
  if (!range) return false
  return startLine <= range.end && endLine >= range.start
}

function offsetFromLineColumn({
  column,
  line,
  sourceMap,
}: {
  column: number | undefined
  line: number
  sourceMap: PretextMarkdownSourceMap
}) {
  const lineStart = sourceMap.lineStarts[line - 1] ?? 0
  return clampOffset(
    lineStart + Math.max(0, (column ?? 1) - 1),
    sourceMap.text.length
  )
}

function clampLine(
  line: number | undefined,
  sourceMap: PretextMarkdownSourceMap
) {
  if (!Number.isFinite(line)) return 1
  return Math.max(1, Math.min(sourceMap.lineCount, Math.trunc(line ?? 1)))
}

function clampOffset(offset: number, textLength: number) {
  return Math.max(0, Math.min(textLength, offset))
}

"use client"

import rehypeKatex from "rehype-katex"
import rehypeRaw from "rehype-raw"
import rehypeSanitize, { defaultSchema } from "rehype-sanitize"
import rehypeSlug from "rehype-slug"
import remarkBreaks from "remark-breaks"
import remarkDirective from "remark-directive"
import remarkGemoji from "remark-gemoji"
import remarkGfm from "remark-gfm"
import remarkMath from "remark-math"
import remarkParse from "remark-parse"
import remarkRehype from "remark-rehype"
import remarkSmartypants from "remark-smartypants"
import { unified } from "unified"
import { VFile } from "vfile"

import type {
  PretextMarkdownHastElement,
  PretextMarkdownHastRoot,
} from "./pretext-markdown-hast-types"
import { createPretextMarkdownSourceMap } from "./pretext-markdown-source-map"

export type PretextMarkdownUnifiedDocument = {
  hast: PretextMarkdownHastRoot
  mdast: PretextMarkdownMdastRoot
  messages: PretextMarkdownUnifiedMessage[]
  sourceMap: ReturnType<typeof createPretextMarkdownSourceMap>
}

export type PretextMarkdownUnifiedMessage = {
  column?: number
  fatal?: boolean | null
  line?: number
  reason: string
  ruleId?: string | null
  source?: string | null
}

export type PretextMarkdownUnifiedOptions = {
  gfm?: PretextMarkdownGfmOptions
}

export const PRETEXT_MARKDOWN_REMARK_PLUGINS = [
  "remark-parse",
  "remark-directive",
  "remark-gfm",
  "remark-breaks",
  "remark-math",
  "remark-gemoji",
  "remark-pretext-markdown-prose-transforms",
  "remark-smartypants",
  "remark-pretext-markdown-github-alerts",
  "remark-pretext-markdown-definition-lists",
  "remark-pretext-markdown-components",
  "remark-pretext-markdown-code-metadata",
] as const

export const PRETEXT_MARKDOWN_REHYPE_PLUGINS = [
  "remark-rehype",
  "rehype-raw",
  "rehype-slug",
  "rehype-sanitize",
  "rehype-pretext-markdown-trusted-metadata",
  "rehype-pretext-markdown-safe-inputs",
  "rehype-katex",
] as const

type PretextMarkdownGfmOptions = {
  singleTilde?: boolean
  stringLength?: (value: string) => number
  tableCellPadding?: boolean
  tablePipeAlign?: boolean
}

type PretextMarkdownMdastNode = {
  children?: PretextMarkdownMdastNode[]
  data?: {
    hProperties?: Record<string, unknown>
    [key: string]: unknown
  }
  lang?: string
  meta?: string
  position?: {
    end?: {
      column?: number
      line?: number
      offset?: number
    }
    start?: {
      column?: number
      line?: number
      offset?: number
    }
  }
  type: string
  value?: string
}

type PretextMarkdownMdastRoot = PretextMarkdownMdastNode & {
  children: PretextMarkdownMdastNode[]
  type: "root"
}

type PretextMarkdownMdastParagraph = PretextMarkdownMdastNode & {
  children: PretextMarkdownMdastNode[]
  type: "paragraph"
}

type PretextMarkdownComponent = {
  children?: PretextMarkdownMdastNode[]
  name: string
  props: Record<string, string>
}

const GITHUB_ALERT_LABELS = {
  caution: "Caution",
  important: "Important",
  note: "Note",
  tip: "Tip",
  warning: "Warning",
} as const

export function createPretextMarkdownUnifiedDocument(
  markdown: string,
  options: PretextMarkdownUnifiedOptions = {}
): PretextMarkdownUnifiedDocument {
  const file = new VFile({ value: markdown })
  const mdastProcessor = unified()
    .use(remarkParse)
    .use(remarkDirective)
    .use(remarkGfm, options.gfm)
    .use(remarkBreaks)
    .use(remarkMath)
    .use(remarkGemoji)
    .use(remarkPretextMarkdownProseTransforms)
    .use(remarkSmartypants)
    .use(remarkPretextMarkdownGithubAlerts)
    .use(remarkPretextMarkdownDefinitionLists)
    .use(remarkPretextMarkdownComponents)
    .use(remarkPretextMarkdownCodeMetadata)
  const mdast = mdastProcessor.runSync(
    mdastProcessor.parse(file),
    file
  ) as PretextMarkdownMdastRoot
  const hast = unified()
    .use(remarkRehype, { allowDangerousHtml: true })
    .use(rehypeRaw)
    .use(rehypeSlug)
    .use(rehypeSanitize, createPretextMarkdownUnifiedSanitizeSchema())
    .use(rehypePretextMarkdownTrustedMetadata)
    .use(rehypePretextMarkdownSafeInputs)
    .use(rehypeKatex, {
      maxExpand: 1000,
      maxSize: 10,
      strict: "ignore",
      trust: false,
    })
    .runSync(mdast as never, file) as PretextMarkdownHastRoot
  const sourceMap = createPretextMarkdownSourceMap(markdown)
  injectPretextMarkdownFrontmatter(hast, sourceMap.text)

  return {
    hast,
    mdast,
    messages: file.messages.map(pretextMarkdownUnifiedMessageFromVFileMessage),
    sourceMap,
  }
}

function pretextMarkdownUnifiedMessageFromVFileMessage(message: {
  column?: number
  fatal?: boolean | null
  line?: number
  reason: string
  ruleId?: string | null
  source?: string | null
}): PretextMarkdownUnifiedMessage {
  return {
    column: message.column,
    fatal: message.fatal,
    line: message.line,
    reason: message.reason,
    ruleId: message.ruleId,
    source: message.source,
  }
}

function injectPretextMarkdownFrontmatter(
  hast: PretextMarkdownHastRoot,
  markdown: string
) {
  const frontmatter = readPretextMarkdownFrontmatter(markdown)
  if (!frontmatter) return
  hast.children = [
    createFrontmatterElement(frontmatter),
    ...hast.children.filter((child) => {
      const line = child.position?.start?.line ?? Number.POSITIVE_INFINITY
      return line > frontmatter.endLine
    }),
  ]
}

function readPretextMarkdownFrontmatter(markdown: string) {
  const lines = markdown.split(/\r\n|[\n\r\u2028\u2029]/)
  const first = lines[0]?.trim()
  const kind = first === "---" ? "yaml" : first === "+++" ? "toml" : ""
  if (!kind) return null
  const closeIndex = lines.findIndex(
    (line, index) => index > 0 && line.trim() === first
  )
  if (closeIndex <= 0) return null
  const body = lines.slice(1, closeIndex)
  if (!body.some((line) => line.trim())) return null
  return {
    body,
    endLine: closeIndex + 1,
    kind,
    raw: lines.slice(0, closeIndex + 1).join("\n"),
  }
}

function createFrontmatterElement(frontmatter: {
  body: string[]
  endLine: number
  kind: string
  raw: string
}): PretextMarkdownHastElement {
  const lastLine = frontmatter.raw.split(/\r\n|[\n\r\u2028\u2029]/).at(-1) ?? ""
  return {
    type: "element",
    tagName: "div",
    position: {
      start: { line: 1, column: 1, offset: 0 },
      end: {
        line: frontmatter.endLine,
        column: lastLine.length + 1,
        offset: frontmatter.raw.length,
      },
    },
    properties: {
      dataPretextMarkdownFrontmatter: frontmatter.kind,
    },
    children: [
      {
        type: "element",
        tagName: "pre",
        properties: { dataPretextMarkdownFrontmatterSource: "" },
        children: [
          {
            type: "element",
            tagName: "code",
            properties: { dataPretextMarkdownFrontmatterSource: "" },
            children: [{ type: "text", value: frontmatter.raw }],
          },
        ],
      },
      {
        type: "element",
        tagName: "dl",
        properties: { dataPretextMarkdownFrontmatterMetadata: "" },
        children: frontmatterEntries(frontmatter).flatMap(
          ([key, value, kind]) => [
            {
              type: "element" as const,
              tagName: "dt",
              properties: {},
              children: [{ type: "text" as const, value: key }],
            },
            {
              type: "element" as const,
              tagName: "dd",
              properties: { dataFrontmatterValueKind: kind },
              children: [{ type: "text" as const, value }],
            },
          ]
        ),
      },
    ],
  }
}

function frontmatterEntries(frontmatter: { body: string[]; kind: string }) {
  return frontmatter.kind === "toml"
    ? tomlFrontmatterEntries(frontmatter.body)
    : yamlFrontmatterEntries(frontmatter.body)
}

function yamlFrontmatterEntries(
  lines: string[]
): Array<[string, string, string]> {
  const entries: Array<[string, string, string]> = []
  for (let index = 0; index < lines.length; index += 1) {
    const line = lines[index]!
    const match = /^([A-Za-z0-9_.-]+):\s*(.*)$/.exec(line)
    if (!match) continue
    const key = match[1]!
    const value = match[2]!.trim()
    if (value.startsWith("{") || value.startsWith("[{")) continue
    if (/^\[.*\]$/.test(value)) {
      entries.push([
        key,
        value
          .slice(1, -1)
          .split(",")
          .map((item) => item.trim())
          .join(", "),
        "list",
      ])
    } else if (value) {
      entries.push([key, value.replace(/^["']|["']$/g, ""), "scalar"])
    } else {
      const items: string[] = []
      while (/^\s+-\s+/.test(lines[index + 1] ?? "")) {
        index += 1
        items.push((lines[index] ?? "").replace(/^\s+-\s+/, "").trim())
      }
      if (items.length) entries.push([key, items.join(", "), "list"])
    }
  }
  return entries
}

function tomlFrontmatterEntries(
  lines: string[]
): Array<[string, string, string]> {
  const entries: Array<[string, string, string]> = []
  let section = ""
  for (const line of lines) {
    const sectionMatch = /^\[([^\]]+)\]$/.exec(line.trim())
    if (sectionMatch) {
      section = `${sectionMatch[1]}.`
      continue
    }
    const match = /^([A-Za-z0-9_.-]+)\s*=\s*(.*)$/.exec(line.trim())
    if (!match) continue
    const key = `${section}${match[1]}`
    const value = match[2]!.trim()
    if (/^\[.*\]$/.test(value)) {
      entries.push([
        key,
        value
          .slice(1, -1)
          .split(",")
          .map((item) => item.trim().replace(/^["']|["']$/g, ""))
          .join(", "),
        "list",
      ])
    } else {
      entries.push([key, value.replace(/^["']|["']$/g, ""), "scalar"])
    }
  }
  return entries
}

function createPretextMarkdownUnifiedSanitizeSchema() {
  return {
    ...defaultSchema,
    clobberPrefix: "user-content-",
    attributes: {
      ...defaultSchema.attributes,
      "*": [
        ...(defaultSchema.attributes?.["*"] ?? []),
        "ariaDescribedBy",
        "ariaHidden",
        "ariaLabel",
        "ariaLabelledBy",
        "className",
        "dataFootnoteBackref",
        "dataFootnoteRef",
        "dataFootnotes",
        "dataPretextComponentFallback",
        "dataPretextComponentFallbackName",
        "dataPretextComponentFallbackReason",
        "dataPretextComponentFallbackSource",
        "dataPretextComponentName",
        "dataPretextComponentProps",
        "dataPretextAlertKind",
        "dataPretextAlertTitle",
        "dataPretextCalloutKind",
        "dataPretextCalloutTitle",
        "id",
      ],
      a: [
        ...(defaultSchema.attributes?.a ?? []),
        "ariaDescribedBy",
        "dataFootnoteBackref",
        "dataFootnoteRef",
        "href",
        "id",
        "title",
      ],
      code: [
        ...(defaultSchema.attributes?.code ?? []),
        "className",
        "dataPretextCodeMeta",
      ],
      ins: [...(defaultSchema.attributes?.ins ?? []), "cite"],
      input: ["checked", "disabled", "type"],
      li: [...(defaultSchema.attributes?.li ?? []), "className"],
      ol: [...(defaultSchema.attributes?.ol ?? []), "start"],
      section: [
        ...(defaultSchema.attributes?.section ?? []),
        "className",
        "dataFootnotes",
      ],
      time: [...(defaultSchema.attributes?.time ?? []), "dateTime"],
      sup: [...(defaultSchema.attributes?.sup ?? []), "id"],
      td: [...(defaultSchema.attributes?.td ?? []), "align"],
      th: [...(defaultSchema.attributes?.th ?? []), "align"],
      q: [...(defaultSchema.attributes?.q ?? []), "cite"],
    },
    tagNames: [
      ...(defaultSchema.tagNames ?? []),
      "abbr",
      "caption",
      "cite",
      "dd",
      "details",
      "dfn",
      "dl",
      "dt",
      "figcaption",
      "figure",
      "input",
      "ins",
      "kbd",
      "mark",
      "q",
      "samp",
      "section",
      "small",
      "summary",
      "time",
      "var",
    ],
  }
}

function remarkPretextMarkdownGithubAlerts() {
  return function transform(tree: unknown) {
    for (const node of (tree as PretextMarkdownMdastRoot).children) {
      transformGithubAlertBlockquote(node)
    }
  }
}

function remarkPretextMarkdownProseTransforms() {
  return function transform(tree: unknown) {
    visitPretextMarkdownMdastNodes(tree as PretextMarkdownMdastRoot, (node) => {
      if (node.type !== "text" || typeof node.value !== "string") return
      node.value = node.value
        .replace(/--/g, "—")
        .replace(/\.\.\./g, "…")
        .replace(/->/g, "→")
        .replace(/\b1\/2\b/g, "½")
    })
  }
}

function transformGithubAlertBlockquote(node: PretextMarkdownMdastNode) {
  if (node.type !== "blockquote") return

  const blockquote = node
  const first = blockquote.children?.[0]
  if (!first || first.type !== "paragraph") return

  const alert = readGithubAlertMarker(first as PretextMarkdownMdastParagraph)
  if (!alert) return

  blockquote.data = {
    ...blockquote.data,
    hProperties: {
      ...(blockquote.data?.hProperties as Record<string, unknown> | undefined),
      dataPretextAlertKind: alert.kind,
      dataPretextAlertTitle: alert.title,
    },
  }
}

function remarkPretextMarkdownCodeMetadata() {
  return function transform(tree: unknown) {
    visitPretextMarkdownMdastNodes(tree as PretextMarkdownMdastRoot, (node) => {
      if (node.type !== "code" || !node.meta) return
      node.data = {
        ...node.data,
        hProperties: {
          ...(node.data?.hProperties as Record<string, unknown> | undefined),
          dataPretextCodeMeta: node.meta,
        },
      }
    })
  }
}

function visitPretextMarkdownMdastNodes(
  node: PretextMarkdownMdastNode,
  visitor: (node: PretextMarkdownMdastNode) => void
) {
  visitor(node)
  for (const child of node.children ?? []) {
    visitPretextMarkdownMdastNodes(child, visitor)
  }
}

function readGithubAlertMarker(paragraph: PretextMarkdownMdastParagraph) {
  const first = paragraph.children[0]
  if (!first || first.type !== "text") return null

  const match =
    /^\[!(NOTE|TIP|IMPORTANT|WARNING|CAUTION)\][\t ]*(?:\r?\n)?/i.exec(
      first.value ?? ""
    )
  if (!match) return null

  const kind = match[1]!.toLowerCase() as keyof typeof GITHUB_ALERT_LABELS
  first.value = (first.value ?? "").slice(match[0].length)
  if (!first.value) {
    paragraph.children.shift()
  }

  return {
    kind,
    title: GITHUB_ALERT_LABELS[kind],
  }
}

function remarkPretextMarkdownComponents() {
  return function transform(tree: unknown, file: VFile) {
    transformPretextMarkdownComponentChildren(
      tree as PretextMarkdownMdastRoot,
      file
    )
  }
}

function remarkPretextMarkdownDefinitionLists() {
  return function transform(tree: unknown) {
    const root = tree as PretextMarkdownMdastRoot
    const nextChildren: PretextMarkdownMdastNode[] = []
    for (const child of root.children) {
      const definitionList = pretextMarkdownDefinitionListFromParagraph(child)
      nextChildren.push(definitionList ?? child)
    }
    root.children = nextChildren
  }
}

function pretextMarkdownDefinitionListFromParagraph(
  node: PretextMarkdownMdastNode
): PretextMarkdownMdastNode | null {
  if (node.type !== "paragraph" || !node.children?.length) return null

  const lines = splitMdastParagraphLines(node.children)
  if (lines.length < 2) return null
  const term = trimMdastLine(lines[0] ?? [])
  const definitions = lines
    .slice(1)
    .map(trimDefinitionLine)
    .filter(
      (definition): definition is PretextMarkdownMdastNode[] =>
        definition != null
    )
  if (!term.length || !definitions.length) return null

  return {
    type: "list",
    data: {
      hName: "dl",
      hProperties: {
        dataPretextDefinitionList: "",
      },
    },
    children: [
      {
        type: "listItem",
        data: {
          hName: "dt",
          hProperties: {
            dataPretextDefinitionTerm: "",
          },
        },
        children: term,
      },
      ...definitions.map((definition) => ({
        type: "listItem",
        data: {
          hName: "dd",
          hProperties: {
            dataPretextDefinitionDescription: "",
          },
        },
        children: definition,
      })),
    ],
  }
}

function splitMdastParagraphLines(children: PretextMarkdownMdastNode[]) {
  const lines: PretextMarkdownMdastNode[][] = [[]]
  for (const child of children) {
    if (child.type === "break") {
      lines.push([])
      continue
    }
    if (child.type === "text" && typeof child.value === "string") {
      const parts = child.value.split(/\r?\n/)
      parts.forEach((part, index) => {
        if (index > 0) lines.push([])
        if (part) lines[lines.length - 1]!.push({ ...child, value: part })
      })
      continue
    }
    lines[lines.length - 1]!.push(child)
  }
  return lines
}

function trimMdastLine(line: PretextMarkdownMdastNode[]) {
  return trimMdastLineEnd(trimMdastLineStart(line))
}

function trimDefinitionLine(line: PretextMarkdownMdastNode[]) {
  const trimmed = trimMdastLine(line)
  const first = trimmed[0]
  if (
    !first ||
    first.type !== "text" ||
    typeof first.value !== "string" ||
    !first.value.startsWith(":")
  ) {
    return null
  }
  first.value = first.value.replace(/^:\s*/, "")
  return trimMdastLine(trimmed)
}

function trimMdastLineStart(line: PretextMarkdownMdastNode[]) {
  const next = line.map((node) => ({ ...node }))
  while (
    next[0]?.type === "text" &&
    typeof next[0].value === "string" &&
    !next[0].value.trim()
  ) {
    next.shift()
  }
  if (next[0]?.type === "text" && typeof next[0].value === "string") {
    next[0].value = next[0].value.replace(/^\s+/, "")
    if (!next[0].value) next.shift()
  }
  return next
}

function trimMdastLineEnd(line: PretextMarkdownMdastNode[]) {
  const next = line.map((node) => ({ ...node }))
  while (
    next.at(-1)?.type === "text" &&
    typeof next.at(-1)?.value === "string" &&
    !String(next.at(-1)?.value).trim()
  ) {
    next.pop()
  }
  const last = next.at(-1)
  if (last?.type === "text" && typeof last.value === "string") {
    last.value = last.value.replace(/\s+$/, "")
    if (!last.value) next.pop()
  }
  return next
}

function rehypePretextMarkdownSafeInputs() {
  return function transform(tree: PretextMarkdownHastRoot) {
    removeUnsafeInputChildren(tree)
  }
}

function rehypePretextMarkdownTrustedMetadata() {
  return function transform(tree: PretextMarkdownHastRoot) {
    trustGeneratedPretextMarkdownMetadata(tree)
  }
}

function trustGeneratedPretextMarkdownMetadata(
  node: PretextMarkdownHastElement | PretextMarkdownHastRoot
) {
  for (const child of node.children) {
    const element = child as PretextMarkdownHastElement
    if (!element || element.type !== "element") continue

    if (hasPretextMarkdownInternalMetadata(element)) {
      if (element.position) {
        stripPretextMarkdownInternalMetadata(element)
      } else if (hasPretextMarkdownTrustedComponentMetadata(element)) {
        element.properties ??= {}
        element.properties.pretextComponentTrusted = true
      }
    }

    trustGeneratedPretextMarkdownMetadata(element)
  }
}

function hasPretextMarkdownInternalMetadata(
  element: PretextMarkdownHastElement
) {
  return Object.keys(element.properties ?? {}).some((key) =>
    /^(?:dataPretextComponent|dataPretextCallout|dataFootnotes|dataFootnoteBackref|pretextComponentTrusted)/.test(
      key
    )
  )
}

function hasPretextMarkdownTrustedComponentMetadata(
  element: PretextMarkdownHastElement
) {
  return Object.keys(element.properties ?? {}).some((key) =>
    /^(?:dataPretextComponent|dataPretextCallout|pretextComponentTrusted)/.test(
      key
    )
  )
}

function stripPretextMarkdownInternalMetadata(
  element: PretextMarkdownHastElement
) {
  for (const key of Object.keys(element.properties ?? {})) {
    if (
      /^(?:dataPretextComponent|data-pretext-component|dataPretextCallout|data-pretext-callout|dataFootnotes|data-footnotes|dataFootnoteBackref|data-footnote-backref|pretextComponentTrusted)/.test(
        key
      )
    ) {
      delete element.properties?.[key]
    }
  }
}

function removeUnsafeInputChildren(
  parent: PretextMarkdownHastElement | PretextMarkdownHastRoot
) {
  if (!Array.isArray(parent.children)) return
  parent.children = parent.children.filter((child) => {
    const element = child as PretextMarkdownHastElement
    if (!element || element.type !== "element") return true
    if (element.tagName !== "input") return true
    return (
      isHastElement(parent) &&
      parent.tagName === "li" &&
      hasClassName(parent, "task-list-item") &&
      element.properties?.type === "checkbox"
    )
  })
  for (const child of parent.children) {
    const element = child as PretextMarkdownHastElement
    if (element?.type === "element") removeUnsafeInputChildren(element)
  }
}

function isHastElement(
  node: PretextMarkdownHastElement | PretextMarkdownHastRoot
): node is PretextMarkdownHastElement {
  return node.type === "element"
}

function hasClassName(element: PretextMarkdownHastElement, className: string) {
  const value = element.properties?.className
  return Array.isArray(value) && value.includes(className)
}

function transformPretextMarkdownComponentChildren(
  parent: PretextMarkdownMdastNode,
  file: VFile
) {
  const children = parent.children
  if (!children) return
  transformPretextMarkdownHtmlContainers(parent, file)

  for (let index = 0; index < children.length; index += 1) {
    const child = children[index]!

    if (child.type === "html" && typeof child.value === "string") {
      const component = parsePretextMarkdownComponentHtml(child.value)
      if (component) {
        children[index] = createPretextMarkdownComponentNode(component)
        continue
      }
      // CommonMark merges consecutive component tags (no blank line between)
      // into one HTML block; split it so each tag renders as its own component
      // (or its own fallback) instead of the whole run falling through to text.
      const multiple = splitPretextMarkdownComponentHtml(child.value, file)
      if (multiple) {
        children.splice(index, 1, ...multiple)
        index += multiple.length - 1
        continue
      }
      if (isPretextMarkdownComponentHtml(child.value)) {
        const reason = fallbackReasonForHtml(child.value)
        emitPretextMarkdownComponentFallbackMessage({
          file,
          node: child,
          reason,
        })
        children[index] = createPretextMarkdownComponentFallbackNode({
          name: componentNameFromHtml(child.value) ?? "Component",
          reason,
          source: child.value.trim(),
        })
        continue
      }
    }

    const paragraphComponentSource = componentSourceFromParagraph(child, file)
    if (paragraphComponentSource) {
      const reason = fallbackReasonForHtml(paragraphComponentSource)
      emitPretextMarkdownComponentFallbackMessage({
        file,
        node: child,
        reason,
      })
      children[index] = createPretextMarkdownComponentFallbackNode({
        name: componentNameFromHtml(paragraphComponentSource) ?? "Component",
        reason,
        source: paragraphComponentSource,
      })
      continue
    }

    if (
      child.type === "containerDirective" &&
      isPretextMarkdownContainerComponentName(readDirectiveName(child))
    ) {
      transformPretextMarkdownComponentChildren(child, file)
      const component = parsePretextMarkdownDirectiveComponent(child)
      if (component) {
        children[index] = createPretextMarkdownComponentNode(component)
        continue
      }
      if (isPretextMarkdownContainerComponentName(readDirectiveName(child))) {
        const reason = "Unsupported component directive props"
        emitPretextMarkdownComponentFallbackMessage({
          file,
          node: child,
          reason,
        })
        children[index] = createPretextMarkdownComponentFallbackNode({
          name:
            componentNameForDirective(readDirectiveName(child)) ?? "Component",
          reason,
          source: directiveSourceForUnsafeComponent(child),
          children: child.children ?? [],
        })
        continue
      }
    }

    if (
      child.type === "containerDirective" &&
      isCalloutKind(readDirectiveName(child))
    ) {
      children[index] = createPretextMarkdownCalloutNode(child)
      continue
    }

    if (child.type === "leafDirective" || child.type === "textDirective") {
      const component = parsePretextMarkdownDirectiveComponent(child)
      if (component) {
        children[index] = createPretextMarkdownComponentNode(component)
        continue
      }
      if (componentNameForDirective(readDirectiveName(child))) {
        const reason = "Unsupported component directive props"
        emitPretextMarkdownComponentFallbackMessage({
          file,
          node: child,
          reason,
        })
        children[index] = createPretextMarkdownComponentFallbackNode({
          name:
            componentNameForDirective(readDirectiveName(child)) ?? "Component",
          reason,
          source: directiveSourceForUnsafeComponent(child),
          children:
            child.type === "textDirective" ? (child.children ?? []) : [],
        })
        continue
      }
    }

    transformPretextMarkdownComponentChildren(child, file)
  }
}

function componentSourceFromParagraph(
  node: PretextMarkdownMdastNode,
  file: VFile
) {
  if (node.type !== "paragraph") return null
  const nonWhitespaceChildren = (node.children ?? []).filter(
    (child) => !(child.type === "text" && !String(child.value ?? "").trim())
  )
  if (nonWhitespaceChildren.length !== 1) return null
  const onlyChild = nonWhitespaceChildren[0]!
  if (onlyChild.type !== "text" || typeof onlyChild.value !== "string") {
    return null
  }

  const source = sourceTextForMdastNode(node, file).trim() || onlyChild.value
  return isPretextMarkdownComponentHtml(source) ? source : null
}

function transformPretextMarkdownHtmlContainers(
  parent: PretextMarkdownMdastNode,
  file: VFile
) {
  const children = parent.children
  if (!children) return
  for (let index = 0; index < children.length; index += 1) {
    const child = children[index]!
    if (child.type !== "html" || typeof child.value !== "string") continue
    const start = /^<([A-Z][A-Za-z0-9]*)\b([^>]*)>$/.exec(child.value.trim())
    if (!start || !["Accordion", "Callout"].includes(start[1]!)) continue
    const name = start[1]!
    const closeIndex = children.findIndex(
      (candidate, candidateIndex) =>
        candidateIndex > index &&
        candidate.type === "html" &&
        typeof candidate.value === "string" &&
        candidate.value.trim() === `</${name}>`
    )
    if (closeIndex < 0) continue
    const propsText = start[2]!
    const source = child.value.trim()
    const inner = children.slice(index + 1, closeIndex)
    const component = hasEventHandlerAttribute(propsText)
      ? null
      : parsePretextMarkdownComponentProps(
          name,
          parseComponentAttributes(propsText),
          inner
        )
    if (!component) {
      emitPretextMarkdownComponentFallbackMessage({
        file,
        node: child,
        reason: fallbackReasonForHtml(source),
      })
    }
    children.splice(
      index,
      closeIndex - index + 1,
      component
        ? createPretextMarkdownComponentNode(component)
        : createPretextMarkdownComponentFallbackNode({
            name,
            reason: fallbackReasonForHtml(source),
            source,
            children: inner,
          })
    )
  }
}

function emitPretextMarkdownComponentFallbackMessage({
  file,
  node,
  reason,
}: {
  file: VFile
  node: PretextMarkdownMdastNode
  reason: string
}) {
  file.message(
    new Error(reason),
    pretextMarkdownMessagePoint(node),
    "pretext-markdown:component-fallback"
  )
}

function pretextMarkdownMessagePoint(node: PretextMarkdownMdastNode) {
  const point = node.position?.start
  return typeof point?.line === "number" && typeof point.column === "number"
    ? { column: point.column, line: point.line }
    : null
}

function createPretextMarkdownComponentNode(
  component: PretextMarkdownComponent
): PretextMarkdownMdastNode {
  return {
    type: "pretextComponent",
    data: {
      hName: "div",
      hProperties: {
        dataPretextComponentName: component.name,
        dataPretextComponentProps: JSON.stringify(component.props),
      },
    },
    children: component.children ?? [],
  }
}

function createPretextMarkdownComponentFallbackNode({
  children = [],
  name,
  reason,
  source,
}: {
  children?: PretextMarkdownMdastNode[]
  name: string
  reason: string
  source: string
}): PretextMarkdownMdastNode {
  return {
    type: "pretextComponentFallback",
    data: {
      hName: "div",
      hProperties: {
        dataPretextComponentFallback: "",
        dataPretextComponentFallbackName: name,
        dataPretextComponentFallbackReason: reason,
        dataPretextComponentFallbackSource: source,
      },
    },
    children: [{ type: "text", value: source }, ...children],
  }
}

function createPretextMarkdownCalloutNode(
  node: PretextMarkdownMdastNode
): PretextMarkdownMdastNode {
  const kind = calloutKind(readDirectiveName(node))
  const attrs = readDirectiveAttributes(node) ?? {}
  const title =
    typeof attrs.title === "string" && attrs.title
      ? attrs.title
      : calloutTitle(kind)
  return {
    type: "pretextCallout",
    data: {
      hName: "div",
      hProperties: {
        dataPretextCalloutKind: kind,
        dataPretextCalloutTitle: title,
      },
    },
    children: node.children ?? [],
  }
}

// Splits an HTML block holding several self-closing component tags (only
// whitespace between them) into one node per tag: a component node when the tag
// parses, otherwise a fallback node — so one invalid tag never blanks the whole
// run. Returns null only when the block isn't entirely component tags (then
// normal HTML handling applies).
function splitPretextMarkdownComponentHtml(value: string, file: VFile) {
  const trimmed = value.trim()
  // Quote-aware so `>` inside an attribute value doesn't end a tag early.
  const tagPattern = /<[A-Z][A-Za-z0-9]*\b(?:[^>"']|"[^"]*"|'[^']*')*\/>/g
  const matches = [...trimmed.matchAll(tagPattern)]
  if (matches.length < 2) return null

  let cursor = 0
  for (const match of matches) {
    if (trimmed.slice(cursor, match.index).trim() !== "") return null
    cursor = match.index + match[0].length
  }
  if (trimmed.slice(cursor).trim() !== "") return null

  // Only treat the block as components when every tag names a known component.
  if (
    !matches.every((match) => {
      const name = componentNameFromHtml(match[0])
      return name !== null && isPretextMarkdownLeafComponentName(name)
    })
  ) {
    return null
  }

  return matches.map((match) => {
    const tag = match[0]
    const component = parsePretextMarkdownComponentHtml(tag)
    if (component) return createPretextMarkdownComponentNode(component)
    const reason = fallbackReasonForHtml(tag)
    emitPretextMarkdownComponentFallbackMessage({
      file,
      node: { type: "html", value: tag } as PretextMarkdownMdastNode,
      reason,
    })
    return createPretextMarkdownComponentFallbackNode({
      name: componentNameFromHtml(tag) ?? "Component",
      reason,
      source: tag,
    })
  })
}

function parsePretextMarkdownComponentHtml(value: string) {
  // Match exactly one self-closing tag: attribute chars are either non-quote/
  // non-`>` or fully-quoted strings, so `>` inside an attribute (e.g. a mermaid
  // `source="graph TD; A-->B"`) is allowed, while a multi-tag HTML block fails
  // here and is handled by splitPretextMarkdownComponentHtml.
  const match = /^<([A-Z][A-Za-z0-9]*)\b((?:[^>"']|"[^"]*"|'[^']*')*)\/>$/.exec(
    value.trim()
  )
  if (!match) return null
  const name = match[1]!
  const propsText = match[2]!
  if (!isPretextMarkdownLeafComponentName(name)) {
    return null
  }
  return parsePretextMarkdownComponentProps(
    name,
    parseComponentAttributes(propsText),
    []
  )
}

function parsePretextMarkdownDirectiveComponent(
  node: PretextMarkdownMdastNode
) {
  const name = componentNameForDirective(readDirectiveName(node))
  if (!name) return null
  return parsePretextMarkdownComponentProps(
    name,
    readDirectiveAttributes(node),
    node.children ?? []
  )
}

function parsePretextMarkdownComponentProps(
  name: string,
  props: Record<string, unknown> | null,
  children: PretextMarkdownMdastNode[]
): PretextMarkdownComponent | null {
  if (!props) return null
  if (Object.keys(props).some((key) => /^on/i.test(key))) return null

  if (name === "Diagram") {
    if (props.type !== "mermaid" || typeof props.source !== "string")
      return null
    return {
      name,
      props: {
        caption: readPropString(props.caption),
        source: normalizePretextMarkdownDiagramSource(props.source),
        title: readPropString(props.title),
        type: "mermaid",
      },
    }
  }
  if (name === "Metric") {
    if (!props.label || !props.value || props.tone) return null
    return {
      name,
      props: {
        label: readPropString(props.label),
        value: readPropString(props.value),
      },
    }
  }
  if (name === "Badge") {
    const label = readPropString(props.label) || mdastText(children)
    const tone = readPropString(props.tone)
    if (!label || (tone && !["default", "success", "warning"].includes(tone))) {
      return null
    }
    return { name, props: { label, tone } }
  }
  if (name === "Image") {
    if (!props.src || !props.alt) return null
    return {
      name,
      props: {
        alt: readPropString(props.alt),
        height: readPropString(props.height),
        src: readPropString(props.src),
        title: readPropString(props.title),
        width: readPropString(props.width),
      },
    }
  }
  if (name === "Video") {
    if (!props.src || !props.label) return null
    return {
      name,
      props: {
        controls: readPropString(props.controls),
        label: readPropString(props.label),
        loop: readPropString(props.loop),
        muted: readPropString(props.muted),
        src: readPropString(props.src),
        title: readPropString(props.title),
      },
    }
  }
  if (name === "Accordion") {
    if (!props.title) return null
    return { name, props: { title: readPropString(props.title) }, children }
  }
  if (name === "Callout") {
    const kind = calloutKind(readPropString(props.kind) || "note")
    return {
      name,
      props: {
        kind,
        title: readPropString(props.title) || calloutTitle(kind),
      },
      children,
    }
  }
  if (name === "Tabs" || name === "Tab") {
    return {
      name,
      props: {
        label: readPropString(props.label),
        title: readPropString(props.title),
      },
      children,
    }
  }
  return null
}

function normalizePretextMarkdownDiagramSource(source: string) {
  return source
    .split(/;\s*/)
    .map((line) => line.trim())
    .filter(Boolean)
    .join("\n")
}

function readDirectiveName(node: PretextMarkdownMdastNode) {
  const directive = node as unknown as { name?: unknown }
  return typeof directive.name === "string" ? directive.name : ""
}

function readDirectiveAttributes(node: PretextMarkdownMdastNode) {
  const attributes = (node as { attributes?: unknown }).attributes
  return attributes && typeof attributes === "object"
    ? (attributes as Record<string, unknown>)
    : null
}

function parseQuotedAttributes(value: string): Record<string, string> {
  return Object.fromEntries(
    Array.from(value.matchAll(/\s*([A-Za-z][A-Za-z0-9_]*)="([^"]*)"/g)).map(
      (item) => [item[1]!, item[2]!]
    )
  )
}

function parseComponentAttributes(value: string) {
  if (/\{\s*\.\.\./.test(value)) return null
  const attributes: Record<string, string> = {}
  const consumed: Array<[number, number]> = []
  for (const match of value.matchAll(
    /\s+([A-Za-z][A-Za-z0-9_]*)=(?:"([^"]*)"|\{(\d+(?:\.\d+)?|true|false)\})/g
  )) {
    attributes[match[1]!] = match[2] ?? match[3] ?? ""
    consumed.push([match.index ?? 0, (match.index ?? 0) + match[0].length])
  }
  for (const match of value.matchAll(/\s+([A-Za-z][A-Za-z0-9_]*)(?=\s|$)/g)) {
    const index = match.index ?? 0
    if (consumed.some(([start, end]) => index >= start && index < end)) {
      continue
    }
    attributes[match[1]!] = "true"
    consumed.push([index, index + match[0].length])
  }
  if (removeRanges(value, consumed).trim()) return null
  return attributes
}

function removeRanges(value: string, ranges: Array<[number, number]>) {
  let result = ""
  let offset = 0
  for (const [start, end] of ranges.sort((a, b) => a[0] - b[0])) {
    result += value.slice(offset, start)
    offset = end
  }
  return result + value.slice(offset)
}

function readPropString(value: unknown) {
  return typeof value === "string" ? value : ""
}

function mdastText(nodes: readonly PretextMarkdownMdastNode[]): string {
  return nodes
    .map((node) =>
      typeof node.value === "string"
        ? node.value
        : mdastText(node.children ?? [])
    )
    .join("")
}

function componentNameForDirective(name: string) {
  const normalized = name.toLowerCase()
  const names: Record<string, string> = {
    accordion: "Accordion",
    badge: "Badge",
    callout: "Callout",
    diagram: "Diagram",
    image: "Image",
    metric: "Metric",
    tab: "Tab",
    tabs: "Tabs",
    video: "Video",
  }
  return names[normalized] ?? null
}

function isPretextMarkdownLeafComponentName(name: string) {
  return ["Badge", "Diagram", "Image", "Metric", "Video"].includes(name)
}

function isPretextMarkdownContainerComponentName(name: string) {
  return Boolean(componentNameForDirective(name))
}

function isPretextMarkdownComponentHtml(value: string) {
  return /^<\/?[A-Z][A-Za-z0-9.]*(?:\b|\.)/.test(value.trim())
}

function componentNameFromHtml(value: string) {
  return /^<\/?([A-Z][A-Za-z0-9.]*)/.exec(value.trim())?.[1] ?? null
}

function hasEventHandlerAttribute(value: string) {
  return /\son[A-Za-z]+\s*=/.test(value)
}

function fallbackReasonForHtml(value: string) {
  const name = componentNameFromHtml(value)
  if (name?.includes(".")) {
    return "Remote or namespaced components are not supported"
  }
  if (!name || !componentNameForDirective(name)) return "Unsupported component"
  if (hasEventHandlerAttribute(value))
    return "Event handler props are not supported"
  if (value.includes("{")) return "Component props must be literal values"
  return "Unsupported component"
}

function sourceTextForMdastNode(node: PretextMarkdownMdastNode, file: VFile) {
  const value = String(file.value ?? "")
  const start = node.position?.start?.offset
  const end = node.position?.end?.offset
  if (
    typeof start !== "number" ||
    typeof end !== "number" ||
    start < 0 ||
    end < start
  ) {
    return ""
  }
  return value.slice(start, end)
}

function isCalloutKind(name: string) {
  return ["caution", "important", "note", "success", "tip", "warning"].includes(
    name.toLowerCase()
  )
}

function calloutKind(value: string) {
  const normalized = value.toLowerCase()
  if (normalized === "success") return "tip"
  if (isCalloutKind(normalized)) return normalized
  return "note"
}

function calloutTitle(kind: string) {
  const titles: Record<string, string> = {
    caution: "Caution",
    important: "Important",
    note: "Note",
    tip: "Tip",
    warning: "Warning",
  }
  return titles[kind] ?? "Note"
}

function directiveSourceForUnsafeComponent(node: PretextMarkdownMdastNode) {
  const name = readDirectiveName(node)
  const attrs = readDirectiveAttributes(node) ?? {}
  const attrSource = Object.entries(attrs)
    .map(([key, value]) => `${key}="${String(value)}"`)
    .join(" ")
  const marker = node.type === "textDirective" ? ":" : "::"
  return `${marker}${name}${attrSource ? `{${attrSource}}` : ""}`
}

"use client"

const URL_CONTROL_CHARACTER_PATTERN = /[\u0000-\u001F\u007F]/
const URL_SCHEME_PATTERN = /^([A-Za-z][A-Za-z0-9+.-]*):/
const URL_BACKSLASH_PATTERN = /[\\\uFE68\uFF3C\u2216]/
const URL_CONFUSABLE_DELIMITER_PATTERN =
  /[\u02D0\u0589\u05C3\u0703\u0704\u16EC\u1803\u1809\u205A\u2236\uA789\uFE13\uFE55\uFF1A\u2044\u2215\u2571\u27CB\u29F8\uFF0F]/
const ALLOWED_LINK_PROTOCOLS = new Set(["http", "https", "mailto"])

export function sanitizePretextMarkdownUrl(value: string) {
  const trimmed = value.trim()
  if (!trimmed) return ""
  if (URL_CONTROL_CHARACTER_PATTERN.test(trimmed)) return ""
  if (URL_BACKSLASH_PATTERN.test(trimmed)) return ""
  if (URL_CONFUSABLE_DELIMITER_PATTERN.test(trimmed)) return ""

  const decoded = decodePretextMarkdownUrl(trimmed).trim()
  if (!decoded || URL_CONTROL_CHARACTER_PATTERN.test(decoded)) return ""
  if (URL_BACKSLASH_PATTERN.test(decoded)) return ""
  if (URL_CONFUSABLE_DELIMITER_PATTERN.test(decoded)) return ""

  const decodedScheme = getPretextMarkdownUrlScheme(decoded)
  const rawScheme = getPretextMarkdownUrlScheme(trimmed)
  if (decodedScheme && decodedScheme !== rawScheme) return ""
  if (decodedScheme && !ALLOWED_LINK_PROTOCOLS.has(decodedScheme)) return ""

  if (trimmed.startsWith("#")) return trimmed
  if (trimmed.startsWith("/")) return trimmed.startsWith("//") ? "" : trimmed

  try {
    const url = new URL(trimmed, "https://retab.local")
    if (ALLOWED_LINK_PROTOCOLS.has(url.protocol.slice(0, -1))) {
      return trimmed
    }
  } catch {
    return ""
  }

  return ""
}

export function sanitizePretextMarkdownImageUrl(value: string) {
  const safeUrl = sanitizePretextMarkdownUrl(value)
  if (!safeUrl || safeUrl.startsWith("mailto:") || safeUrl.startsWith("#")) {
    return ""
  }
  if (isPretextMarkdownSvgResourceUrl(safeUrl)) return ""
  return safeUrl
}

export function sanitizePretextMarkdownMediaUrl(value: string) {
  // Image URLs already reject SVG resources, so media inherits that policy.
  return sanitizePretextMarkdownImageUrl(value)
}

function decodePretextMarkdownUrl(value: string) {
  try {
    return decodeURIComponent(value)
  } catch {
    return value
  }
}

function getPretextMarkdownUrlScheme(value: string) {
  return URL_SCHEME_PATTERN.exec(value)?.[1]?.toLowerCase() ?? null
}

export function isPretextMarkdownSvgResourceUrl(value: string) {
  const decoded = decodePretextMarkdownUrl(value).trim()

  try {
    const url = new URL(decoded, "https://retab.local")
    return /\.(?:svg|svgz)$/i.test(url.pathname)
  } catch {
    const pathname = decoded.split(/[?#]/, 1)[0] ?? decoded
    return /\.(?:svg|svgz)$/i.test(pathname)
  }
}
